window.CORE = {"abilities":[{"id":"m001","b":"通用","n":"屬性豁免(力量/敏捷/體質/智力/感知/魅力)","c":1500,"t":["角色獲得所選的屬性豁免熟練。"]},{"id":"m002","b":"通用","n":"力量成長","c":1500,"rep":1,"t":["角色的屬性值:力量增加 2 點(力量屬性最高 20)"]},{"id":"m003","b":"通用","n":"敏捷成長","c":1500,"rep":1,"t":["角色的屬性值:敏捷增加 2 點(敏捷屬性最高 20)"]},{"id":"m004","b":"通用","n":"體質成長","c":2000,"rep":1,"t":["角色的屬性值:體質增加 2 點(體質屬性最高 20)"]},{"id":"m005","b":"通用","n":"感知成長","c":1500,"rep":1,"t":["角色的屬性值:感知增加 2 點(體質屬性最高 20)"]},{"id":"m006","b":"通用","n":"智力成長","c":1500,"rep":1,"t":["角色的屬性值:智力增加 2 點(體質屬性最高 20)"]},{"id":"m007","b":"通用","n":"魅力成長","c":1500,"rep":1,"t":["角色的屬性值:魅力增加 2 點(體質屬性最高 20)"]},{"id":"m008","b":"通用","n":"XX(技能)熟練","c":500,"t":["角色獲得所選的 XX 技能熟練。"]},{"id":"m009","b":"通用","n":"OO(遊戲套組/樂器)熟練","c":500,"t":["角色獲得所選的 OO 熟練。"]},{"id":"m010","b":"通用","n":"△△(工具組)熟練","c":2000,"t":["角色獲得所選的△△工具組熟練。"]},{"id":"m011","b":"通用","n":"回氣","c":1000,"t":["你擁有有限的充沛精力讓你得以利用於保護自己不受傷害。","在你的回合，你可以使用一個附贈動作以回復等同於 1/2 最大生命值的生命值。一旦你使用此能力，你必須完成長休後才能再使用它。"]},{"id":"m012","b":"通用","n":"動作如潮","c":1000,"t":["在你的回合在你完成原本的主要動作和可能的附贈動作之後，另外再採取一次額外的主要動作。","你必須完成短休後才能再次使用此能力。"]},{"id":"m013","b":"通用","n":"不屈","c":1000,"t":["你可以在你一次失敗的豁免檢定中重骰。若你這麼做，你必須使用新的擲骰結果。","你必須完成短休後才能再次使用此能力。"]},{"id":"m014","b":"通用","n":"戰術思維","c":1500,"t":["你的先攻檢定額外獲得等同於你的智力調整值的加值。"]},{"id":"m015","b":"通用","n":"鼓舞戰吼","c":1500,"req":"具有能力[【通用】回氣]","refs":[{"b":"通用","n":"回氣"}],"need":1,"t":["你學會如何激勵你的盟友們戰勝他們過去的傷害。","當你使用你的回氣能力，你可以選取最多三個距離你 60 尺內的友方的生物。只要他們可以看見或聽見你，他們將各自獲得你魅力調整值五倍的[臨時生命值]。"]},{"id":"m016","b":"通用","n":"強攻戰吼","c":1000,"req":"具有能力[【通用】回氣]","refs":[{"b":"通用","n":"回氣"}],"need":1,"t":["你學會如何激勵你的盟友們去攻擊敵人。","當你使用你的回氣能力，你可以選取三個距離你 60 尺內的友方的生物。只要它可以看見或聽見你，該生物就能夠以它的反應進行一次近戰、遠程武器攻擊或魔法攻擊。"]},{"id":"m017","b":"通用","n":"堅壁戰吼","c":1500,"req":"具有能力[【通用】回氣]","refs":[{"b":"通用","n":"回氣"}],"need":1,"t":["你學會如何激勵你的盟友們去防禦敵人的攻擊。","當你使用你的回氣能力，你可以選取三個距離你 60 尺內的友方的生物。只要它可以看見或聽見你，該生物直到下的你下個回合結束前護甲等級(AC)+2。"]},{"id":"m018","b":"通用","n":"威嚇戰吼","c":2000,"req":"具有能力[【通用】回氣]","refs":[{"b":"通用","n":"回氣"}],"need":1,"t":["你學會如何使敵方的意志崩潰。","當你使用你的回氣能力，你可以選取 5 個距離你 60 尺內且的友方的生物。只要它可以看見或聽見你，其需要進行一次 DC=(8+你 2 倍熟練值)的感知豁免，如失敗，直到目標結束回合時期將無法移動及使用反應。"]},{"id":"m019","b":"通用","n":"不屈戰吼","c":1500,"req":"具有能力[【通用】回氣]","refs":[{"b":"通用","n":"回氣"}],"need":1,"t":["你學會如何激勵你的盟友們去對抗未知。","當你使用你的回氣能力，你可以選取三個距離你 60 尺內且的友方的生物。只要它可以看見或聽見你，該生物的下一次的豁免具有優勢。"]},{"id":"m020","b":"通用","n":"巨聲戰吼","c":1000,"t":["當你擁有「戰吼」之名的能力時，可選擇的生物數量增加 2 個。"]},{"id":"m021","b":"通用","n":"自勵戰吼","c":1000,"t":["當你使用「戰吼」之名的能力時，你可以選擇自己。"]},{"id":"m022","b":"通用","n":"宿敵","c":500,"t":["你在對一個特定類別的敵人的研究、追跡、狩獵、和甚至交談上已相當具備充足的經驗。","選取一個宿敵類別：異怪、野獸、天界生物、構裝體、龍、元素、精類、邪魔、巨人、怪獸、泥怪、植物或不死生物。或者，你可以選取二個類人生物種族（像是豺狼人和獸人）作為宿敵。","你在用於追蹤你宿敵的感知（生存）檢定、以及用以回憶關於它們情報的智力檢定中具有優勢。","當你獲得此能力時，若你的宿敵擁有至少一種語言，你也選取學會一種被它們所使用的語言。"]},{"id":"m023","b":"通用","n":"宿敵強化Ⅰ","c":500,"req":"具有能力[【通用】宿敵]","refs":[{"b":"通用","n":"宿敵"}],"need":1,"t":["選取一個宿敵類別：異怪、野獸、天界生物、構裝體、龍、元素、精類、邪魔、巨人、怪獸、泥怪、植物或不死生物。或者，你可以選取二個類人生物種族（像是豺狼人和獸人）作為宿敵。"]},{"id":"m024","b":"通用","n":"宿敵強化Ⅱ","c":500,"req":"具有能力[【通用】宿敵強化Ⅰ]","refs":[{"b":"通用","n":"宿敵強化Ⅰ"}],"need":1,"t":["選取一個宿敵類別：異怪、野獸、天界生物、構裝體、龍、元素、精類、邪魔、巨人、怪獸、泥怪、植物或不死生物。或者，你可以選取二個類人生物種族（像是豺狼人和獸人）作為宿敵。"]},{"id":"m025","b":"通用","n":"宿敵獵手","c":1000,"req":"具有能力[【通用】宿敵]","refs":[{"b":"通用","n":"宿敵"}],"need":1,"t":["每回合一次，攻擊命中你的[宿敵]時，額外造成 1D6 的傷害。"]},{"id":"m026","b":"通用","n":"宿敵迴避","c":1000,"req":"具有能力[【通用】宿敵]","refs":[{"b":"通用","n":"宿敵"}],"need":1,"t":["每回合一次，當你的[宿敵]攻擊命中你時，你能使此次攻擊傷害減少 1D6。"]},{"id":"m027","b":"通用","n":"宿敵屠戮者","c":1500,"req":"具有能力[【通用】宿敵獵手]或[【通用】宿敵迴避]的其中一個","refs":[{"b":"通用","n":"宿敵獵手"},{"b":"通用","n":"宿敵迴避"}],"need":1,"t":["你成為了一名針對你的[宿敵]的無雙獵手。","在你的每個回合一次，你可以將你的感知調整值加到你對你其中一個[宿敵]所進行的攻擊檢定或傷害骰中。你可以選取在擲骰之前或之后使用此能力，但是必須在任何擲骰效果適用之前使用。"]},{"id":"m028","b":"通用","n":"原初意志","c":500,"t":["你可以使用你的動作並消耗 1[魔力]以集中你的意識於你周遭的區域。在 1 分鐘內，你可以感知下列類別的生物是否存在於距離你 1 裡內的區域：異怪、天界生物、龍、元素、精類、邪魔、和不死生物。此能力無法揭露出該生物的位置和數量。"]},{"id":"m029","b":"通用","n":"不知疲倦","c":2000,"t":["以一個動作，你能夠給予自己 1d8 + 你的感知調整值的臨時生命值（最少 1 點）。你能夠使用此能力的次數等於你的體質調整值，已消耗的次數可以通過完成一次長休進行回復。","此外，每當你完成一次短休時，你的力竭等級減少 1（若有）。"]},{"id":"m030","b":"通用","n":"野性感官","c":2000,"t":["你獲得超自然的感官以輔助說明你對抗看不見的生物。當你攻擊一個你看不見的生物時，你並不會因為無法看見它而在你對它進行的攻擊檢定中承受[劣勢]。同時，只要該生物沒有躲藏於你，且你不處於[目盲]或[耳聾]狀態，則你也能察覺到任何距離你 30 尺內[隱形]生物的位置。"]},{"id":"m031","b":"通用","n":"鋼鐵心智","c":500,"req":"具有能力[【靈敏】幽影追蹤者]","refs":[{"b":"靈敏","n":"幽影追蹤者"}],"need":1,"t":["你已磨練出用於抵抗來自於你獵物的精神影響力量的能力。","你獲得感知豁免的熟練。若你已經擁有此熟練，則你可以改為獲得智力豁免或魅力豁免的熟練（由你選取）。"]},{"id":"m032","b":"通用","n":"偵測傳送門","c":2000,"t":["你獲得以魔法感知位面傳輸門存在的主要動作。以一個動作，你偵測出距離你 100 哩內最近的傳輸門的距離以及方位。","一旦你使用此能力，直到你完成一次長休之前你都無法再使用它。"]},{"id":"m033","b":"通用","n":"位面戰士","c":1500,"t":["以一個附贈動作，選取一個距離你 30 尺內且你所能看見的生物。你在該回合下一次攻擊命中該生物時，該攻擊所造成的所有傷害都將變成力場傷害，且該生物將受到來自你的攻擊傷害會額外增加 1d8 的力場傷害。"]},{"id":"m034","b":"通用","n":"位面戰士-位面之力","c":1000,"req":"具有能力[【通用】位面戰士]","refs":[{"b":"通用","n":"位面戰士"}],"need":1,"t":["[位面戰士]所增加 1D8 力場傷害，變為 2D8。"]},{"id":"m035","b":"通用","n":"逃離眾敵","c":2000,"t":["所有對你進行的藉機攻擊將具有劣勢。"]},{"id":"m036","b":"通用","n":"防禦多重攻擊","c":2000,"t":["當一個生物以一次攻擊命中你時，你的護甲等級(AC)將對該生物在該回合中所進行的所有后續攻擊獲得 +4 的加值。"]},{"id":"m037","b":"通用","n":"遠離恐懼","c":500,"t":["你在對抗[恐懼]的豁免檢定中具有優勢。"]},{"id":"m038","b":"通用","n":"逆潮而立","c":1500,"t":["當一個敵對生物對你進行的一次近戰攻擊失手，你可以使用你的反應以強迫該生物對你所選取的另一個生物（除了它自己以外）重複進行一次該攻擊。"]},{"id":"m039","b":"通用","n":"獵者感知","c":1000,"t":["你獲得凝視一個生物並以魔法知悉傷害它最佳的方式的能力。以一個動作，選取一個距離你 60 尺內且你所能看見的生物。你將立刻知道該生物是否擁有任何傷害免疫、抗性、或是易傷，以及它們的種類。若該生物不受預言系魔法影響，則你感知到的結果將會是它不具有任何傷害免疫、抗性和易傷。","你可以使用此能力的次數等同於你的感知調整值（最少 1 次）。你在完成一次長休后回復所有你消耗掉的次數。"]},{"id":"m040","b":"通用","n":"獵者","c":1500,"t":["你可以專注你的憤怒於單一敵人，增加你對它所造成的傷害。以一個附贈動作，你指定一個距離你 60 尺內且你所能看見的生物作為此能力的目標。之後每個回合當你第一次以武器攻擊命中目標時，它將額外受到來自該武器的 1d6 傷害。","你指定另一個不同生物作為目標時此效果提早結束。","你可以使用此能力的次數等同於你的感知調整值（最少 1 次）。你在完成一次長休后回復所有你消耗掉的次數。"]},{"id":"m041","b":"通用","n":"超常防禦","c":1000,"req":"具有能力[【通用】獵者]","refs":[{"b":"通用","n":"獵者"}],"need":1,"t":["你獲得其餘的韌性以抵抗你獵物對你身體和精神所做出的侵襲。","每當被你[獵者]所指定的目標強迫你進行一次豁免檢定時，骰 1D6 並將其加入你的擲骰結果中。"]},{"id":"m042","b":"通用","n":"獵物阻饒","c":1000,"req":"具有能力[【通用】獵者]","refs":[{"b":"通用","n":"獵者"}],"need":1,"t":["你獲得如何使你鎖定獵物不自在的能力。","每當被你[獵者]所指定的目標攻擊時，你可以一個反應使其此回合的所有攻擊命中減少 1D6。","每當被你[獵者]所指定的目標使用法術時，你可以一個反應使其須通過 DC=(8+你的熟練+感知調整值)的感知豁免，否則它的法術將失敗並被浪費。一旦你使用此能力，直到你完成一次短休或長休之前你都無法再使用它。"]},{"id":"m043","b":"通用","n":"殺手反制","c":1000,"req":"具有能力[【通用】獵者]","refs":[{"b":"通用","n":"獵者"}],"need":1,"t":["你獲得在你的獵物嘗試妨害你時展開反擊的能力。","若你被你[獵者]所指定的目標強迫你進行一次豁免檢定，你可以使用你的反應以對該獵物進行一次武器攻擊。你在進行該豁免檢定之前立刻進行此攻擊。若你的攻擊命中，則除了該攻擊原本的效果之外，你的豁免檢定也將自動成功。"]},{"id":"m044","b":"通用","n":"手穩就准","c":1000,"t":["使用一個附贈動作，你在目前回合為你的下一次攻擊將具有優勢。你只能在你本回合還沒有移動的時候使用這個附贈動作，而且在你使用這個附贈動作后，你的速度在目前回合裡歸零。"]},{"id":"m045","b":"通用","n":"盲感","c":1000,"t":["若你能夠聽見，則你能夠察覺到任何距離你 10 尺內躲藏起來或隱形的生物所在的位置。"]},{"id":"m046","b":"通用","n":"可靠才能","c":2500,"t":["每當你進行一個允許你加入你熟練加值的技能檢定，你可以將其 d20 骰出 9 或以下的擲骰結果視為 10。"]},{"id":"m047","b":"通用","n":"幸運一擊","c":3000,"t":["你有着在你需要的時候成功的神奇訣竅。","若你對一個生物的攻擊失手時，你可以將該次攻擊從失手改成命中。或者，若你在一次屬性檢定中失敗，你可以將其 D20 的擲骰結果視作骰出了 20。","一旦你使用此能力，你直到完成一次短休或長休前都不能再使用它。"]},{"id":"m048","b":"通用","n":"專業滲透","c":1000,"t":["你可以為自己創造出可靠的假身分。你必須花費七天的時間和 500 DP 以為該身分編造曆史紀錄、職業、以及人際關系。你無法編造一個屬於他人的身分。舉例來說，你可能會需要取得相應的服裝、介紹信、以及看似官方的證明文檔，來為自己創建一個來自偏遠城市商行成員的身分，並使你得以混入其他富商團體中。","在這之后，若你採用該身分作為偽裝，其他生物將會相信你就是那個人，直到另有明顯證據證明你不是。"]},{"id":"m049","b":"通用","n":"冒充者","c":1500,"req":"具有能力[【通用】專業滲透]","refs":[{"b":"通用","n":"專業滲透"}],"need":1,"t":["你獲得准確模仿其他人說話、書寫、和行為舉止的能力。你必須花費至少三個小時的時間以研究該人物行為中的這三個要素：聆聽他的說話腔調、查看字跡、以及觀察舉止習慣。","你的詭計對尋常觀察者而言難以分辨。若一個謹慎的生物因一些模仿缺陷而開始懷疑，則你在任何你用以避免被察覺所進行魅力（欺瞞）檢定中具有優勢。"]},{"id":"m050","b":"通用","n":"審訊者","c":1500,"t":["你發展出了分辨謊言的天賦。每當你進行一次感知（洞悉）檢定以辨別一個生物是否說謊時，你將 d20 骰出的 7 或更低的擲骰結果視作骰出 8。","你可以使用一個附贈動作以進行一次感知（感知）檢定以發現隱藏的生物或物體，或進行一次智力（調查）檢定以揭示或破譯線索。"]},{"id":"m051","b":"通用","n":"穩定之眼","c":500,"t":["若你移動不超過你移動速度一半的距離，你在同個回合所進行的任何感知（察覺）或智力（調查）檢定中具有優勢。"]},{"id":"m052","b":"通用","n":"精準之眼","c":1000,"t":["你的感知能力機乎不可能被挫敗。","以一個動作，只要你不處於目盲或耳聾狀態，你就可以感知到距離你 30 尺內的幻象的存在、不處於它原本型態的變形者、以及其他用以欺瞞感官的魔法。你能感知到正嘗試欺騙你的效果，但你無法得知它所隱藏的事物或它真正的性質。","你可以使用這個能力的次數等同於你的感知調整值（最少一次），且你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m053","b":"通用","n":"戰術大師","c":1000,"t":["你能夠以一個附贈動作採取協助動作。此外，當你使用協助動作以援助盟友攻擊一個生物時，若目標可以看見或聽見你，則該攻擊的目標可以在距離你 30 尺內的位置，而非原本的 5 尺內。"]},{"id":"m054","b":"通用","n":"誤導攻擊","c":1000,"t":["你有時可以讓另一個生物代為承受針對你的攻擊。當你被一次攻擊指定為目標，且有一個距離你 5 尺內的生物，則你可以使用你的反應以讓該攻擊改為指定該生物作為目標。"]},{"id":"m055","b":"通用","n":"無甲防禦-剛","c":1000,"t":["當你未穿戴護甲時，你的 AC 等於 10 + 你的敏捷調整值 + 你的體質調整值。你可以使用盾牌而仍獲得這個好處。"]},{"id":"m056","b":"通用","n":"無甲防禦-巧","c":1000,"t":["當你未穿戴護甲時，你的 AC 等於 10 + 你的敏捷調整值 + 你的感知調整值。你可以使用盾牌而仍獲得這個好處。"]},{"id":"m057","b":"通用","n":"險境感知","c":1500,"t":["你獲得一種能查覺到周遭異狀的超常感知能力，讓你在躲避危險時掌握先機。","你在對抗你所能見的效果時所進行的敏捷豁免中具有優勢，像是陷阱和法術。要獲得此好處，你不能處於目盲、耳聾或無力狀態。"]},{"id":"m058","b":"通用","n":"魔法之拳","c":500,"t":["你的徒手攻擊被同時視為魔法攻擊。"]},{"id":"m059","b":"通用","n":"心頭滅卻","c":1000,"t":["你可以使用一個動作以結束一個讓你被魅惑或[恐懼]的效果。"]},{"id":"m060","b":"通用","n":"百病不侵","c":3000,"t":["你免疫於疾病和毒素傷害（包含中毒狀態）。"]},{"id":"m061","b":"通用","n":"劍聖之途","c":1500,"req":"具有能力[【武力】武藝]","refs":[{"b":"武力","n":"武藝"}],"need":1,"t":["你特殊的武術訓練讓精通於你特定武器的使用。你獲得下列好處。","• 劍聖武器. 選擇二種武器作為你的劍聖武器：一種近戰武器和一種遠程武器。這些武器可以是任何沒有重型或特殊屬性的簡易或軍用武器，包括長弓也是可選選項之一。若你尚未熟練於這些武器，則你獲得它們的熟練。","• 靈巧格檔. 若你在你的回合以攻擊動作的一部份進行了一次徒手攻擊，且你正持握一把劍聖武器，則若該武器是一把近戰武器，你將可以用它來保護自己。當該武器在你中且你未陷入無力狀態，你的 AC 獲得+2 加值直到你的下個回合開始。","• 劍聖神射.你可以在你的回合使用一個附贈動作讓你通過劍聖武器所進行遠程攻擊變得更加致命。當你這麼做時，任何被你以劍聖武器所進行的遠程攻擊命中的目標將會受到額外的 1d4 該武器傷害類型的傷害。你保留這個好處直到該回合結束。"]},{"id":"m062","b":"通用","n":"劍聖武器增加","c":500,"req":"具有能力[【通用】劍聖之途]","refs":[{"b":"通用","n":"劍聖之途"}],"need":1,"rep":1,"t":["你的劍聖武器數目增加 2。"]},{"id":"m063","b":"通用","n":"人劍合一","c":1000,"req":"具有能力[【通用】劍聖之途]及[【特殊】氣]","refs":[{"b":"通用","n":"劍聖之途"},{"b":"特殊","n":"氣"}],"need":2,"t":["你將你的氣延展至你的劍聖武器中，賦予你下列好處。","• 魔法劍聖武器. 在克服對非魔法攻擊和傷害的抗性和免疫能力時，你以劍聖武器所進行的攻擊被視作魔法攻擊。","• 機敏打擊. 當你以劍聖武器命中一個目標時，你可以消耗 1 點氣以讓該武器對目標造成等同於你武藝骰的額外傷害。你只能在你的每個回合使用這個能力一次。"]},{"id":"m064","b":"通用","n":"心靈防禦","c":3000,"t":["你對心靈傷害獲得抗性。此外，你在對抗魅惑或[恐懼]的豁免檢定上獲得優勢。"]},{"id":"m065","b":"通用","n":"強效治療","c":1500,"t":["奔馳於你體內的神聖能量可以強化治療法術。","每當你或一個距離你 5 尺內的盟友擲骰決定一個法術所回復的生命值數值時，只要你並非處於無力狀態，你就可以消耗 1[魔力]以重骰任意數量的這些骰子一次。你每個回合只能使用此能力一次。"]},{"id":"m066","b":"通用","n":"超凡之翼","c":2000,"t":["你可以使用一個附贈動作以從你背后展現出一對靈體翅膀。當這對翅膀存在時，你擁有 30 尺的飛行速度。這對翅膀會持續存1 分鐘或直到你陷入無力狀態、死亡、或你以一個附贈動作解消它們。","你為你神聖魔法能力所選擇的傾向，將會決定這對靈體翅膀的外觀：善良或守序則為鷹翼、邪惡或混亂則為蝙蝠翅膀、中立則為蜻蜓翅膀。","你可以使用這個能力的次數等同於你的感知調整值（最少一次），且你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m067","b":"通用","n":"神秘療愈","c":2500,"t":["你獲得為幫助他人克服嚴重傷勢的能力。","當 5 尺內的一名生物(不包含自己)只剩下少於一半的生命值時，以一個動作，你可以為周圍 5 尺內的所有友方生物(不包含自己)回復你生命值最大值一半的生命值。","一旦你使用此能力，直到你完成一次長休前都不能再使用它。"]},{"id":"m068","b":"通用","n":"龍之血脈","c":2500,"t":["選擇下面一個龍種作為你的龍族血統:","龍種傷害種類","黑龍酸蝕","藍龍閃電","黃銅龍火焰","青銅龍閃電","赤桐龍酸蝕","金龍火焰","綠龍毒素","紅龍火焰","銀龍冰冷","白龍冰冷","每當你在與龍族交互時進行魅力檢定，若你的熟練加值能適用於該檢定，你的熟練加值變為二倍。","你龍族血統的物理特徵開始浮現。你的生命值最大值增加 1 點，且每當你在習得能力時都會再增加 1 點。","你一部份的肌膚將會被輕薄、龍族般的光滑鱗片給覆蓋。當你未穿戴護甲時，你的 AC 等於 13 + 你的敏捷調整值。","你指尖長出可伸縮的爪子。這對爪子是你可以用來進行徒手打擊的天生武器。如果你用它們命中目標，你造成等同於 1d4 + 你的力量調整值的揮砍傷害，而非原本徒手打擊的鈍擊傷害。"]},{"id":"m069","b":"通用","n":"終焉之眼","c":1000,"req":"具有能力[【特殊】終焉之力]","refs":[{"b":"特殊","n":"終焉之力"}],"need":1,"t":["你具有 120 尺範圍的黑暗視覺。"]},{"id":"m070","b":"通用","n":"神力引導﹝驅散不死﹞","c":500,"req":"具有能力[【特殊】神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["以一個動作並消耗一個神力引導使用次數，你展現你的聖徽並說出斥責不死生物的禱詞。每個距離你 30 尺內且可以看見或聽見你的不死生物必須進行一次感知豁免。若該生物豁免失敗，則它將被驅散長達 1 分鐘或直到它受到傷害。","一個被驅散的不死生物必須用它的回合嘗試盡可能的遠離你，且它無法自願的移動到距離你 30 尺內的空間。它無法採取反應。它的動作只能使用疾走動作或嘗試掙脫阻止它移動的效果。若它無法移動，則該生物將使用閃避動作。"]},{"id":"m071","b":"通用","n":"摧毀不死","c":2000,"req":"具有能力[【通用】神力引導﹝驅散不死﹞]","refs":[{"b":"通用","n":"神力引導﹝驅散不死﹞"}],"need":1,"t":["當一個不死生物在對抗你驅散不死能力的豁免檢定中失敗，該生物將立即被摧毀。"]},{"id":"m072","b":"通用","n":"神力引導﹝知識之井﹞","c":1500,"req":"具有能力[【特殊】]神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["你可以使用你的神力引導以進入知識的神聖之井。以一個動作消耗一個神力引導，你選擇一項技能或工具。在 10 分鐘內，你將熟練於所選的技能或工具。"]},{"id":"m073","b":"通用","n":"知識祝福","c":1000,"req":"具有能力[【通用】神力引導﹝知識之井﹞]","refs":[{"b":"通用","n":"神力引導﹝知識之井﹞"}],"need":1,"t":["你也變得熟練於二個從下列選項中自選的技能：奧秘、歷史、自然或宗教。你的熟練加值在使用這些技能所進行的任何屬性檢定中變為兩倍。"]},{"id":"m074","b":"通用","n":"神力引導﹝雷電狂怒﹞","c":1500,"req":"具有能力[【特殊】神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["你可以使用你的神力引導以施加不受控的凶猛暴風之力。","當你擲骰決定閃電或雷鳴傷害時，你可以使用你的神力引導，不擲骰而改為直接造成最大傷害。"]},{"id":"m075","b":"通用","n":"雷電猛擊","c":1500,"req":"具有能力[【通用】神力引導﹝雷電狂怒﹞]","refs":[{"b":"通用","n":"神力引導﹝雷電狂怒﹞"}],"need":1,"t":["一回合一次，當你對一個體型為大型或更小的生物造成閃電或雷鳴傷害時，你也可以將它推離你最多 10 尺距離。"]},{"id":"m076","b":"通用","n":"黑夜明目","c":3000,"req":"具有能力[【特殊】神力引導﹝暮光聖域﹞]","refs":[{"b":"特殊","n":"神力引導﹝暮光聖域﹞"}],"need":1,"t":["你的雙眼可以洞穿最深沉的黑暗。","你獲得 300 尺的黑暗視覺，而你的視力在微光光照下視為等同於明亮光照，而在黑暗中則視為等同於微光光照。","以一個主要動作，你可以用魔法將黑暗視覺分享給你 10 尺內最多等同於你感知調整值數量（最少 1 名生物）的可見自願生物。共享的黑暗視覺持續 1 小時。一旦如此做，直到你完成一次長休或消耗 1[魔力]，你無法再次分享此特性。"]},{"id":"m077","b":"通用","n":"驚覺賜福","c":1500,"req":"具有能力[【特殊】神力引導﹝暮光聖域﹞]","refs":[{"b":"特殊","n":"神力引導﹝暮光聖域﹞"}],"need":1,"t":["夜晚教會了你時刻保持警惕。你能用一個主要動作觸碰一個生物（包括你自己），並賦予該生物下次先攻檢定優勢。此增益在該生物骰先攻檢定或你再次使用此特性后立刻結束。","你可以使用這個能力的次數等同於你的感知調整值（最少一次），且你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m078","b":"通用","n":"神聖感知","c":1500,"t":["強大的邪惡對你來說就像是令人作嘔的臭氣，而強大的善良在你的耳中就如同仙樂般鳴響。以一個主要動作，你可以擴張你的意識以偵測這類力量。直到你的下個回合結束前，你知曉任何距離你 60 尺內，且未處於全掩護的天界生物、邪魔、或不死生物的位置。你知曉被你感知到的存在的種類（天界生物、邪魔、或不死生物），但無法知曉它的身分（例如吸血鬼伯爵，斯特拉德·馮·扎洛維奇）。在同樣的範圍內，你也可以偵測到任何被像是聖居法術給祝聖或褻瀆的場所或物體。","你可以使用這個能力的次數等同於 1 + 你的魅力調整值。當你完成一次長休，你回復所有你花費掉的次數。"]},{"id":"m079","b":"通用","n":"不屈之魂","c":2000,"req":"具有能力[【特殊】神力引導﹝捍衛挑戰﹞]","refs":[{"b":"特殊","n":"神力引導﹝捍衛挑戰﹞"}],"need":1,"t":["你在用於避免麻痺或震懾的豁免檢定中具有優勢。"]},{"id":"m080","b":"通用","n":"荒野形態","c":1500,"t":["你可以使用你的主要動作變成一個你曾經見過大型(含)以下野獸的型態。你可以使用這個能力二次。你在完成一次短休或長休后回復所有你花費掉的次數。","你可以保持野獸型態長達等同於你熟練值二倍的小時數。你接着將回復你原本的型態，除非你再花費此能力的一個次數。你可以通過在你的回合使用一個附贈動作以提早回復你原本的型態。你將在你陷入昏迷、生命值歸零、或死亡時自動回復原本的型態。","當你變形后，適用以下規則：","• 你的游戲數據被該野獸的數據給取代，但你保留你的陣營、個性，和智力、感知、和魅力值。你同時也保留你的所有技能和豁免熟練，並額外獲得該生物所具有的熟練。若該生物具有與你相同的熟練項，且它數據數據中列出的加值比你的還要高，則你使用該生物的加值取代你自己的。若該生物具有任何傳奇動作或巢穴動作，你不能使用它們。","• 當你變形時，你取用該野獸的生命值和生命骰。當你回復你原本的型態時，你將取回你變形之前的生命值。若你是因為生命值歸零而回復原本型態，則任何溢出傷害都將被帶到你原本的型態，扣減你原本的生命值。舉例來說，若你在處於動物型態時受到 10 點傷害，且只剩下 1 點生命值，你將回復原本的型態並承受 9 點傷害。只要這個溢出傷害沒有讓你原本型態的生命值歸零，你就不會被擊倒昏迷。","• 你不能施放法術，且你說話或採取任何需要雙手的動作的能力將受限於你的野獸型態。然而，變形並不會中斷你對已施放法術的專注，也不會讓你無法採取你已經施放法術所提供的動作，像是召雷術。","• 你保留任何來自你職業、種族、或其他來源的能力，且若新型態物理上有能力這麼做，你就能夠使用它們。然而，你無法使用你的特殊感官，像是黑暗視覺，除非你的新型態也具有該感官。","• 你選擇你的裝備是會掉在地上、融入新型態、或是被新型態穿戴。被穿戴的裝備將正常生效，但 DM 將根據該生物的體型和形狀以決定新型態是否可以正常穿戴你的每個裝備。你的裝備並不會改變形狀或尺寸以符合你的新形態，且任何新型態無法穿戴的裝備將會掉在地上或融入新型態。直到你解除該型態前，融入新型態的裝備將不會產生任何效果。","• 根據變形野獸的挑戰等級不同你需要花費更多的荒野形態變形次數來變身。","◦ 挑戰等級 0~5 一次。","◦ 挑戰等級 6~10 兩次。","◦ 挑戰等級 11~15 三次。","◦ 挑戰等級 15~20 四次。","◦ 挑戰等級 21 以上五次。"]},{"id":"m081","b":"通用","n":"荒野共鳴","c":1000,"req":"具有能力[【通用】荒野形態]","refs":[{"b":"通用","n":"荒野形態"}],"need":1,"rep":1,"t":["你使用荒野形態能力的次數增加 1 次。"]},{"id":"m082","b":"通用","n":"戰鬥荒野形態","c":1500,"req":"具有能力[【通用】荒野形態]","refs":[{"b":"通用","n":"荒野形態"}],"need":1,"t":["你獲得在你的回合以一個附贈動作，而非一個動作來使用荒野形態的變形能力。","當你通過荒野型態而處於變形狀態時，你可以使用一個附贈動作以消耗[魔力]，回復等同於被消耗[魔力] d12 點的生命值。"]},{"id":"m083","b":"通用","n":"自然之護","c":3500,"t":["你將不會被元素或精類生物給魅惑或[恐懼]，且你將免疫於疾病和毒素傷害（包含中毒狀態）。"]},{"id":"m084","b":"通用","n":"吟遊激勵","c":1500,"t":["你可以用振奮人心的言詞或音樂來激勵其他生物。在你的回合中使用一個附贈動作來選擇一個除你之外，距離你 60 尺內且可以聽見你的生物，該生物獲得一個吟游激勵骰 d6。","在接下來的 10 分鐘內，該生物可以骰這顆激勵骰，並將骰出來的數字加到它所進行的一次屬性檢定、攻擊檢定、或豁免檢定中。該生物可以在骰 d20 之后才決定是否使用使用吟游激勵骰，但必須在 DM 宣布該檢定結果之前使用。一旦吟游激勵骰被使用，它就消失。且一個生物同時只能擁有一顆吟游激勵骰。","你可以使用這個能力的次數等同於你的魅力調整值+你的熟練值。你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m085","b":"通用","n":"吟遊激勵強化","c":2000,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["吟游激勵骰由 d6→d8。"]},{"id":"m086","b":"通用","n":"吟遊激勵強化Ⅱ","c":3000,"req":"具有能力[【通用】吟遊激勵強化]","refs":[{"b":"通用","n":"吟遊激勵強化"}],"need":1,"t":["吟游激勵骰由 d8→d12。"]},{"id":"m087","b":"通用","n":"紓壓曲","c":1500,"t":["你可以在短休期間利用安撫人心的音樂或演說來使你受傷的隊友回復活力。若你或任何可以聽見你表演的生物在短休結束時借由消耗生命骰回復生命值，則每顆生命骰將為生物額外回復的 1d8 生命值。"]},{"id":"m088","b":"通用","n":"紓壓曲-續曲","c":2500,"req":"具有能力[【通用】紓壓曲]","refs":[{"b":"通用","n":"紓壓曲"}],"need":1,"t":["你的紓壓曲額外回復的生命值由 1d8→1d12。"]},{"id":"m089","b":"通用","n":"激勵涌泉","c":3500,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["你在完成一次短休或長休后都會回復所有你在吟游激勵骰花費掉的次數。"]},{"id":"m090","b":"通用","n":"反制迷惑","c":2500,"t":["你獲得使用音樂或言語的力量來干擾會影響心靈效果的能力。","以一個動作，你可以開始一段持續到你下個回合結束的表演。在這段期間，你和任何與你距離 30 尺內的友善生物在對抗[恐懼]或魅惑的豁免檢定中獲得優勢。只有能聽見你的生物可以獲得此效果。這段表演將在你陷入無力、無法發出聲音、或是你自願停止（不需要動作）時提早結束。在表演期將你皆無法使用動作、附贈動作、反應。"]},{"id":"m091","b":"通用","n":"擾神之詞","c":1500,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["你可以編造一些帶有魔力的話語，擾亂一個生物的心神，使其自我懷疑。","消耗一個附贈動作，你可以消耗一個吟游激勵骰，選擇一個你視野中的距你 60 尺以內的生物。擲出吟游激勵骰，在你的下一個回合開始前，該生物的下一次豁免檢定將會減去這個激勵骰所投出的值。"]},{"id":"m092","b":"通用","n":"不竭鼓舞","c":1500,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["你的激勵言語是如此的具有感染力，以至於被鼓舞的人感受到他們必須要，不行也得行地做到成功。","當一個生物使用了你的吟游激勵骰用於攻擊骰、屬性檢定或豁免檢定后仍然失敗，其可以保留這個吟游激勵骰。"]},{"id":"m093","b":"通用","n":"成功學說","c":1500,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["當你成功激勵了他人之后，你那雄辯言辭的力量會散播開去。","當一個距離你 60 尺內的生物使用了你的吟游激勵骰增益了一次攻擊骰，屬性檢定或者豁免檢定並且成功之后，你可以用你的反應去借此鼓勵另一個（除了你之外的）能聽見你的生物了，其獲得一個吟游激勵骰，並且你不會消耗已有的吟游激勵骰。","你可以使用該能力的次數等於你的魅力調整值（最少為 1），在長休后回復該能力被消耗的所有使用次數。"]},{"id":"m094","b":"通用","n":"醉人演出","c":1500,"t":["你可以在你的表演中注入魅惑人心的精類魔法。","若你持續表演至少 1 分鐘，你可以嘗試通過歌唱、朗誦詩歌、或跳舞來驚艷你的聽眾。在表演結束時，選擇距離你 60 尺內完整觀看或聆聽了你表演的任意數量個類人生物，數量最多等同於你的魅力調整值（最少為 1）。每個目標必須成功通過一次對抗你法術豁免 DC 的感知豁免，否則將被你魅惑。當因為這個方式被魅惑，目標將視你為偶像，熱烈地和任何人談論關於你的事，並阻撓任何反對你的人。除非它原本就傾向為你而戰，否則它會避免暴力手段。作用於一個目標上的此效果會在 1 小時后結束，或在它受到任何傷害、你攻擊它、或它目擊你攻擊或傷害了他的任何盟友時提早結束。","若目標成功通過豁免檢定，目標並不會察覺到你曾嘗試魅惑它。","一旦你使用此能力，直到你完成一次短休或長休之前你都不能再使用它。"]},{"id":"m095","b":"通用","n":"絕代技藝","c":1500,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["當你進行一次屬性檢定時，你可以消耗一次你吟游激勵的使用次數。骰一顆吟游激勵骰，並將骰出來的數字加入該屬性檢定的擲骰結果中。你可以選擇在你為該屬性檢定擲骰后，但 DM 宣布你成功與否之前使用此能力。"]},{"id":"m096","b":"通用","n":"駭人言詞","c":2000,"t":["你學會將能夠引發恐慌的陰險魔法注入看似無害的言詞中。","若你和一個類人生物單獨談話至少 1 分鐘，你可以嘗試在它心中埋下偏執和妄想。在對話結束時，目標必須以劣勢成功通過一次對抗你法術豁免 DC 的感知豁免，否則因你或你所選擇的另一個生物陷入[恐懼]。目標將因為這個方式而陷入[恐懼]長達 1 小時，或直到它被攻擊或傷害、或直到它目擊它的盟友被攻擊或傷害。","若目標成功通過豁免檢定，目標並不會察覺到你曾嘗試[恐懼]它。","一旦你使用此能力，直到你完成一次短休或長休之前你都不能再使用它。"]},{"id":"m097","b":"通用","n":"陰影學識","c":2000,"t":["你獲得將黑暗魔法編入你言詞，引發出一個生物最懼怕事物的能力。","以一個主要動作，你用魔法低語一段詞句，且只有一個距離你 30 尺內的生物可以聽見。目標必須進行一次對抗你法術豁免 DC 的感知豁免。若它與你之間沒有共通的語言或它無法聽見你，則它將自動通過該豁免檢定。若豁免成功，你的低語聽起來將像是一陣不知所雲的呢喃，且沒有任何效果。","若豁免失敗，目標將在接下來 8 小時內被你魅惑，或直到你或你的盟友攻擊它、傷害它、或強迫它進行一次豁免檢定。它將把這段低語解讀成一段對它最不堪秘密的描述。你不會獲得任何對該秘密的情報，但目標會深信你已經知道該秘密。","被魅惑的生物將因為懼怕你揭露它的秘密而服從你的命令。它不會為你冒險賭上自己的性命或為你而戰，除非它原本就傾向會這麼做。它會為你提供只提供給親密朋友的幫助和禮物。","當這個效果結束，該生物不會理解它為什麼如此懼怕你。","一旦你使用此能力，直到你完成一次長休之前你都不能再使用它。"]},{"id":"m098","b":"通用","n":"天族韌性","c":3500,"t":["每當你完成一次短休或長休時，你將獲得臨時生命值。這些臨時生命值等同於你的能力數目 + 你的魅力調整值。此外，在短休或長休結束時選擇最多五個你所能看見的生物。這些生物將各自獲得等同於你能力數目的一半 + 你的魅力調整值的臨時生命值。"]},{"id":"m099","b":"通用","n":"海洋餽贈","c":1500,"t":["你游泳速度為 40 尺，且可以在水下呼吸。"]},{"id":"m100","b":"通用","n":"黑暗者賜福","c":1500,"t":["當你將一個敵對生物的生命值歸零時，你獲得等同於你魅力調整值 + 你的能力數目的臨時生命值（最少為 1）。"]},{"id":"m101","b":"通用","n":"黑暗者的強運","c":1500,"t":["當你進行一次屬性檢定或豁免檢定時，你可以使用此能力以將一顆 d10 加入你的擲骰結果中。你可以在看見一開始的擲骰結果之后，但任何檢定效果發生之前使用此能力。","一旦你使用此能力，直到你完成一次短休或長休之前你都不能再使用它。"]},{"id":"m102","b":"通用","n":"喚醒心靈","c":1500,"t":["你的異界知識賦予了你接觸其他生物心靈的能力。","你可以對距離你 30 尺內且你所能看見的一個生物通過心靈感應交談。你不需要與該生物有共通的語言，就能使它理解你通過心靈感應所傳達的話語，但該生物必須至少理解一種語言。"]},{"id":"m103","b":"通用","n":"熵光防護","c":2000,"t":["你學會用魔法從攻擊中守護自己，並將敵人失手的打擊轉變成你自己的好運。","當一個生物對你進行一次攻擊檢定時，你可以使用你的反應以讓該檢定承受劣勢。若該攻擊失手，則直到你的下個回合結束前，你下一次對該生物進行的攻擊檢定將獲得優勢。","一旦你使用此能力，直到你完成一次短休或長休之前你都不能再使用它。"]},{"id":"m104","b":"通用","n":"墳塚之觸","c":2000,"req":"具有能力[【特殊】顫慄型態]","refs":[{"b":"特殊","n":"顫慄型態"}],"need":1,"t":["死靈之力對你的身體和魔法產生了深遠的影響。","你的回合每回合一次，當你用攻擊檢定命中一個生物並對該生物投擲傷害骰時，你可以將傷害類型替換為 [闇蝕傷害]。當你為顫慄型態時，你可以在確定目標受到該[闇蝕傷害]的數值時，額外投擲一枚[闇蝕傷害]骰。"]},{"id":"m105","b":"通用","n":"月之儀態","c":1000,"t":["你不再需要睡眠，且無法被任何方式強迫入睡。若要獲得長休的好處，你必須消耗完整 8 小時進行輕省活動，像是閱讀你的魔法書和放哨。"]},{"id":"m106","b":"通用","n":"巫者目光","c":1500,"t":["當任何變形者或被幻術系或變化系法術隱藏的生物距離你 30 尺內並處於你視線範圍內，你可以看見該生物的真實型態。"]},{"id":"m107","b":"通用","n":"迷人引響力","c":1500,"t":["你獲得對欺瞞和說服的技能熟練。","你在欺瞞和說服的技能的檢定上具有優勢。"]},{"id":"m108","b":"通用","n":"地城探索者","c":2000,"t":["警戒於大多地城中會發現的隱藏陷阱和密門，你獲得下列好處：","• 你在搜索密門時所進行的感知（察覺）和智力（調查）檢定中有優勢。","• 你在躲避或抵抗陷阱時的豁免檢定中有優勢。","• 對於陷阱所造成的傷害具有抗性。","• 以快速步速旅行並不會對你的被動感知（察覺）數值造成原本的-5 減值。"]},{"id":"m109","b":"通用","n":"幸運","c":3000,"t":["你的離奇運氣讓你可以在最危險的時刻化險為夷。","你獲得 3 點幸運點。當你進行攻擊檢定、屬性檢定、或豁免檢定時，你可以花費一點幸運點以再骰一顆額外的 d20。你可以選擇在你擲骰之后，但決定結果之前才花費幸運點。你選擇要使用哪一顆 d20 以用在該攻擊檢定、屬性檢定、或豁免檢定。","你也可以在一次對你的攻擊檢定被進行時選擇花費一點幸運點。骰一顆 d20，然后選擇該次攻擊要使用攻擊者還是你的骰子。如果有超過一個生物花費幸運點以影響一次擲骰的結果，則幸運點將彼此抵消；不需要擲任何額外的骰子。","你在完成一次長休后回復所有你花費掉的幸運點。"]},{"id":"m110","b":"通用","n":"慷慨及運","c":1000,"req":"具有能力[【通用】幸運]","refs":[{"b":"通用","n":"幸運"}],"need":1,"t":["當一個與你距離 30 尺內，你能看見的隊友在攻擊檢定、能力檢定、或豁免檢定失敗時，你可以使用你的反應並消耗 1 點幸運點，來讓該隊友重新擲骰。該隊友必須使用新的擲骰結果。","當你使用這個能力，直到你的下個回合結束之前，你都不能使用你的［幸運］能力。"]},{"id":"m111","b":"通用","n":"醫療師","c":1500,"t":["你是名嫻熟的醫者，能夠快速地治療傷口並讓隊友們重返戰場。你獲得下列好處：","• 當你使用醫療工具組穩定瀕死生物的傷勢時，該生物同時回復 1 點生命值。","• 以一個動作，你可以消耗醫療工具組的一次使用額度照顧一個非瀕死的生物，並回復他 [1d6+4+等同該生物最大生命骰數量]的生命值。直到完成短休或長休之前，該生物都不能再通過此能力回復生命值。"]},{"id":"m112","b":"通用","n":"運動健將","c":2000,"t":["你曾經曆的大量肉體訓練，讓你獲得下列好處：","• 當你伏地時，起身只需要花費 5 尺移動速度。","• 攀爬不會消耗額外的移動速度。","• 你只需要徒步移動 5 尺就可以進行跳高和跳遠，而非原本的 10 尺。"]},{"id":"m113","b":"通用","n":"敏思強記","c":1500,"t":["你擁有着能以不可思議的精確度牢牢追蹤時間、方位、以及細節的大腦。你獲得下列好處：","• 你永遠知道哪個方位是北方。","• 你永遠知道距離下一次日出或日落還剩下幾個小時。","• 你可以精准回憶起過去一個月內你曾聽到或看到的任何事物。"]},{"id":"m114","b":"通用","n":"敏銳觀察","c":2000,"t":["你能夠迅速注意周遭環境的細節，你獲得下列好處：","• 若你可以在一個生物正以你理解的語言說話時看見它的嘴巴，你就可以通過讀唇語來理解目標正在說什麼。","• 你的被動感知（察覺）和被動智力（調查）獲得+5 加值。"]},{"id":"m115","b":"通用","n":"激勵統御","c":2500,"t":["你可以花費 10 分鐘來激勵你的同伴，鼓舞他們對戰鬥的信心。","若你這麼做，選擇 30 尺內最多 6 個可以看到或聽到你且理解你的友方生物（可以包括你自己）。每個生物可以獲得等同你的能力數加上你的魅力調整值的臨時生命值。直到完成短休或長休之前，受影響的生物都不能再通過此能力獲得臨時生命值。"]},{"id":"m116","b":"通用","n":"警覺","c":2000,"t":["經常對危機保持警惕，讓你獲得下列好處：","• 你的先攻獲得+5 加值。","• 當你意識清醒時不會被突襲。","• 其他生物對你進行的攻擊檢定並不會因為你看不到它而獲得優勢。"]},{"id":"m117","b":"通用","n":"機械僕從","c":2500,"t":["工藝的研究和精通讓你得以製造一個[機械僕從]。這個[機械僕從]是構裝體，且會毫不猶豫地服從你的命令，並在戰鬥中保護你。你一次只能有一個[機械僕從]。","選擇一個挑戰等級為 3(含)以下中型或大型野獸。這個[機械僕從]將使用該野獸的遊戲數據，且只要它的外型符合其遊戲數據，則它的外貌將由你自由決定。除此之外，它具有下列的調整：","• 它的生物類型為構裝體，而非野獸。","• 它的挑戰等級為你能力數。","• 它的最大生命值為 25+你能力數的五倍。","• 它的生命骰為 D10。","• 它的生命骰數目為你能力數。","• 它的 AC 變為 10+你的熟練值+你的智力調整值。","• 它不會被魅惑。","• 它沒有[魔力]。","• 它免疫於毒素傷害和中毒狀態。","• 若它原本沒有的話，它將獲得 60 尺範圍的黑暗視覺。","• 它理解你在創造它時所知道的所有語言，但它並不會說。","• 它的攻擊為魔法攻擊。","• 若你成為一次近戰攻擊的目標，且此[機械僕從]距離攻擊者 5 尺內，則你可以使用你的反應以命令[機械僕從]，指示它使用它的反應對該攻擊者進行一次近戰攻擊。","• 你可以一個動作命令它發動一次攻擊。","• 它將盡其所能地服從你的命令。","• 在戰鬥中，它將骰自己的先攻，並自己行動。","• 它不能作為[坐騎]。","若這個[機械僕從]被殺死，它可以透過尋常手段被起死回生（例如回生術法術）。此外，在一次長休的過程中，若你可以接觸它的身體，則你可以維修一個被殺死的[機械僕從]。它將在該次長休結束時以 1 點生命值的狀態被復活。若[機械僕從]無法被修復，則你可以藉由花費 6 休憩點與 8000DP 的原料以建造一個新的[機械僕從]。"]},{"id":"m118","b":"通用","n":"機獸武裝-機能強化","c":2000,"req":"具有能力[【通用】機械僕從]","refs":[{"b":"通用","n":"機械僕從"}],"need":1,"rep":1,"t":["你的[機械僕從]增加一項自選屬性值 2 點，或著增加二項自選屬性值各 1 點。(每一屬性上限為 20。)"]},{"id":"m119","b":"通用","n":"機獸武裝-堅硬護甲","c":2500,"req":"具有能力[【通用】機械僕從]","refs":[{"b":"通用","n":"機械僕從"}],"need":1,"t":["你的[機械僕從]AC+2。"]},{"id":"m120","b":"通用","n":"血之決心","c":2000,"t":["有時最佳選擇就是冒著生命危險去爭取一個獲勝的機會。","當你或友方生物被攻擊時，你消耗反應可以發動一次具有優勢的攻擊。若命中敵方，則取消其攻擊。成功取消後，該敵方生物在此次戰鬥結束前，對你的攻擊將獲得優勢。"]},{"id":"m121","b":"通用","n":"戰術領袖","c":1500,"t":["在每次戰鬥開始時，你可以與一名友方生物交換先攻順序。"]},{"id":"m122","b":"通用","n":"戰術型態","c":2000,"req":"具有能力[【通用】戰術領袖]","refs":[{"b":"通用","n":"戰術領袖"}],"need":1,"t":["戰術領袖具有戰術思維的領導者，隨著他的指令，友軍可以一步步地走向勝利。","在投擲先攻時你可以選擇一種你所有的戰術型態發動，戰術型態的效果直到此次戰鬥結束。","你獲得下面兩個戰術型態，並可以使用一個附贈動作做切換。","你一次只能有一個戰術型態。","戰術型態","• 蛇之戰術型態","如你周圍 5 尺有友方生物時，則他與你的近戰攻擊具有優勢。","• 蟹之戰術型態","如你周圍 5 尺有友方生物時，則他與你獲得半掩護狀態。","• 蠍之戰術型態","如你周圍 5 尺有友方生物時，則他與你的近戰攻擊距離增加 5 尺。","• 蜘蛛戰術型態","如你周圍 5 尺有友方生物時，則他與你的敏捷豁免、技能檢定具有優勢。","• 蟻群戰術型態","如你周圍 5 尺有友方移動時，你可以消耗反應與其一起移動。你 5 尺的友方生物也獲得同樣的效果。"]},{"id":"m123","b":"通用","n":"戰術學習","c":1500,"req":"具有能力[【通用】戰術型態]","refs":[{"b":"通用","n":"戰術型態"}],"need":1,"rep":1,"t":["你習的下面一種戰術型態。","戰術型態","• 蛇之戰術型態","如你周圍 5 尺有友方生物時，則他與你的近戰攻擊具有優勢。","• 蟹之戰術型態","如你周圍 5 尺有友方生物時，則他與你獲得半掩護狀態。","• 蠍之戰術型態","如你周圍 5 尺有友方生物時，則他與你的近戰攻擊距離增加 5 尺。","• 蜘蛛戰術型態","如你周圍 5 尺有友方生物時，則他與你的敏捷豁免、技能檢定具有優勢。","• 蟻群戰術型態","如你周圍 5 尺有友方移動時，你可以消耗反應與其一起移動。你 5 尺的友方生物也獲得同樣的效果。"]},{"id":"m124","b":"通用","n":"榮耀的奉獻","c":3000,"req":"具有能力[【通用】戰術型態]","refs":[{"b":"通用","n":"戰術型態"}],"need":1,"t":["身為一名優秀的戰術領袖，你可以克制自己，將榮耀貢獻給友軍。","一回合一次，你可以將自己的 [主要動作 Actions] 、 [附贈動作 Bonus Action] 、 [反應 Reactions] 中的一個，給予 30 尺內你所看見的一個友方生物。該友方生物需要可以看見、聽見你此能力才會生效。給予的 [主要動作 Actions] 、 [附贈動作 Bonus Action] 、 [反應 Reactions] 會持續到該友方生物的回合結束。","你每場戰鬥你只能使用此能力 1 次。"]},{"id":"m125","b":"通用","n":"備選戰術","c":2000,"req":"具有能力[【通用】戰術型態]","refs":[{"b":"通用","n":"戰術型態"}],"need":1,"t":["你現在可以同時發揮 2 個戰術型態的能力，但你每次切換仍舊之能切換一個。"]},{"id":"m126","b":"通用","n":"戰略家","c":3500,"req":"具有能力[【通用】榮耀的奉獻]和[【通用】備選戰術]","refs":[{"b":"通用","n":"榮耀的奉獻"},{"b":"通用","n":"備選戰術"}],"need":2,"t":["你的戰術型態效果範圍擴大到你周圍 30 尺的距離；[榮耀的奉獻]效果範圍擴大到你周圍 120 尺的距離。"]},{"id":"m127","b":"通用","n":"蝕骨道途","c":2000,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["你習得一種古老的部落技藝，可將被你打敗得生物屍體作為武器，並藉由狂暴之力將其生前力量引出。","當你親手擊殺一個生物後，你可以收集其屍體將其作為材料製作一個近戰武器。此武器稱之 [蝕骨武器] 。 [蝕骨武器] 製作此需要一個{#短休}的時間，你一次只能有一個 [蝕骨武器] ，並且你會熟練此你製作的 [蝕骨武器] 。","[蝕骨武器] 的傷害為任一種武器原型的傷害(長劍、巨斧、戰槌...)，此外此武器可以使用該材料的生物的特殊攻擊(如:龍的吐息攻擊...)，這個特殊攻擊只能在狂暴期間使用。(特殊攻擊會作為主詞綴(常見) 存在)"]},{"id":"m128","b":"通用","n":"街頭混混","c":1500,"t":["你知曉如何用語言使他人心神不安的技巧。","以一個附贈動作你可以使 30 尺內一個你所看到目標發出言語羞辱，如目標可以聽見此聲音則你對目標的下一次攻擊具優勢。"]},{"id":"m129","b":"通用","n":"街頭騙術","c":1500,"req":"具有能力[【靈敏】街頭技巧]","refs":[{"b":"靈敏","n":"街頭技巧"}],"need":1,"t":["在每次骰 D20 骰前，你可以宣言使用此能力這會使你的結果增加 1D6。","此能力只能使用[熟練加值數的 1/2(無條件進位)]次，直到你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m130","b":"通用","n":"這就是街頭","c":2500,"req":"[【靈敏】街頭技巧]","refs":[{"b":"靈敏","n":"街頭技巧"}],"need":1,"t":["你可以在最危險的時刻化險為夷。","當你受到攻擊命中時，消耗一個反應進行一次*特技*技能檢定，如技能檢定大於此次攻擊命中，則此次攻擊無效，並你可以移動 10 尺內的任一一個不被占據的空間，接著發動一次武器攻擊或徒手打擊，此次攻擊具有優勢。此能力只能使用[你的敏捷調整值]次，直到你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m131","b":"通用","n":"縱火犯","c":1500,"req":"具有能力[【靈敏】偷襲Ⅰ]","refs":[{"b":"靈敏","n":"偷襲Ⅰ"}],"need":1,"t":["作為一名合格的縱火犯你熟習爆裂物與火藥的危險與使用技巧。","你獲得一個縱火工具包，一個裝滿了你用於製造各樣爆裂物所需原料的提包。需要有縱火犯工具包才能製作縱火爆裂物，若你失去縱火犯工具包，則你可以花費 6 休憩點和價值 1000DP 的材料製作一個新的縱火犯工具包。","你獲得以下縱火爆裂物的製作方式，你可以在每次短休時製作等同於你智力調整值數量的縱火爆裂物，你所持有的縱火爆裂物數量不能超過你的能力數。","縱火爆裂物的豁免 DC=8+你的熟練+你智力調整值。","縱火爆裂物","◆ 縱火爆裂物-星塵","◇ 當這個爆裂物爆炸時對對周圍 5 尺的生物進行一次體質豁免如失敗將會受到[偷襲傷害]1/2 的力場傷害。","◇ 此物品可做為投石索的[彈藥]使用。","◆ 縱火爆裂物-野火","◇ 當這個爆裂物爆炸時對對周圍 5 尺的生物進行一次敏捷豁免如失敗將會受到[偷襲傷害]1/2 的火焰傷害。","◇ 此物品可做為投石索的[彈藥]使用。","◆ 縱火爆裂物-彈片","◇ 當這個爆裂物爆炸時對對周圍 5 尺的生物造成 2d4 的穿刺、揮砍或鈍擊其中一種傷害(隨機)。","◇ 此物品可做為投石索的[彈藥]使用。"]},{"id":"m132","b":"通用","n":"爆彈製作者","c":2500,"req":"具有能力[【通用】縱火犯]","refs":[{"b":"通用","n":"縱火犯"}],"need":1,"t":["當你製作[爆彈]類物品時你可直接花費 DP 製作而不需要製作材料但需要花費的 DP 為期購買 DP 的 2 倍。"]},{"id":"m133","b":"通用","n":"星塵爆裂物","c":1500,"req":"具有能力[【通用】縱火犯]","refs":[{"b":"通用","n":"縱火犯"}],"need":1,"t":["縱火爆裂物-星塵的效果變為:","◆ 縱火爆裂物-星塵","◇ 當這個爆裂物爆炸時對對周圍 5 尺的生物進行一次體質豁免如失敗將會受到[偷襲傷害]1/2 的力場傷害，並使其*倒地*；成功則受到的傷害減半，且不會*倒地*。","◇ 此物品可做為投石索的[彈藥]使用。"]},{"id":"m134","b":"通用","n":"野火爆裂物","c":1500,"req":"具有能力[【通用】縱火犯]","refs":[{"b":"通用","n":"縱火犯"}],"need":1,"t":["縱火爆裂物-野火的效果變為:","◆ 縱火爆裂物-野火","◇ 當這個爆裂物爆炸時對對周圍 5 尺的生物進行一次敏捷豁免如失敗將會受到[偷襲傷害]1/2 火焰傷害，並使其燃燒；成功則受到的傷害減半，且不會燃燒。","◇ 此物品可做為投石索的[彈藥]使用。"]},{"id":"m135","b":"通用","n":"彈片爆裂物","c":1500,"req":"具有能力[【通用】縱火犯]","refs":[{"b":"通用","n":"縱火犯"}],"need":1,"t":["縱火爆裂物-彈片的效果變為:","◆ 縱火爆裂物-彈片","◇ 當這個爆裂物爆炸時對對周圍 5 尺的生物造成 2d6 的穿刺、揮砍或鈍擊其中一種傷害(隨機)。","◇ 此物品可做為投石索的[彈藥]使用。"]},{"id":"m136","b":"通用","n":"日月道","c":2000,"req":"具有能力[【特殊】啟迪之道]","refs":[{"b":"特殊","n":"啟迪之道"}],"need":1,"t":["在你回合開始時，你可以消耗消耗 1 點[氣]使你的護甲等級(AC)與徒手打擊命中額外獲得你[感知調整值] 的加值，直到你的下次回合開始。"]},{"id":"m137","b":"通用","n":"回應命運","c":1500,"req":"具有能力[【特殊】啟迪之道]","refs":[{"b":"特殊","n":"啟迪之道"}],"need":1,"t":["在你的回合，你可以消耗 1 點[氣]與一次反應獲得一個附贈動作，你每場戰鬥只能只用此能力一次。"]},{"id":"m138","b":"通用","n":"強化．回應命運","c":2500,"req":"具有能力[【通用】回應命運]","refs":[{"b":"通用","n":"回應命運"}],"need":1,"t":["當你使用[回應命運]能力時，你將額外獲得一個主要動作。"]},{"id":"m139","b":"通用","n":"守林人","c":2500,"t":["你獲得[密探工具組]熟練。","在長休時你可以獲得你熟練值數目的守林人陷阱，你所持有的守林人陷阱數目不能超過你的熟練值+2。","守林人陷阱具有 30 點生命值，其護甲等級(AC)為[11+你的熟練加值]，如其觸發時須通過豁免，豁免的 DC=8+你的熟練+你敏捷調整值。如過要發現佈置的守林人陷阱需通通過一次感知(感知)檢定(DC=8+你的熟練加值+你的敏捷調整值)；如過要解除佈置的守林人陷阱需通通過一次敏捷(巧手)檢定(DC=8+你的熟練加值 +你的敏捷調整值)。","守林人陷阱","◆ 守林人陷阱-誘捕陷阱","◇ 重量:3lb","◇ 效果:當誘捕陷阱[觸發]時，觸發的生物須通過一次敏捷豁免，失敗將會陷入伏地與束縛狀態。","◆ 守林人陷阱-爆裂陷阱","◇ 重量:3lb","◇ 效果:當爆裂陷阱[觸發]時，觸發的生物須通過一次體質豁免，失敗將會受到 5D10 的火焰傷害，成功則火焰傷害減半。","◆ 守林人陷阱-刀鋒陷阱","◇ 重量:3lb","◇ 效果:當刀鋒陷阱[觸發]時，觸發的生物須通過一次力量豁免，失敗將會受到 6D8 的揮砍傷害，成功則揮砍傷害減半。","◆ 守林人陷阱-地裂陷阱","◇ 重量:3lb","◇ 效果:當地裂陷阱[觸發]時，會使周圍十尺的地面變為[困難地型]，並使觸發的生物須通過一次敏捷豁免，失敗將會受到 4D12 的鈍擊傷害並伏地，成功則鈍擊傷害減半。"]},{"id":"m140","b":"通用","n":"大範圍陷阱","c":1500,"req":"具有能力[【通用】守林人]","refs":[{"b":"通用","n":"守林人"}],"need":1,"t":["你獲取的守林人陷阱[觸發]範圍增加 5 尺。"]},{"id":"m141","b":"通用","n":"草藥師","c":2500,"t":["你獲得[製藥工具組]熟練。","當你採集植物時，你可額外獲得一個，下列隨機一種上古種子。","當你製作[藥劑]時可加入任意數目、種類的上古種子，使[藥劑]獲得額外的效果。","◇ 上古種子-補蠅草節莖","• 當你飲用具有這種上古種子的[藥劑]時，接下來 24 小時你進行感知豁免時可以再骰一次，並套用再骰後的骰值。","◇ 上古種子-炮仗紅節莖","• 當你飲用具有這種上古種子的[藥劑]時，你的力竭等級-1。","◇ 上古種子-山楂果核","• 當你飲用具有這種上古種子的[藥劑]時，會額外回復 1D8 點生命值，且提供足夠一個生物維持一天所需的營養。","◇ 上古種子-美人蕉種子","• 當你飲用具有這種上古種子的[藥劑]時，接下來 24 小時你進行體質豁免時可以再骰一次，並套用再骰後的骰值。","◇ 上古種子-蒲公英之種","• 當你飲用具有這種上古種子的[藥劑]時，解除身上的中毒狀態。","◇ 上古種子-鬼針草種子","• 當你飲用具有這種上古種子的[藥劑]時，下次短休時使用生命骰回復的生命值變為原先的 2 倍。"]},{"id":"m142","b":"通用","n":"大地低語","c":1500,"req":"具有能力[【通用】草藥師]","refs":[{"b":"通用","n":"草藥師"}],"need":1,"t":["每次你獲得上古種子時額外獲得兩個隨機一種上古種子。"]},{"id":"m143","b":"通用","n":"時刻備種","c":1500,"req":"具有能力 [【通用】草藥師]","refs":[{"b":"通用","n":"草藥師"}],"need":1,"t":["草藥師習慣性的準備與持續栽培。無論何時，你都能確保身邊有一份藥材或藥劑，避免在危急時刻因缺乏資源而陷入困境。這種「隨時備用」的能力讓你在隊伍中成為可靠的後勤支援。","在戰鬥狀態時時如你身上沒有上古種子則獲得得自選一顆上古種子。在戰鬥狀態時如你身上沒有 [治療藥水 Potion of Healing] 則你獲得一個[治療藥水 Potion of Healing] 。"]},{"id":"m144","b":"通用","n":"機獸武裝-多重攻擊","c":2000,"req":"具有能力[【通用】機械僕從]","refs":[{"b":"通用","n":"機械僕從"}],"need":1,"t":["你的機械僕從的攻擊次數+1。"]},{"id":"m145","b":"通用","n":"福禍相依","c":3000,"t":["你在骰值為 19、20，視為大成功。","你在骰值為 1、2，視為大失敗。"]},{"id":"m146","b":"通用","n":"追獵者","c":1500,"t":["你習得『獵人印記 Hunter's Mark』法術，這個法術這不會使用你的法術容量。在投擲先攻時，你可以對一個你能看見的生物施展『獵人印記 Hunter's Mark』法術。"]},{"id":"m147","b":"通用","n":"追獵強攻","c":1000,"req":"具有能力[【通用】追獵者]","refs":[{"b":"通用","n":"追獵者"}],"need":1,"t":["你施展施展『獵人印記 Hunter's Mark』法術所造成額外的 1d6 傷害變為 1d10 傷害。"]},{"id":"m148","b":"通用","n":"追獵殲滅","c":2500,"req":"具有能力[【通用】追獵者]","refs":[{"b":"通用","n":"追獵者"}],"need":1,"t":["你對你所施展施展『獵人印記 Hunter's Mark』的目標的的重擊筏值-1。『獵人印記 Hunter's Mark』的額外傷害可以造成重擊。"]},{"id":"m149","b":"通用","n":"持久追獵","c":2000,"req":"具有能力[【通用】追獵者]","refs":[{"b":"通用","n":"追獵者"}],"need":1,"t":["當你受到傷害時，不對打斷你對『獵人印記 Hunter's Mark』的專注。"]},{"id":"m150","b":"通用","n":"廣域追獵","c":1500,"req":"具有能力[【通用】追獵者]","refs":[{"b":"通用","n":"追獵者"}],"need":1,"t":["當你施展施展『獵人印記 Hunter's Mark』法術時可以對兩個生物同時施展。"]},{"id":"m151","b":"通用","n":"機會主義","c":1500,"t":["當你在技能檢定具有優勢時，此次技能檢定額外獲得 1D6 的加值。你能使用此能力的次數等於你的[熟練加值]。當你完成一次長休后，你回復所有已消耗的使用次數。"]},{"id":"m152","b":"通用","n":"神力引導﹝赦罪之眼﹞","c":2500,"req":"具有能力[【特殊】神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["沒有什麼能逃脫律法的監視。","以一個附贈動作消耗一個神力引導發動你獲得 60 尺的真實視覺，並在遠程武器的攻擊檢定獲得+2 的加值，持續 1 分鐘。"]},{"id":"m153","b":"通用","n":"警覺靈光","c":2000,"req":"具有能力[通用】神力引導﹝赦罪之眼﹞]","t":["若你未昏迷，則在你 10 尺內範圍內的友方生物的[被動感知]獲得[你的魅力調整值]的加值。"]},{"id":"m154","b":"通用","n":"巨靈流光","c":2000,"req":"具有能力[【特殊】神力引導﹝巨靈盟約﹞]","refs":[{"b":"特殊","n":"神力引導﹝巨靈盟約﹞"}],"need":1,"t":["巨靈的光輝流淌於你的身軀，即使未披甲胄，仍能化為堅不可摧的護佑。當你赤身或僅著輕甲時，巨靈的庇佑使你的防禦更為穩固，宛如大地本身守護著你。","當你為未穿著{#中甲}、{#重甲}時你的[護甲等級 Armor Class（AC）]額外獲得等同於你[魅力調整值]的加值(至少+1)。"]},{"id":"m155","b":"通用","n":"元素流光","c":1500,"req":"具有能力[【通用】巨靈流光]","refs":[{"b":"通用","n":"巨靈流光"}],"need":1,"t":["巨靈的光輝不僅庇佑你的防禦，更能在瞬間化為元素屏障。當你受到巨靈流光的守護時，你能引導其力量，抵禦天地間最猛烈的元素衝擊。","當你受到[【通用】巨靈流光]效果影響時，可以以一個[反應]獲得[酸蝕傷害]、[雷鳴傷害]、[火焰傷害]、 [閃電傷害]或[冰冷傷害]的免疫，直到你的下個回合開始。","你能使用此能力的次數等於你的[魅力調整值]。當你完成一次長休后，你回復所有已消耗的使用次數。"]},{"id":"m156","b":"通用","n":"神力引導﹝聖旗引光﹞","c":1500,"req":"具有能力[【武力】神力引導〔聖輝戰旗〕]","refs":[{"b":"武力","n":"神力引導﹝聖輝戰旗﹞"}],"need":1,"t":["你能以聖輝戰旗引導神力，將光芒化為詛咒的標記，迫使敵人暴露於光輝之下。此能力象徵聖旗不僅是庇佑盟友的象徵，更是審判敵人的利器。","以一個[主要動作]消耗一次[神力引導]發動，對自身周圍 60 尺的一個敵方生物發動，使其獲得 [引光] ({#詛咒}) 效果，持續一分鐘。","[引光] ({#詛咒})","• 當自身進行在敏捷[隱匿]檢定上具有 [劣勢]。","• 敵對生物對自身的攻擊檢定具有 [優勢]。","• 當自身身命值減少時額外受到 1D8 的[光耀傷害]。","• 若自身嘗試[{#隱形}]或進入黑暗環境，光輝仍會顯現其輪廓。"]},{"id":"m157","b":"通用","n":"永恆的閃耀之旗","c":2000,"req":"具有能力[【特殊】旗在我在]、[【特殊】聖旗威光]、[【通用】神力引導〔聖旗引光〕]三個","refs":[{"b":"特殊","n":"旗在我在"},{"b":"特殊","n":"聖旗威光"},{"b":"通用","n":"神力引導﹝聖旗引光﹞"}],"need":3,"t":["聖輝戰旗已成為你靈魂的一部分。它不再只是神力的化現，而是你存在的象徵。只要你仍在戰場上，聖旗便永遠閃耀。","每次長休結束時你可以獲得一個[聖輝戰旗]，當你具有[聖輝戰旗]時你無法裝備其他武器。"]},{"id":"m158","b":"通用","n":"聖旗真耀","c":3000,"req":"具有能力[【通用】永恆的閃耀之旗]","refs":[{"b":"通用","n":"永恆的閃耀之旗"}],"need":1,"t":["你的聖輝戰旗已不再只是武器或象徵，而是你靈魂的永恆延伸。當你舉起聖旗，光輝照耀整個戰場，庇佑盟友、審判敵人，旗在則你在，光在則信念不滅。","當你裝備[聖輝戰旗]時，你獲得以下的特性。","• 審判之光","◦ 你可使用一個[主要動作]對 60 內一個可見的生物發動，對其進行一次感知豁免(DC=神力引導的 DC)，如失敗對其造成 10d8 的[光耀傷害]並獲得得 [引光] ({#詛咒})，如成功則傷害減半且不會受到詛咒。","◦ 你在長休結束前只能使用此特性一次。","• 聖旗光輝","◦ 詞綴[聖輝戰旗]的 [{#靈光}]效果變為 30 尺。","◦ 詞綴[聖輝戰旗]的[{#靈光}]效果內的友方生物武器攻命中時而外造成 1D6 的[光耀傷害]。"]},{"id":"m159","b":"通用","n":"槍術風格·戰亂遊俠","c":2000,"req":"具有能力能力 [【特殊】槍匠]","refs":[{"b":"特殊","n":"槍匠"}],"need":1,"t":["你在混亂的戰場中依舊保持冷靜與專注，無論敵人如何逼近，你的槍口始終穩定指向目標。","當你使用 [暴雷加農砲 Discharge Canno] 攻擊時，你不會因周圍 5 尺有其他敵對單位獲得 [劣勢 Disadvantage] 。"]},{"id":"m160","b":"武力","n":"軍用武器熟練","c":1500,"t":["角色獲得所有的軍用武器熟練。"]},{"id":"m161","b":"武力","n":"輕甲熟練","c":500,"t":["角色獲得輕甲熟練。"]},{"id":"m162","b":"武力","n":"中度著甲","c":1000,"req":"具有能力[【武力】輕甲熟練]或角色具有輕甲熟練","refs":[{"b":"武力","n":"輕甲熟練"}],"need":1,"soft":1,"t":["角色獲得中甲和盾牌的熟練。"]},{"id":"m163","b":"武力","n":"中甲大師","c":1500,"req":"具有能力[【武力】中度著甲]或角色具有中甲熟練","refs":[{"b":"武力","n":"中度著甲"}],"need":1,"soft":1,"t":["穿着中甲不會讓你的敏捷（隱匿）檢定獲得劣勢。","當你穿着中甲時，如果你的敏捷為 16 或以上，你的 AC 可以增加 3 點，而非 2 點。"]},{"id":"m164","b":"武力","n":"重甲熟練","c":1000,"req":"具有能力[【武力】中度著甲]或角色具有中甲熟練","refs":[{"b":"武力","n":"中度著甲"}],"need":1,"soft":1,"t":["角色獲得重甲熟練。"]},{"id":"m165","b":"武力","n":"額外攻擊","c":1000,"t":["每當你在自己回合以主要動作執行攻擊動作時，你可以發動 2 次攻擊，而非 1 次。"]},{"id":"m166","b":"武力","n":"戰鬥風格-守護","c":1000,"t":["當一個你所能看見的生物攻擊一個距離你 5 尺內你以外的目標，你可以使用你的反應以讓該攻擊檢定承受劣勢；當你使用此能力時，你必須持握一面盾牌。"]},{"id":"m167","b":"武力","n":"戰鬥風格-巨武戰鬥","c":1000,"t":["當你在使用一把以雙手持用的近戰武器所進行攻擊的傷害骰中骰出了1或2的結果，你可以重骰該骰，且必須使用新的擲骰結果，即使其結果仍然是1或2。該武器必須具有雙手或可雙手屬性才能讓你獲得這個好處。"]},{"id":"m168","b":"武力","n":"戰鬥風格-遠程武器","c":1000,"t":["你在使用遠程武器進行的遠程攻擊檢定中獲得+2 加值。"]},{"id":"m169","b":"武力","n":"戰鬥風格-決鬥","c":1000,"t":["當你單手持用一把近戰武器，且沒有持用其他武器時，你在使用該武器所進行的傷害骰中獲得+2 加值。"]},{"id":"m170","b":"武力","n":"戰鬥風格-防禦","c":1000,"t":["當你穿戴護甲時，你的 AC 獲得+1 加值。"]},{"id":"m171","b":"武力","n":"戰鬥風格-雙武器戰鬥","c":1000,"t":["在你的主要回合，當你雙武器戰鬥時，你可以額外攻擊一次，此攻擊的命中不會增加屬性調整值。"]},{"id":"m172","b":"武力","n":"戰鬥風格-盲鬥","c":1000,"t":["你獲得 10 尺盲視。在 10 尺範圍內，你可以看見除了處於全遮掩后的任何東西，哪怕你正在被目盲或是在黑暗之中。此外，你可以看見該範圍內的未對你成功躲藏的隱形生物。"]},{"id":"m173","b":"武力","n":"戰鬥風格-攔截","c":1000,"t":["當一個你可見的生物攻擊距離你 5 尺以內你以外的目標時，你能以一個反應將目標受到的傷害減少 1d10 + 你熟練加值（最多減到 0 傷害）。當你手持一面盾牌或者一把簡單或軍用武器時才能執行此反應。"]},{"id":"m174","b":"武力","n":"戰鬥風格-投擲武器戰鬥","c":1000,"t":["你可以在使用一件帶有投擲屬性武器進行攻擊時，將那件武器作為攻擊的一部分而拔出。","此外，在你以一件投擲武器於遠程攻擊中命中對手時，你的傷害骰獲得+2 加值。"]},{"id":"m175","b":"武力","n":"戰鬥風格-徒手格鬥","c":1000,"t":["你的徒手打擊可以造成 1d4 + 你力量調整值的鈍擊傷害，如果你沒有手持任何武器或盾牌進行攻擊，傷害骰從 d4 變為 d6。","你的每個回合開始時，你可以對被擒於你的一個生物造成 1d4 鈍擊傷害。"]},{"id":"m176","b":"武力","n":"堅守之盾","c":1000,"req":"具有能力[【武力】戰鬥風格-守護]","refs":[{"b":"武力","n":"戰鬥風格-守護"}],"need":1,"t":["當你使用[戰鬥風格-守護]時，你可以額外使此次攻擊檢定-5。"]},{"id":"m177","b":"武力","n":"巨武狂襲","c":1000,"req":"具有能力[【武力】戰鬥風格-巨武戰鬥]","refs":[{"b":"武力","n":"戰鬥風格-巨武戰鬥"}],"need":1,"t":["當你在你的回合使用 [主要動作 Actions] 使用一把以雙手持用的近戰武器所進行攻擊時你額外獲得一次攻擊機會，此次攻擊具有 [劣勢 Disadvantage] 。該武器必須具有{#雙手}或{#可雙手}屬性才能讓你獲得這個好處。"]},{"id":"m178","b":"武力","n":"遠程打擊","c":1000,"req":"具有能力[【武力】戰鬥風格-遠程武器]","refs":[{"b":"武力","n":"戰鬥風格-遠程武器"}],"need":1,"t":["你在使用遠程武器進行的攻擊的傷害獲得+2 加值。"]},{"id":"m179","b":"武力","n":"決鬥高手","c":1000,"req":"具有能力[【武力】戰鬥風格-決鬥]","refs":[{"b":"武力","n":"戰鬥風格-決鬥"}],"need":1,"t":["當你單手持用一把近戰武器，且沒有持用其他武器時，你在使用該武器所進行攻擊檢定獲得+2 加值。"]},{"id":"m180","b":"武力","n":"鐵壁","c":1000,"req":"具有能力[【武力】戰鬥風格-防禦]","refs":[{"b":"武力","n":"戰鬥風格-防禦"}],"need":1,"t":["[戰鬥風格-防禦]的效果變為-[當你穿戴護甲時，你的 AC 獲得+2 加值。]"]},{"id":"m181","b":"武力","n":"二刃斬","c":1500,"req":"具有能力[【武力】戰鬥風格-雙武器戰鬥]","refs":[{"b":"武力","n":"戰鬥風格-雙武器戰鬥"}],"need":1,"t":["當你雙持武器使用藉機攻擊時，你可以額外攻擊一次，此攻擊的傷害與攻擊檢定不會增加屬性調整值。"]},{"id":"m182","b":"武力","n":"心眼","c":1500,"req":"具有能力[【武力】戰鬥風格-盲鬥]","refs":[{"b":"武力","n":"戰鬥風格-盲鬥"}],"need":1,"t":["[盲鬥]效果變為-[你獲得 20 尺盲視。在 20 尺範圍內，你可以看見除了處於全遮掩后的任何東西，哪怕你正在被目盲或是在黑暗之中。此外，你可以看見該範圍內的未對你成功躲藏的隱形生物。]"]},{"id":"m183","b":"武力","n":"阻斷","c":1500,"req":"具有能力[【武力】戰鬥風格-攔截]","refs":[{"b":"武力","n":"戰鬥風格-攔截"}],"need":1,"t":["[攔截]效果變為-[當一個你可見的生物攻擊距離你 5 尺以內你以外的目標時，你能以一個反應將目標受到的傷害減少 1d10 + 你熟練加值 2 倍或的 AC 加值的 2 倍（最多減到 0 傷害）。當你手持一面盾牌或者一把簡單或軍用武器時才能執行此反應。]"]},{"id":"m184","b":"武力","n":"投手","c":1500,"req":"具有能力[【武力】戰鬥風格-投擲武器戰鬥]","refs":[{"b":"武力","n":"戰鬥風格-投擲武器戰鬥"}],"need":1,"t":["當你使用一件帶有投擲屬性武器進行攻擊時，你可以選擇在同一直線上且距離較遠的另一個生物作為次要攻擊目標，當你的攻擊失手時將會對次要目標進行攻擊檢定，此次攻擊檢定為劣勢。"]},{"id":"m185","b":"武力","n":"打架高手","c":1000,"req":"具有能力[【武力】戰鬥風格-徒手格鬥]","refs":[{"b":"武力","n":"戰鬥風格-徒手格鬥"}],"need":1,"t":["徒手格鬥效果變為-[你的徒手打擊可以造成 1d6 + 你力量調整值的鈍擊傷害，如果你沒有手持任何武器或盾牌進行攻擊，傷害骰從 d6 變為 d8。你的每個回合開始時，你可以對被擒於你的一個生物造成 1d6 鈍擊傷害。]"]},{"id":"m186","b":"武力","n":"打架專家","c":1500,"req":"具有能力[【武力】打架高手]","refs":[{"b":"武力","n":"打架高手"}],"need":1,"t":["徒手格鬥效果變為-[你的徒手打擊可以造成 1d8 + 你力量調整值的鈍擊傷害，如果你沒有手持任何武器或盾牌進行攻擊，傷害骰從 d8 變為 d10。你的每個回合開始時，你可以對被擒於你的一個生物造成 1d8 鈍擊傷害。]"]},{"id":"m187","b":"武力","n":"格鬥天王","c":2000,"req":"具有能力[【武力】打架專家]","refs":[{"b":"武力","n":"打架專家"}],"need":1,"t":["徒手格鬥效果變為-[你的徒手打擊可以造成 1D10 + 你力量調整值的鈍擊傷害，如果你沒有手持任何武器或盾牌進行攻擊，傷害骰從 D10 變為 D12。你的每個回合開始時，你可以對被擒於你的一個生物造成 1d10 鈍擊傷害。]"]},{"id":"m188","b":"武力","n":"酒馆拳王","c":1500,"t":["習慣於抄起任何剛好在手邊的武器加入混戰亂鬥，你獲得下列好處：","• 你熟練於臨時武器。","• 你的徒手打擊使用 d4 作為傷害骰。","• 當你在你的回合使用徒手打擊或臨時武器命中一個生物時，你可以使用附贈動作以嘗試擒抱該目標。"]},{"id":"m189","b":"武力","n":"戰鬥卓越","c":1500,"t":["你學會各種戰技，並借由被稱作卓越骰的特殊骰子驅動它們。","你學會三個自選戰技，參見下列「戰技」項目。許多戰技將以某些方式強化一次攻擊。你只能為每次攻擊使用一種戰技。","［卓越骰］你擁有四顆為上限的『卓越骰』，這四顆『卓越骰』為 D8。卓越骰將在你使用戰技時被花費。你在完成一次短休或長休后回復你花費掉的卓越骰。","豁免檢定.你的部分戰技會要求你的目標進行一次豁免檢定以對抗戰技的效果。這個豁免檢定 DC 的計算方式如下：戰技豁免 DC = 8 + 你的熟練加值 + 你的力量或敏捷調整值（由你決定）","「戰技」:","• 指揮官奇襲.當你在你的回合採取攻擊動作時，你可以放棄你的其中一次攻擊，並使用一個附贈動作以指揮你的其中一個同伴進行奇襲。當你這麼做時，選取一個能夠看見或聽見你的友善生物，並消耗一顆卓越骰。該生物可以立刻使用它的反應以進行一次武器攻擊，並將卓越骰加入該攻擊的傷害骰中。","• 繳械擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰並嘗試使目標繳械，強迫它掉落一個它正持握且你所選取的物品。你將卓越骰加入該攻擊的傷害骰中，且目標必須進行一次力量豁免。若豁免失敗，它將掉落你所選取的該物體。該物體將落在它的腳邊。","• 擾亂擊.你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以干擾該生物，為你的盟友制造良機。你將卓越骰加入該攻擊的傷害骰中。在你的下個回合開始前，下一次你以外的攻擊者對目標所進行的攻擊檢定將具有優勢。","• 躲閃步伐.當你移動時，你可以消耗一顆卓越骰，擲該卓越骰並將骰出的數字加入你的 AC 中直到你停止移動。","• 詭詐擊.你可以消耗一顆卓越骰並在你的回合使用一個附贈動作以進行佯攻，選取一個距離你 5 尺內的生物作為你的目標。你在該回合對該生物的下一次攻擊檢定中具有優勢。若該攻擊命中，則將卓越骰加入該攻擊的傷害骰中。若你在獲得這個優勢的回合中沒有使用它，則你將會失去這個優勢。","• 挑釁擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試挑釁目標攻擊你。你將卓越骰加入該攻擊的傷害骰中，且目標必須進行一次感知豁免。若豁免失敗，則直到你的下個回合結束前，目標對你以外的物件所進行的所有攻擊檢定都將承受劣勢。","• 突刺擊.當你在你的回合進行一次近戰武器攻擊時，你可以消耗一顆卓越骰以使你該攻擊的觸及範圍增加 5 尺。若你命中，則你將卓越骰加入該攻擊的傷害骰中。","• 靈動擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以調動你其中一個伙伴到一處更有利的位置。你將卓越骰加入該攻擊的傷害骰中，且你選取一個能夠看見或聽見你的友善生物。該生物可以使用它的反應以移動最多等同於它移動速度一半的距離，且不會觸發來自你攻擊目標的藉機攻擊。","• 恐嚇擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試嚇唬目標。你將卓越骰加入該攻擊的傷害骰中，且目標必須進行一次感知豁免。若豁免失敗，它將因你陷入[恐懼]直到你的下個回合結束。","• 格擋.當另一個生物以一次近戰攻擊傷害你時，你可以使用你的反應並消耗一顆卓越骰以減少傷害。該傷害將減少等同於你卓越骰所骰出的數字 + 你的敏捷調整值。","• 精准擊.當你對一個生物進行一次武器攻擊檢定，你可以消耗一顆卓越骰以將它加入該檢定中。你可以在進行攻擊檢定之前或之后使用此戰技，但必須在任何攻擊的效果適用前使用。","• 推撞擊.你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試驅使目標后退。你將卓越骰加入該攻擊的傷害骰中，且若目標的體型為大型或更小，則它必須進行一次力量豁免。若豁免失敗，你將目標推離你最多 15 尺距離。","• 鼓舞.在你的回合，你可以使用一個附贈動作並消耗一顆卓越骰以鼓舞你其中一個同伴的士氣。當你這麼做時，選取一個能夠看見或聽見你的友善生物。該生物將獲得等同於你卓越骰所骰出的數字 + 你的魅力調整值的臨時生命值。","• 反擊.當一個生物在一次對你進行的近戰攻擊中失手，你可以使用你的反應並消耗一顆卓越骰以對該生物進行一次近戰武器攻擊。若你命中，則你將卓越骰加入該攻擊的傷害骰中。","• 橫掃擊. 當你以一次近戰武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試以相同的攻擊傷害另一個生物。選取另一個距離原本目標 5 尺內，且處於你觸及範圍的生物。若原本的攻擊檢定能夠命中第二個生物，則它將受到等同於你卓越骰所骰出的數字的傷害。這個傷害的傷害類別與原本攻擊所造成的傷害類別相同。","• 絆摔擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試將目標擊倒。你將卓越骰加入該攻擊的傷害骰中，且若目標的體型為大型或更小，則它必須進行一次力量豁免。若豁免失敗，則你將目標擊倒伏地。"]},{"id":"m190","b":"武力","n":"卓越之心","c":1000,"req":"具有能力[【武力】戰鬥卓越]","refs":[{"b":"武力","n":"戰鬥卓越"}],"need":1,"t":["你的卓越骰數目上限變為六顆。"]},{"id":"m191","b":"武力","n":"卓越之躍","c":1000,"req":"具有能力[【武力】戰鬥卓越]","refs":[{"b":"武力","n":"戰鬥卓越"}],"need":1,"t":["你的卓越骰由 D8 變為 D10。"]},{"id":"m192","b":"武力","n":"卓越精通","c":1500,"req":"具有能力[【武力】卓越之躍]","refs":[{"b":"武力","n":"卓越之躍"}],"need":1,"t":["你的卓越骰由 D10 變為 D12。"]},{"id":"m193","b":"武力","n":"卓越不滅","c":2000,"req":"具有能力[【武力】卓越之心]","refs":[{"b":"武力","n":"卓越之心"}],"need":1,"t":["每次戰鬥開始時你獲得[你的體質調整值]卓越骰。"]},{"id":"m194","b":"武力","n":"戰技精通","c":2000,"req":"具有能力[【武力】戰鬥卓越]","refs":[{"b":"武力","n":"戰鬥卓越"}],"need":1,"t":["你每次攻擊可以使用兩種戰技。"]},{"id":"m195","b":"武力","n":"戰技大師","c":2500,"req":"具有能力[【武力】戰鬥卓越]","refs":[{"b":"武力","n":"戰鬥卓越"}],"need":1,"t":["你每次攻擊可以使用的戰技沒有上限。"]},{"id":"m196","b":"武力","n":"戰技習得","c":500,"req":"具有能力[【武力】戰鬥卓越]","refs":[{"b":"武力","n":"戰鬥卓越"}],"need":1,"rep":1,"t":["習得下面一種「戰技」。","「戰技」:","• 指揮官奇襲.當你在你的回合採取攻擊動作時，你可以放棄你的其中一次攻擊，並使用一個附贈動作以指揮你的其中一個同伴進行奇襲。當你這麼做時，選取一個能夠看見或聽見你的友善生物，並消耗一顆卓越骰。該生物可以立刻使用它的反應以進行一次武器攻擊，並將卓越骰加入該攻擊的傷害骰中。","• 繳械擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰並嘗試使目標繳械，強迫它掉落一個它正持握且你所選取的物品。你將卓越骰加入該攻擊的傷害骰中，且目標必須進行一次力量豁免。若豁免失敗，它將掉落你所選取的該物體。該物體將落在它的腳邊。","• 擾亂擊.你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以干擾該生物，為你的盟友制造良機。你將卓越骰加入該攻擊的傷害骰中。在你的下個回合開始前，下一次你以外的攻擊者對目標所進行的攻擊檢定將具有優勢。","• 躲閃步伐.當你移動時，你可以消耗一顆卓越骰，擲該卓越骰並將骰出的數字加入你的 AC 中直到你停止移動。","• 詭詐擊.你可以消耗一顆卓越骰並在你的回合使用一個附贈動作以進行佯攻，選取一個距離你 5 尺內的生物作為你的目標。你在該回合對該生物的下一次攻擊檢定中具有優勢。若該攻擊命中，則將卓越骰加入該攻擊的傷害骰中。若你在獲得這個優勢的回合中沒有使用它，則你將會失去這個優勢。","• 挑釁擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試挑釁目標攻擊你。你將卓越骰加入該攻擊的傷害骰中，且目標必須進行一次感知豁免。若豁免失敗，則直到你的下個回合結束前，目標對你以外的物件所進行的所有攻擊檢定都將承受劣勢。","• 突刺擊.當你在你的回合進行一次近戰武器攻擊時，你可以消耗一顆卓越骰以使你該攻擊的觸及範圍增加 5 尺。若你命中，則你將卓越骰加入該攻擊的傷害骰中。","• 靈動擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以調動你其中一個伙伴到一處更有利的位置。你將卓越骰加入該攻擊的傷害骰中，且你選取一個能夠看見或聽見你的友善生物。該生物可以使用它的反應以移動最多等同於它移動速度一半的距離，且不會觸發來自你攻擊目標的藉機攻擊。","• 恐嚇擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試嚇唬目標。你將卓越骰加入該攻擊的傷害骰中，且目標必須進行一次感知豁免。若豁免失敗，它將因你陷入[恐懼]直到你的下個回合結束。","• 格擋.當另一個生物以一次近戰攻擊傷害你時，你可以使用你的反應並消耗一顆卓越骰以減少傷害。該傷害將減少等同於你卓越骰所骰出的數字 + 你的敏捷調整值。","• 精准擊.當你對一個生物進行一次武器攻擊檢定，你可以消耗一顆卓越骰以將它加入該檢定中。你可以在進行攻擊檢定之前或之后使用此戰技，但必須在任何攻擊的效果適用前使用。","• 推撞擊.你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試驅使目標后退。你將卓越骰加入該攻擊的傷害骰中，且若目標的體型為大型或更小，則它必須進行一次力量豁免。若豁免失敗，你將目標推離你最多 15 尺距離。","• 鼓舞.在你的回合，你可以使用一個附贈動作並消耗一顆卓越骰以鼓舞你其中一個同伴的士氣。當你這麼做時，選取一個能夠看見或聽見你的友善生物。該生物將獲得等同於你卓越骰所骰出的數字 + 你的魅力調整值的臨時生命值。","• 反擊.當一個生物在一次對你進行的近戰攻擊中失手，你可以使用你的反應並消耗一顆卓越骰以對該生物進行一次近戰武器攻擊。若你命中，則你將卓越骰加入該攻擊的傷害骰中。","• 橫掃擊.當你以一次近戰武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試以相同的攻擊傷害另一個生物。選取另一個距離原本目標 5 尺內，且處於你觸及範圍的生物。若原本的攻擊檢定能夠命中第二個生物，則它將受到等同於你卓越骰所骰出的數字的傷害。這個傷害的傷害類別與原本攻擊所造成的傷害類別相同。","• 絆摔擊.當你以一次武器攻擊命中一個生物時，你可以消耗一顆卓越骰以嘗試將目標擊倒。你將卓越骰加入該攻擊的傷害骰中，且若目標的體型為大型或更小，則它必須進行一次力量豁免。若豁免失敗，則你將目標擊倒伏地。"]},{"id":"m197","b":"武力","n":"堅定印記","c":1500,"t":["你可以威脅你的敵人，挫敗它們的攻擊並為傷害他人而懲罰它們。當你以一次近戰武器攻擊命中一個生物，你可以標記該生物直到你的下個回合結束。這個效果會在你陷入無力狀態、你死亡、或者其他人記號該生物時提早結束。","當一個被標記( {#詛咒} )的生物距離你 5 尺內，它將在任何不以你為目標的攻擊檢定中具有劣勢。","此外，若一個被你標記的生物對你以外的任何單位造成傷害，你可以在你的下個回合以一個附贈動作對該被記號的生物進行一次特殊的近戰武器攻擊。你在該攻擊檢定中具有優勢，且若命中，該攻擊的武器將對目標額外造成等同於[你能力數目 1/2]的傷害。無論你標記了多少生物，你能夠進行這個特殊攻擊的次數等同於你的力量調整值（最少一次），且你在完成一次{#長休}后回復所有你花費掉的次數。"]},{"id":"m198","b":"武力","n":"防護戰術","c":1500,"t":["若你或一個距離你 5 尺內且你所能看見的生物被一次攻擊時，且若你正持用一把近戰武器或盾牌，則你能夠以一個反應骰一顆 D8 。骰這顆骰子，並將骰出來的數字加入目標對該次攻擊的 AC 中。若該攻擊仍然命中，則目標對該次攻擊的傷害將減半。","你可以使用這個能力的次數等同於你的體質調整值（最少一次），且你在完成一次{#長休}后回復所有你花費掉的次數。"]},{"id":"m199","b":"武力","n":"堅守戰線","c":2500,"t":["你成為了封鎖你敵人行動的專家。且若你[藉機攻擊 Opportunity Attack] 命中一個單位，該單位直接結束其回合。"]},{"id":"m200","b":"武力","n":"勇猛衝鋒","c":1500,"t":["若你在近戰攻擊一個生物之前直線移動至少 10 尺，且該攻擊命中，則目標必須成功通過一次{#力量豁免}（DC= 8 + 你的熟練加值 + 你的力量調整值），否則被擊倒[伏地]。","你在每個你的回合只能使用這個能力一次。"]},{"id":"m201","b":"武力","n":"重擊強化","c":1500,"t":["你的近戰武器攻擊將在骰出 19 或 20 時造成 [重擊] 。"]},{"id":"m202","b":"武力","n":"卓躍重擊","c":2000,"req":"具有能力[【武力】重擊強化]","refs":[{"b":"武力","n":"重擊強化"}],"need":1,"t":["你的近戰武器攻擊將在骰出 18、19 或 20 時造成[重擊]。"]},{"id":"m203","b":"武力","n":"追獵如風","c":1000,"req":"具有能力[【靈敏】幽影追蹤者]","refs":[{"b":"靈敏","n":"幽影追蹤者"}],"need":1,"t":["你學會以出人意料的高速進行攻擊，以讓你將一次失手轉變成另一次打擊。在你的每個回合一次，當你的一次武器攻擊失手時，你可以進行另一次武器攻擊以作為同個動作的一部份。"]},{"id":"m204","b":"武力","n":"追獵如風-幽影之擊","c":500,"req":"具有能力[【武力】追獵如風]","refs":[{"b":"武力","n":"追獵如風"}],"need":1,"t":["如果再黑暗或微光光照環境之中， [追獵如風]的效果變為:","你學會以出人意料的高速進行攻擊，以讓你將一次失手轉變成另一次打擊。在你的每個回合二次，當你的一次武器攻擊失手時，你可以進行另一次武器攻擊以作為同個動作的一部份。"]},{"id":"m205","b":"武力","n":"閃現打擊","c":1500,"req":"具有能力[【通用】位面戰士]","refs":[{"b":"通用","n":"位面戰士"}],"need":1,"t":["你獲得在眨眼間穿梭於位面間的能力。","當你採取攻擊動作時，你可以在每次攻擊之前傳輸最多 10 尺距離到一處你所能看見的未被占據空間。若你以攻擊動作命中至少二個以上的不同生物時，你可以對其餘你未攻擊的一個生物再進行一次攻擊。你可以使用此效果的次數等於你的敏捷調整值（最少為 1），在長休后回復該能力被消耗的所有使用次數。"]},{"id":"m206","b":"武力","n":"閃現打擊-相位之力","c":1000,"req":"具有能力[【武力】閃現打擊]","refs":[{"b":"武力","n":"閃現打擊"}],"need":1,"t":["當你使用[閃現打擊]能力移動後，你的下一次近戰攻擊具有額外 1D8 的力場傷害。"]},{"id":"m207","b":"武力","n":"狩者獵物","c":1500,"rep":1,"t":["你獲得下列其中一個你所選取的能力：巨怪獵者、巨人殺手或滅族者。","• 巨怪獵者.","你的執着可以毀滅最強大的敵人。當你以一次武器攻擊命中一個生物，若它的生命值低於最大值，則該生物將受到額外的 1D8 傷害。你每回合只能造成一次這個額外傷害。","• 巨人殺手.","當一個距離你 5 尺內，體型為大型或更大的生物對你進行的一次攻擊命中或失手時，只要你可以看見該生物，你就可以使用你的反應以立刻在它的攻擊之后對它進行攻擊。","• 滅族者.","在你的每個回合一次，當你進行一次武器攻擊時，你可以使用相同的武器對一個距離原本目標 5 尺內，且處於你武器射程內的另一個生物進行另一次攻擊。"]},{"id":"m208","b":"武力","n":"巨怪屠殺","c":1000,"req":"具有能力[【武力】狩者獵物]","refs":[{"b":"武力","n":"狩者獵物"}],"need":1,"t":["[巨怪獵者.]的額外的 1D8 傷害變為 2D8。"]},{"id":"m209","b":"武力","n":"泰坦狩獵","c":1000,"req":"具有能力[【武力】狩者獵物]","refs":[{"b":"武力","n":"狩者獵物"}],"need":1,"t":["當你在使用[巨人殺手.]時你可以攻擊 2 次。"]},{"id":"m210","b":"武力","n":"滅族屠戮","c":1000,"req":"具有能力[【武力】狩者獵物]","refs":[{"b":"武力","n":"狩者獵物"}],"need":1,"t":["當你在使用[滅族者.]時你的選擇的目標距離變為 15 尺。"]},{"id":"m211","b":"武力","n":"箭雨","c":2000,"t":["可以使用你的主要動作以進行一次特殊的遠程武器攻擊，並以處於你武器射程內你所能看見一點的周圍 10 尺範圍內的任意數量個生物作為目標。你必須有足夠的彈藥以攻擊每個目標，且你為每個目標進行各自的攻擊檢定。"]},{"id":"m212","b":"武力","n":"劍刃風暴","c":1500,"t":["你可以使用你的動作以進行一次近戰攻擊，並以距離你 5 尺內的任意數量個生物作為目標，為每個目標進行各自的攻擊檢定。"]},{"id":"m213","b":"武力","n":"死亡一擊","c":1000,"req":"具有能力[【靈敏】刺客]","refs":[{"b":"靈敏","n":"刺客"}],"need":1,"t":["你成為了讓人在瞬間死亡的宗師。","當你攻擊並命中一個被突襲的生物，它必須進行一次體質豁免（DC 為 8+你的敏捷調整值+你的熟練加值）。若豁免失敗，則此次突襲你對該生物造成的所有傷害將變為二倍。"]},{"id":"m214","b":"武力","n":"戰鬥洞察","c":1000,"req":"具有能力[【通用】審訊者]和[【靈敏】偷襲Ⅰ]","refs":[{"b":"通用","n":"審訊者"},{"b":"靈敏","n":"偷襲Ⅰ"}],"need":2,"t":["你獲得破譯對手的戰術並加以反制的能力。","以一個附贈動作，你可以進行一次感知（洞悉）檢定，對抗一個你所能看見且未處於無力狀態的生物的魅力（欺瞞）檢定。若你成功，則即使你對它的攻擊檢定不具有優勢，你仍然可以對它使用你的偷襲能力。但若你在該攻擊檢定上具有劣勢則不行。","這個好處將持續 1 分鐘，或直到你對另一個不同的目標成功使用此能力。"]},{"id":"m215","b":"武力","n":"識破弱點","c":1500,"req":"具有能力[【武力】戰鬥洞察]","refs":[{"b":"武力","n":"戰鬥洞察"}],"need":1,"t":["你學會借由謹慎研究一個生物的戰術和行動以利用它的弱點。","當你的戰鬥洞察能力適用於一個生物時，你對該生物的偷襲傷害增加 3d6 點。","一旦你使用此能力，直到你完成一次長休之前你都不能再使用它。"]},{"id":"m216","b":"武力","n":"優雅戰舞-鬥曲","c":1000,"req":"具有能力[【靈敏】優雅戰舞]","refs":[{"b":"靈敏","n":"優雅戰舞"}],"need":1,"t":["你可以在你的回合使用一個附贈動作，你的下一次近戰攻擊與傷害具有優勢。"]},{"id":"m217","b":"武力","n":"決鬥大師","c":1500,"req":"具有能力[【靈敏】風流劍客]","refs":[{"b":"靈敏","n":"風流劍客"}],"need":1,"t":["你對劍術的精通使你可以扭轉戰鬥的勝負。","如果你的一次近戰攻擊檢定失手，你可以選擇以優勢再骰一次該攻擊檢定並額外獲得一個附贈動作。一但你這麼做，直到你完成一次短休或長休之前你不能再次使用這個能力。"]},{"id":"m218","b":"武力","n":"狂暴","c":1500,"t":["在戰鬥中，你帶着原初的狂怒作戰。在你的回合，你能夠以一個附贈動作進入狂暴。","當處於狂暴時，若你未穿戴重甲，你獲得下列好處：","• 你在力量檢定和力量豁免中具有優勢。","• 當你進行一次使用力量的近戰武器攻擊時，你在傷害骰上獲得+2 加值。","• 你對鈍擊、穿刺、和揮砍傷害具有抗性。","若你能夠施放法術，則你在狂暴期間無法施放它們或維持法術上的專注。","你的狂暴持續 1 分鐘。它會在你被擊倒昏迷時提前結束，或若你從上回合到這回合結束時都沒有攻擊一個敵意生物或受到傷害，則狂暴也將提前結束。你也可以在你的回合以一個附贈動作結束你的狂暴。","你可以使用此能力的次數為你的熟練值，你在完成一次長休后重獲所有的使用次數。"]},{"id":"m219","b":"武力","n":"狂暴之徒","c":1000,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["當你狂暴時[你進行一次使用力量的近戰武器攻擊時，你在傷害骰上獲得+2 加值]，此能力變為[你進行一次使用力量的近戰武器攻擊時，你在傷害骰上獲得+4 加值]。"]},{"id":"m220","b":"武力","n":"魯莽攻擊","c":1500,"t":["你可以拋下防御以展開不顧一切的猛烈攻擊。","當你在你的回合進行你的第一次攻擊時，你可以選擇魯莽地攻擊。這麼做會讓你在該回合間所有使用力量的近戰武器攻擊檢定具有優勢，但直到你的下個回合結束前，所有對你進行的攻擊檢定也將具有優勢。"]},{"id":"m221","b":"武力","n":"蠻惡重擊Ⅰ","c":1500,"t":["你可以在決定近戰攻擊的[重擊]所造成的額外傷害時額外骰 1 顆武器傷害骰。"]},{"id":"m222","b":"武力","n":"蠻惡重擊Ⅱ","c":2000,"req":"具有能力[【武力】蠻惡重擊Ⅰ]","refs":[{"b":"武力","n":"蠻惡重擊Ⅰ"}],"need":1,"t":["[蠻惡重擊Ⅰ]的額外骰武器傷害骰增加到 2 顆。"]},{"id":"m223","b":"武力","n":"蠻惡重擊Ⅲ","c":2500,"req":"具有能力[【武力】蠻惡重擊Ⅱ]","refs":[{"b":"武力","n":"蠻惡重擊Ⅱ"}],"need":1,"t":["[蠻惡重擊Ⅰ]的額外骰武器傷害骰增加到 3 顆。"]},{"id":"m224","b":"武力","n":"狂暴不止","c":2500,"req":"具有能力[【武力】狂暴之徒]、[【特殊】頑強狂暴]、[【靈敏】狂暴衝刺]中的兩項","refs":[{"b":"武力","n":"狂暴之徒"},{"b":"特殊","n":"頑強狂暴"},{"b":"靈敏","n":"狂暴衝刺"}],"need":2,"t":["你的狂暴是如此猛烈，以至於它只會在你陷入昏迷或你選擇結束它時提早結束。"]},{"id":"m225","b":"武力","n":"野獸道途","c":1500,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["當你進入狂暴時，你可以變形，顯現出你體內的野獸之力。直到你的狂暴結束，你獲得一件天生武器。它對你視作簡易近戰武器。和普通的簡易近戰武器一樣，你在你的攻擊骰和傷害骰上加上你的力量調整值。","在你進入狂暴時，你可以在以下幾種天生武器中選擇一種：","• 噬咬.","◦ 你的嘴變形成一個野獸的血盆大口或者巨大的昆蟲大顎（由你選擇）。","◦ 它的一次攻擊能造成 1d8 穿刺傷害。每回合一次，當你用它命中一個生物並造成傷害時，你回復等同於你的熟練值 2 倍的生命值。你只能在生命值低於一半的時候使用此方式回復生命值。","• 利爪.","◦ 你的雙手變成了一對利爪，當他沒有持握東西時，可以把它當作作武器使用。","◦ 利爪命中后能夠造成 1d6 揮砍傷害。每回合一次，當你用利爪以攻擊動作進行攻擊時，你可以額外攻擊一次，作為同一個攻擊動作的一部分。","• 尾擊.","◦ 你長出一條繩索一般的，多刺的長尾巴。","◦ 它攻擊命中能造成 1d8 的穿刺傷害，並且擁有觸及屬性。","◦ 如果一個 10 尺以內的，你能看見的生物通過攻擊檢定的方式攻擊並擊中你，你可以消耗你的反應動作來揮舞你的尾巴進行擋避，你投一個 d8 的骰子，並將它加入到你的 AC 中。這個反應可能可以讓這次攻擊轉而無法命中你。"]},{"id":"m226","b":"武力","n":"獸火痙蝕","c":1000,"req":"具有能力[【武力】野獸道途]","refs":[{"b":"武力","n":"野獸道途"}],"need":1,"t":["當你在狂暴時用你的天生武器擊中一個生物時，你內在的野獸可以詛咒你的目標變得如狂犬病似得病態癲狂。該生物需進行一次感知豁免（DC 為 8 + 你的熟練加值 + 你的體質調整值），如果失敗，將必須承受以下的一種效果（由你決定）：","• 目標必須消耗他的反應動作對你所選擇的一個能看到的目標的進行一次近戰攻擊。","• 目標受到 2d12 的心靈傷害。","你可以使用該能力的次數等於你的熟練加值。每完成一次長休之后你回復所有已消耗的使用次數。"]},{"id":"m227","b":"武力","n":"狂戰士","c":1500,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["你獲得狂怒能力。","狂怒• 你可以在狂暴時可以同時進入狂怒。若你這麼做，則在你狂暴期間，你可以在這之后的你的每個","回合以一個附贈動作進行一次近戰武器攻擊。","• 當你的狂暴結束時，你將承受一級的力竭狀態。"]},{"id":"m228","b":"武力","n":"復仇","c":1000,"req":"具有能力[【武力】狂戰士]","refs":[{"b":"武力","n":"狂戰士"}],"need":1,"t":["當你受到來自一個距離你５尺內生物的傷害時，你可以使用你的反應以對該生物進行一次近戰武器攻擊。"]},{"id":"m229","b":"武力","n":"狂戰士之怒","c":2000,"req":"具有能力[【武力】狂戰士]","refs":[{"b":"武力","n":"狂戰士"}],"need":1,"t":["當你進入狂怒的當個回合，你使用附贈動作進行近戰武器攻擊，由一次變為二次。"]},{"id":"m230","b":"武力","n":"浴血之怒","c":2500,"req":"具有能力[【武力】復仇]與[【武力】狂戰士之怒","refs":[{"b":"武力","n":"復仇"},{"b":"武力","n":"狂戰士之怒"}],"need":2,"t":["當你處於狂怒狀態時，你不已[主要動作]進行的近戰攻擊的攻擊次數+1。"]},{"id":"m231","b":"武力","n":"神性狂暴","c":1500,"req":"具有能力 [【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["你可以引導神性之力注入你的武器打擊中。","當你處於狂暴時，你在你的每個回合以近戰攻擊命中後的第一個生物將受到等同於 1d8 + 感知或魅力調整值的傷害。這個額外傷害的傷害類型為闇蝕或光耀。","你在獲得此能力時選擇其中一個傷害類型。"]},{"id":"m232","b":"武力","n":"神之先鋒","c":3000,"req":"具有能力[【特殊】狂暴專注]與【特殊】狂暴之吼]","refs":[{"b":"特殊","n":"狂暴專注"},{"b":"特殊","n":"狂暴之吼"}],"need":2,"t":["當你處於狂暴時，你在你的每個回合以近戰攻擊命中後，皆會具有[【武力】神性狂暴]的闇蝕或光耀傷害。"]},{"id":"m233","b":"武力","n":"武藝","c":1000,"t":["你獲得下列好處：","• 你的{#徒手打擊}視為{#簡易武器}，且在無握持物品時具有{#雙手}{#輕型}{#靈巧}特性，且視為{#雙武器}戰鬥。","• 你可以在{#徒手打擊}和{#簡易武器}中可以使用敏捷而非力量來計算其攻擊檢定和傷害骰。","• 你可以骰一顆 d6 以取代你{#徒手打擊}或{#簡易武器}的傷害骰。","• 當你在你的回合以{#徒手打擊}或一把{#簡易武器}採取攻擊動作，你能夠以[附贈動作 Bonus Action] 進行一次{#徒手打擊}。舉例來說，若你採取攻擊動作並使用長棍進行攻擊，只要你在該回合尚未採取 [附贈動作 Bonus Action] ，你就能夠以一個[附贈動作 Bonus Action] 再進行一次{#徒手打擊}。"]},{"id":"m234","b":"武力","n":"武藝強化","c":1000,"req":"具有能力[【武力】武藝]","refs":[{"b":"武力","n":"武藝"}],"need":1,"t":["[武藝] 的{#徒手打擊}或{#簡易武器}的傷害骰由 d6 變為 d8 。"]},{"id":"m235","b":"武力","n":"武藝至極","c":1500,"req":"具有能力[【武力】武藝強化]","refs":[{"b":"武力","n":"武藝強化"}],"need":1,"t":["[武藝] 的{#徒手打擊}或{#簡易武器}的傷害骰由 d8 變為 d10 。"]},{"id":"m236","b":"武力","n":"御氣以擊","c":1000,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["如果你在你的回合中執行主要動作時花費了 1 點或更多的[氣]，則你可以在回合結束前用一個[附贈動作 Bonus Action]用以{#徒手打擊}或{#簡易武器}進行一次攻擊。"]},{"id":"m237","b":"武力","n":"震攝拳","c":2000,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["你可以干擾一個對手體內氣的流動。","當你以近戰攻擊命中一個生物時，你可以消耗 2 點[氣]以嘗試進行一次[震懾拳]。目標必須成功通過一次體質豁免，否則被[震懾]直到你的下個回合結束。此體質豁免的 DC 為氣的豁免。"]},{"id":"m238","b":"武力","n":"星我之臂","c":1500,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["你對氣的掌握允許你召喚出星我的一部分。","以一個 [附贈動作 Bonus Action] ，你可以花費 1 點氣來召喚你的星我之臂，當你這麼做時，你選擇的每一個你所見的 10 尺範圍內的生物必須進行一次敏捷豁免檢定(DC 為氣的豁免)，如果失敗則受到相當於你兩倍武藝骰骰值的力場傷害。","在接下來的 10 分鐘內，這些幽光般的手臂會槃旋在你的肩膀附近或環繞着你的手臂（由你選擇），你來決定手臂們的外觀，如果你無力或死亡，它們就會立即消失。(此手臂無法握持物品，且不適用任何裝備效果)","當星我之臂出現時，你將獲得如下增益：","• 你進行力量檢定和力量豁免檢定時，可以用你的感知調整值來代替力量調整值。","• 你可以用星我之臂進行{#徒手攻擊}。","• 當你在自己回合用星我之臂進行徒手攻擊時，你的觸及範圍增加 5 尺。","• 當你用星我之臂進行徒手攻擊時，可以用感知調整值代替力量或敏捷調整值來進行攻擊檢定和傷害檢定，它們的傷害類型是力場。"]},{"id":"m239","b":"武力","n":"借力打力","c":1000,"req":"具有能力[【靈敏】醉拳]","refs":[{"b":"靈敏","n":"醉拳"}],"need":1,"t":["當一個生物對你進行的一次近戰攻擊檢定失手時，你能夠以一個反應消耗 1 點氣以使該攻擊命中一個你所選擇的，距離你 5 尺內且你所能看見的生物。"]},{"id":"m240","b":"武力","n":"龍吟九重天","c":2500,"req":"具有能力[【武力】借力打力]、[【靈敏】鯉魚打挺]、[【特殊】醉酒仙寓]、[【特殊】醉仙靈液]其中的二個","refs":[{"b":"武力","n":"借力打力"},{"b":"靈敏","n":"鯉魚打挺"},{"b":"特殊","n":"醉酒仙寓"},{"b":"特殊","n":"醉仙靈液"}],"need":2,"t":["你獲得對一群敵人進行驚人數量的攻擊的能力。","當你使用疾風連擊時，只要此回合的每次疾風連擊都以一個不同的生物作為目標，你就可以無限次的使用疾風連擊。(每次疾風連擊都需要消耗[氣])"]},{"id":"m241","b":"武力","n":"以氣御劍","c":1000,"req":"具有能力[【通用】劍聖之途]、[【特殊】氣]","refs":[{"b":"通用","n":"劍聖之途"},{"b":"特殊","n":"氣"}],"need":2,"t":["你獲得以你的氣進一步增強你武器的能力。","以一個附贈動作，你可以消耗最多 3 點氣並觸碰一把劍聖武器，以讓你在使用它進行攻擊時的攻擊檢定和傷害骰中獲得加值。這個加值等同於你所消耗的氣的數量。這個加值將持續 1 分鐘，或直到你再次使用這個能力。這個能力對已經具有攻擊檢定和傷害骰加值的魔法武器沒有任何效果。"]},{"id":"m242","b":"武力","n":"劍氣合一","c":3000,"req":"具有能力[【通用】人劍合一]、[【武力】以氣御劍]、[【特殊】劍準神確]其中二個","refs":[{"b":"通用","n":"人劍合一"},{"b":"武力","n":"以氣御劍"},{"b":"特殊","n":"劍準神確"}],"need":2,"t":["所有有消耗[氣]的效果，你都可以用劍聖武器的使用。如疾風連擊。"]},{"id":"m243","b":"武力","n":"墜氣無生","c":2000,"req":"具有能力[【特殊】永亡之道]和[【特殊】氣]","refs":[{"b":"特殊","n":"永亡之道"},{"b":"特殊","n":"氣"}],"need":2,"t":["你的觸碰可以將死亡的能量導入一個生物體內。","以一個動作，你觸碰一個距離你 5 尺內的生物，且你消耗 1~10 點氣。目標必須進行一次體質豁免，若該豁免失敗則受到消耗的氣 * 2d10 的闇蝕傷害，豁免成功則只受到一半的傷害。"]},{"id":"m244","b":"武力","n":"散打技巧","c":1500,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["你可以在你駕馭你自己體內氣的同時操作你敵人的氣。","當你使用你疾風連擊所賦予的其中一次攻擊命中一個生物時，你可以對該目標強加下列其中一個效果。","• 它必須成功通過一次敏捷豁免，否則被擊倒伏地。","• 它必須進行一次力量豁免。若它豁免失敗，則你可以將它推離你最多 15 尺距離。","• 它直到你的下個回合結束前都不能採取反應。"]},{"id":"m245","b":"武力","n":"散打技巧-複合打擊","c":2000,"req":"具有能力[【武力】散打技巧]","refs":[{"b":"武力","n":"散打技巧"}],"need":1,"t":["當你使用[【武力】散打技巧]時你可以額外賦予其另一個效果。"]},{"id":"m246","b":"武力","n":"震顫掌","c":3000,"req":"具有能力[【武力】散打技巧]","refs":[{"b":"武力","n":"散打技巧"}],"need":1,"t":["你獲得在某人體內制造致命震顫的能力。","當你以徒手打擊命中一個生物時，你可以消耗 3 點氣以讓這陣難以察覺的震動在目標體內開始鼓動，持續天數等同於你熟練值的 2 倍。這陣震動是無害的，直到你使用你的動作以結束它。若要這麼做，你與目標必須處於相同的存在位面。當你使用這個動作時，該生物必須進行一次體質豁免。若豁免失敗，則它的生命值歸零。若豁免成功，則它將受到 10d10 闇蝕傷害。你只能同時讓一個生物處於此能力的效果之下。你也可以選擇無害的結束這陣震動，而無須使用動作。"]},{"id":"m247","b":"武力","n":"受祝擊","c":500,"req":"具有能力[【特殊】神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["在戰鬥中，你受到神力的祝福。","當你通過法術或攻擊對一個生物造成傷害時，你能夠對該生物造成 1d8 光耀傷害。你造成一次此傷害后，你直到自己的下一個回合開始前無法再次使用此能力。"]},{"id":"m248","b":"武力","n":"死亡打擊","c":1000,"req":"具有能力[【特殊】神力引導﹝死亡之觸﹞]","refs":[{"b":"特殊","n":"神力引導﹝死亡之觸﹞"}],"need":1,"t":["在每個自己回合有一次機會，可以在用攻擊命中某生物時造成 2d8 的闇蝕傷害。"]},{"id":"m249","b":"武力","n":"業火打擊","c":1000,"req":"具有能力[【特殊】神力引導﹝工匠祝福﹞]","refs":[{"b":"特殊","n":"神力引導﹝工匠祝福﹞"}],"need":1,"t":["在每個自己回合有一次機會，可以在用攻擊命中某生物時造成 2d8 的火焰傷害。"]},{"id":"m250","b":"武力","n":"心靈打擊","c":1000,"req":"具有能力[【特殊】神力引導﹝秩序之令﹞]","refs":[{"b":"特殊","n":"神力引導﹝秩序之令﹞"}],"need":1,"t":["在每個自己回合有一次機會，可以在用攻擊命中某生物時造成 2d8 的心靈傷害。"]},{"id":"m251","b":"武力","n":"秩序之怒","c":2000,"req":"具有能力[【武力】心靈打擊]","refs":[{"b":"武力","n":"心靈打擊"}],"need":1,"t":["你所指定要毀滅的敵人將在你和你盟友的共同努力下凋零殆盡。","若你在你的回合對一個生物造成你心靈打擊的傷害，你可以標記(詛咒)該生物，持續直到你的下個回合開始。下一次你的盟友第一次攻擊命中受標記生物時，目標將同時受到 2d8 心靈傷害，接着此標記消失。"]},{"id":"m252","b":"武力","n":"毒素打擊","c":1000,"req":"具有能力[【魔法】神力引導﹝召喚假體﹞]","refs":[{"b":"魔法","n":"神力引導﹝召喚假體﹞"}],"need":1,"t":["在每個其自己回合有一次機會，可以在用攻擊命中某生物時造成 2d8 的毒素傷害。"]},{"id":"m253","b":"武力","n":"光耀打擊","c":1000,"req":"具有能力[【特殊】神力引導﹝暮光聖域﹞]","refs":[{"b":"特殊","n":"神力引導﹝暮光聖域﹞"}],"need":1,"t":["在每個自己回合有一次機會，可以在用攻擊命中某生物時造成 2d8 的光耀傷害。"]},{"id":"m254","b":"武力","n":"神力引導﹝聖導打擊﹞","c":1500,"req":"具有能力[【特殊】神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["你可以使用你的神力引導以不可思議的准確度猛擊。","當你進行一次攻擊檢定時，你可以使用你的神力引導以在該檢定中獲得+10 的加值。你在看見擲骰結果之后，但 DM 說出攻擊是否命中之前決定是否使用此能力。"]},{"id":"m255","b":"武力","n":"戰爭祭司","c":1500,"req":"具有能力[【武力】神力引導﹝聖導打擊﹞]","refs":[{"b":"武力","n":"神力引導﹝聖導打擊﹞"}],"need":1,"t":["你的神在你投身於戰鬥時賦予你激勵。","當你執行攻擊動作後，你能夠以一個附贈動作進行一次武器攻擊。你可以使用此能力等同於你感知調整值的次數（最少一次）。你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m256","b":"武力","n":"戰爭打擊","c":1500,"req":"具有能力[【武力】神力引導﹝聖導打擊﹞]","refs":[{"b":"武力","n":"神力引導﹝聖導打擊﹞"}],"need":1,"t":["在每個自己回合有一次機會，可以在用攻擊命中某生物時造成 2d10 的穿刺、揮砍或鈍擊傷害。"]},{"id":"m257","b":"武力","n":"強化至聖斬","c":2500,"req":"具有能力[【魔法】至聖斬]","refs":[{"b":"魔法","n":"至聖斬"}],"need":1,"t":["你是如此的充滿公義之力，以至於你的所有近戰武器打擊都帶着神聖的能量。","每當你使用一把近戰武器命中生物時，該生物將受到 1d8 光耀傷害。"]},{"id":"m258","b":"武力","n":"不朽衛士","c":2000,"req":"具有能力[【特殊】神力引導﹝自然之怒﹞]","refs":[{"b":"特殊","n":"神力引導﹝自然之怒﹞"}],"need":1,"t":["當你的生命值被歸零且沒有被當場殺死時，你可以選擇改為將生命值減少至 1。一旦你使用此能力，直到你完成一次長休之前你都不能再使用它。此外，你將免受任何衰老的弊害，且你不會被魔法變老。"]},{"id":"m259","b":"武力","n":"無敵的征服者","c":3000,"req":"具有能力[【特殊】征服靈光]和[【特殊】輕蔑喝斥]","refs":[{"b":"特殊","n":"征服靈光"},{"b":"特殊","n":"輕蔑喝斥"}],"need":2,"t":["你獲得駕馭卓越武藝的能力。","以一個動作，你可以魔法性地變成征服的化身，在接下來 1 分鐘內獲得下列好處：","• 你對所有傷害具有抗性。","• 當你在你的回合採取攻擊動作時，你可以作為該動作的一部份額外再進行一次攻擊。","• 你的近戰武器攻擊將在 d20 的結果骰出 19 或 20 時造成重擊。","這個效果會在你陷入無力狀態或死亡時提早結束。","一旦你使用此能力，直到你完成一次長休之前你都不能再使用它。"]},{"id":"m260","b":"武力","n":"至高衛士","c":3000,"req":"具有能力[【特殊】神聖忠誠]和[【通用】不屈之魂]","refs":[{"b":"特殊","n":"神聖忠誠"},{"b":"通用","n":"不屈之魂"}],"need":2,"t":["你在戰場上的姿態對那些致力於你事業的人們而言是一種強大的鼓舞。","你可以使用你的動作以獲得下列好處長達 1 小時：","• 你對鈍擊、穿刺、揮砍傷害具有抗性。","• 你的盟友在處於你 30 尺範圍內時在死亡豁免中具有優勢。","• 你以及距離你 30 尺內的盟友在感知豁免中具有優勢。","這個效果會在你陷入無力狀態或死亡時提早結束。","一旦你使用此能力，直到你完成一次長休之前你都不能再使用它。"]},{"id":"m261","b":"武力","n":"神力引導﹝至聖武器﹞","c":1500,"req":"具有能力[【特殊】神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["以一個動作消耗一個神力引導，你可以將正能量注入一把你正持握的武器，使用你的神力引導，在 1 分鐘內，你在使用該武器進行的攻擊檢定中加入你的魅力調整值（加值最低為+1）。","該武器同時將散發出 20 尺半徑的明亮光照和再延伸 20 尺的微光光照。若該武器原本不是魔法武器，則它將在持續期間變成一把魔法武器。","你可以在你的回合作為任何其他動作的一部份結束這個效果。若你不再持握或攜帶該武器，或若你陷入昏迷狀態，則此效果結束。"]},{"id":"m262","b":"武力","n":"原初打擊","c":1000,"req":"具有能力[【通用】荒野形態]","refs":[{"b":"通用","n":"荒野形態"}],"need":1,"t":["你在用荒野形態變形為野獸時的攻擊被視作魔法攻擊。"]},{"id":"m263","b":"武力","n":"鋒刃劍舞","c":1500,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["你學會展示出戰鬥技藝和速度而令人印象深刻的表演。","每當你在你的回合採取攻擊動作，你的步行速度增加 10 尺直到這個回合結束，且若此攻擊動作的其中一次你所進行的武器攻擊命中一個生物，則你可以選擇使用下列其中一個鋒刃劍舞選項。你每回合只能使用一個鋒刃劍舞選項。","• 防御劍舞. 你可以消耗一次你吟游激勵的使用次數，以讓武器對你命中的目標造成額外傷害。這個額外傷害等同於你吟游激勵骰的擲骰結果。直到你的下個回合開始，你也將吟游激勵骰的擲骰結果加到你的 AC 中。","• 靈活劍舞. 你可以消耗一次你吟游激勵的使用次數，以讓武器對你命中的目標造成額外傷害。這個額外傷害等同於你吟游激勵骰的擲骰結果。你也可以將目標推撞 5+吟游激勵骰擲骰結果的尺數的距離。你可以接着立刻使用你的反應以移動最多你步行速度的距離到一處距離目標 5 尺內的未被占據空間。","• 順劈劍舞. 你可以消耗一次你吟游激勵的使用次數，以讓武器對你命中的目標和任何距離你 5 尺內，你所選且你所能看見的其他生物造成傷害。這個傷害等同於你吟游激勵骰的擲骰結果。"]},{"id":"m264","b":"武力","n":"劍舞大師","c":2000,"req":"具有能力[【武力】鋒刃劍舞]","refs":[{"b":"武力","n":"鋒刃劍舞"}],"need":1,"t":["每當你使用一個鋒刃劍舞的選項，你可以骰一顆 d6，並使用它以取代一次吟游激勵骰的消耗。"]},{"id":"m265","b":"武力","n":"戰場激勵","c":1500,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["你學會在戰鬥中激勵他人。","一個擁有你所給予的吟游激勵骰的生物，可以骰該吟游激勵骰以將骰出來的數字加入它剛進行的傷害中。或者，當一個以該生物為目標的攻擊檢定被進行時，他可以在看見該次攻擊檢定的結果后，但 DM 宣布該次攻擊命中與否之前，使用他的反應以骰該吟游激勵骰，並將骰出來的數字加入它對該次攻擊的 AC 中。"]},{"id":"m266","b":"武力","n":"精神之刃","c":1000,"req":"具有能力[【通用】吟遊激勵]","refs":[{"b":"通用","n":"吟遊激勵"}],"need":1,"t":["你獲得了使你的傷害得以毒害其他生物精神的能力。","當你傷害一個生物時，你可以消耗一次你吟游激勵的使用次數，以對該目標造成你吟游激勵骰值的心靈傷害。"]},{"id":"m267","b":"武力","n":"鋒刃魔契","c":2000,"t":["你可以使用你的動作以在你的一只空着的手中創造一把[契約武器]。你可以在每次創造它時選擇這把近戰武器的型態。你在使用它時熟練於該武器。這把武器在克服對非魔法攻擊和傷害的抗性和免疫時視作魔法武器。","你的[契約武器]會在距離你超過 5 尺外的情況下長達 1 分鐘或更久時消失。這把武器也會在你再次使用這個能力創造武器、你解消武器（無需花費動作）、或你死亡時消失。","你可以在持握一把[魔法武器]時借由施展一種特別儀式以將該武器轉化成你的契約武器。施展這個儀式的過程需要 1 小時，且可以在短休期間被施展。你可以解消這把武器，將它存放在一個異次元空間，且它將在往后每次你創造你的契約武器時出現。你不能用這個方式影響一件神器或一把智能武器。若你死亡、你對另一把武器施展了 1 小時儀式、或你施展一個 1 小時儀式以打破跟這把武器的鏈接時，它將不再作為你的契約武器。若這把武器在鏈接中斷時處於異次元空間，則它將出現在你的腳邊。"]},{"id":"m268","b":"武力","n":"巫咒戰士","c":1500,"t":["每當你完成一次長休，你可以觸碰一把你所熟練且沒有雙手屬性的武器。當你使用該武器進行攻擊時，你可以使用你的魅力調整值，而非力量或敏捷，來計算其攻擊檢定和傷害骰。這個好處會持續直到你完成一次長休。若你具有能力[【武力】鋒刃魔契]，則這個好處將擴展到你使用該能力召喚出的每一把契約武器，且無視武器類型的限制。"]},{"id":"m269","b":"武力","n":"巫咒護甲","c":3000,"req":"具有能力[【特殊】咒劍詛咒]","refs":[{"b":"特殊","n":"咒劍詛咒"}],"need":1,"t":["你的巫咒變得更加強大。若你使用咒劍詛咒所詛咒的目標以一次攻擊檢定命中你，你可以使用你的反應骰一顆 d6。若結果為 4 或更高，則無論該攻擊的檢定結果如何，該攻擊結果改為失手。"]},{"id":"m270","b":"武力","n":"飢渴鋒刃","c":2000,"req":"具有能力[【武力】鋒刃魔契]","refs":[{"b":"武力","n":"鋒刃魔契"}],"need":1,"t":["每當你在你的回合以主要動作攻擊時，如你使用[契約武器]攻擊則你的攻擊次數+1。"]},{"id":"m271","b":"武力","n":"巫毒鋒刃","c":2000,"req":"具有能力[【武力】鋒刃魔契]","refs":[{"b":"武力","n":"鋒刃魔契"}],"need":1,"t":["當你使用你的[契約武器]命中一個生物時，該生物受到等同你[熟練值]的闇蝕傷害（最少為 1）。"]},{"id":"m272","b":"武力","n":"雙持客","c":2000,"t":["你精通於雙持武器作戰，獲得下列好處：","• 當你每只手都各持握一把近戰武器時，你的 AC 獲得+1 加值。","• 即使你持握的單手近戰武器並非輕型，你仍可以進行雙武器戰鬥。","• 在你原本只能拔出或入鞘一把武器的時候，你可以同時拔出或入鞘二把單手武器。"]},{"id":"m273","b":"武力","n":"巨武大師","c":2000,"t":["你學會了如何將武器重量轉化為優勢，利用其動量來增強你的打擊。你獲得下列好處：","• 在你的回合，當你用近戰武器造成重擊、或將一名生物的生命值降至 0，你可以使用附贈動作再進行一次近戰武器攻擊。","• 在你使用你所熟練的重型武器進行近戰攻擊之前，你可以選擇讓該次攻擊檢定承受-5 的減值。若該次攻擊命中，該次攻擊的傷害+10。"]},{"id":"m274","b":"武力","n":"長武大師","c":2000,"t":["你可以使用觸及武器以牽制你的敵人。你獲得下列好處：","• 當你採取攻擊動作且只使用有觸及屬性武器進行攻擊時，你可以使用附贈動作以利用該武器的另一端進行一次近戰攻擊；這個攻擊使用和主要攻擊相同的屬性調整值。這個攻擊所使用的武器傷害骰為 d4，且該攻擊造成鈍擊傷害。","• 當你持握有觸及屬性的武器時，其他生物將在進入你的觸及範圍時觸發你的藉機攻擊。"]},{"id":"m275","b":"武力","n":"衝鋒手","c":2000,"t":["當你使用動作進行疾走時，你可以使用附贈動作來進行一次近戰武器攻擊或推撞一個生物。","若你疾走至少 10 尺后使用該附贈動作，則（若你選擇近戰攻擊且命中）該攻擊的傷害獲得+5 加值或（若你選擇推撞且成功）目標被你推開最多 10 尺。"]},{"id":"m276","b":"武力","n":"盾牌大師","c":2500,"t":["你的盾牌不僅僅是為了防御、更能被用來進攻。當你具有盾牌熟練且持握盾牌時，你獲得下列好處：","• 如果你在你的回合採取攻擊動作，你可以使用附贈動作利用你的盾牌嘗試推撞一個與你距離 5 尺內的生物。","• 如果你不處於無力，你可以將你盾牌的 AC 加值加到用以對抗只以你為目標的法術或其他有傷害效果的敏捷豁免檢定上。","• 如果你受到了某個效果允許你進行敏捷豁免檢定以減半傷害，你可以使用你的反應以在你成功通過豁免檢定時，將你的盾牌插入你和效果源頭之間，好讓你不受傷害。"]},{"id":"m277","b":"武力","n":"穿刺者","c":2000,"t":["你已經可以在戰鬥中造成精准的穿刺。你獲得以下好處:","• 每回合一次，你以攻擊方式直接或間接造成穿刺傷害時，你可以重擲其中一個穿刺傷害的傷害骰，並且你必須使用重投的結果。","• 當你以攻擊方式直接或間接造成穿刺傷害並此次攻擊為重擊時，你可以在計算重擊傷害時投一個額外穿刺傷害的傷害骰。"]},{"id":"m278","b":"武力","n":"重甲大師","c":2500,"req":"具有能力[【武力】重甲熟練]或角色具有重甲熟練","refs":[{"b":"武力","n":"重甲熟練"}],"need":1,"soft":1,"t":["當你穿着{#重甲}時，每次因 [攻擊 Attack] 、{#法術}、或傷害造成 [生命值 Hit Point] 減少時，生命值減少量 -3 。"]},{"id":"m279","b":"武力","n":"粉碎者","c":2500,"t":["你擅長於碾碎敵人的技藝，你獲得了以下增益：","• 每回合一次，你以攻擊方式直接或間接造成鈍擊傷害時，只要攻擊命中的生物的體型並未比你大一級以上，你就可以將目標移動五尺至一個未被占據的空間。","• 當你以攻擊方式直接或間接造成鈍擊傷害並此次攻擊為重擊時，直至你的下一回合開始，所有針對此次攻擊命中的生物的攻擊檢定具有優勢。( {#詛咒})"]},{"id":"m280","b":"武力","n":"野蠻攻擊者","c":2000,"t":["每回合一次，當你為一次近戰武器攻擊骰傷害時，你可以重骰該武器傷害骰，並任選其中一個結果使用。"]},{"id":"m281","b":"武力","n":"劈砍者","c":2500,"t":["已熟知該砍向何處以造成最重的傷害。你獲得以下好處：","• 每回合一次，你以攻擊方式直接或間接造成揮砍傷害時，你可以使攻擊命中的生物速度降低 10 尺，直到你的下回合開始。","• 當你以攻擊方式直接或間接造成揮砍傷害並此次攻擊為重擊時，該攻擊命中的生物在攻擊檢定上具有劣勢，直到你的下個回合開始。( {#詛咒})"]},{"id":"m282","b":"武力","n":"神龍勁","c":1500,"req":"具有能力[【特殊】神龍門徒]","refs":[{"b":"特殊","n":"神龍門徒"}],"need":1,"t":["當你以一次徒手攻擊對一個目標命中時，你可以消耗 1 點氣使次攻擊傷害變為 2D10。"]},{"id":"m283","b":"武力","n":"神龍吐息","c":2000,"req":"具有能力[【特殊】神龍門徒]","refs":[{"b":"特殊","n":"神龍門徒"}],"need":1,"t":["一回合一次，每當你在你的回合採取攻擊動作，你可以用龍的吐息來替代其中一次攻擊，吐息的範圍為 20 尺錐形或 30 尺長、5 尺寬的直線（由你選擇），並選舉一種傷害類型：酸蝕傷害、冰冷傷害、火焰傷害、閃電傷害、或毒素傷害。範圍內每個生物必須通過一次等同於你氣豁免 DC 的敏捷豁免。若豁免失敗，將受到 4D10 的傷害。若豁免成功，則它將受到一半的傷害。","你可以使用此能力的次數等同於你的熟練加值的 1/2(最少為 1)，當你完成一次長休時回復所有使用次數。當你沒有使用次數時，你可以花 3 點氣再次使用這個能力。"]},{"id":"m284","b":"武力","n":"神龍吐息強化","c":2000,"req":"具有能力[【武力】神龍吐息]","refs":[{"b":"武力","n":"神龍吐息"}],"need":1,"t":["當你使用你的[【武力】神龍吐息]時，你可以消耗 1 點氣來對其塑形並增強其威力。你的呼出的神龍吐息改變為 60 尺錐形或 90 尺長、5 尺寬的直線（由你選擇），傷害變為 5D10，此外你每額外消耗 1 點氣傷害骰 (D10)數目增加 1 顆。"]},{"id":"m285","b":"武力","n":"神力引導﹝怒濤﹞","c":1500,"req":"具有能力[【特殊】神力引導﹝海雲﹞]","refs":[{"b":"特殊","n":"神力引導﹝海雲﹞"}],"need":1,"t":["以一個附贈動作，你消耗一次神力引導使用次數，你可以將浪濤的巨力注入你的攻擊。在 1 分鐘內的每個回合一次，當你使用一次武器攻擊命中一個生物，你可以將目標推離你最多 10 尺。若被推離的目標撞上了一個障礙物或生物，它就會受到等同你魅力調整值的鈍擊傷害。"]},{"id":"m286","b":"武力","n":"驚濤駭浪","c":1500,"req":"具有能力[【特殊】神力引導﹝怒濤﹞","refs":[{"b":"特殊","n":"神力引導﹝怒濤﹞"}],"need":1,"t":["每當一個生物移動進入或離開你的觸及範圍時，你可以使用你的反應以召來洶湧的潮汐之力，對其造成 1d12 鈍擊傷害，並且它必須成功通過一次 DC=(8+魅力調整值+熟練)的力量豁免，否則被擊倒伏地。"]},{"id":"m287","b":"武力","n":"元素重刃","c":1500,"req":"具有能力[【特殊】巨靈道途]","refs":[{"b":"特殊","n":"巨靈道途"}],"need":1,"t":["你與巨靈的元素之力的鏈接加深了，你習得了如何將元素能量注入武器中。","當你進入狂暴時，你可以將能量注入其中一件你正持握的武器中，選擇以下一種傷害類型：酸蝕、冰冷、火焰、雷鳴或閃電。當你在狂暴中握持注能武器時，該武器的傷害類型變為你所選擇的傷害類型，使其獲得額外的 1d4 所選類型的傷害，且它獲得[投擲]屬性，正常射程為 20 尺，最大射程為 60 尺。此外你能夠以一個附贈動作重選其傷害類型。","在你投擲該武器後，無論是否命中目標，它會立即重新出現在你的手中。此外此武器無法除你外的其他生物握持。"]},{"id":"m288","b":"武力","n":"元素重刃強化","c":1500,"req":"具有能力[【武力】元素重刃]","refs":[{"b":"武力","n":"元素重刃"}],"need":1,"t":["你的元素重刃特性獲得的額外傷害提升至 2d4。"]},{"id":"m289","b":"武力","n":"元素重刃極化","c":1500,"req":"具有能力[【武力】元素重刃強化]","refs":[{"b":"武力","n":"元素重刃強化"}],"need":1,"t":["你的元素重刃特性獲得的額外傷害提升至 3d4。"]},{"id":"m290","b":"武力","n":"粉碎投擲","c":1000,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["當你以一件具有[投擲]屬性的武器，進行一次使用力量的遠程攻擊命中時，你可以在傷害上獲得狂暴給予的額外傷害的加值。"]},{"id":"m291","b":"武力","n":"撼山道途","c":2000,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["當你選擇此道途時，你的狂暴為你注入衝破並粉碎一切敵人的力量，令戰場化為你的領域。","當你處於狂暴時，以一次近戰攻擊命中一個生物時，你可以將它從你身邊朝你所選的方向推離最多 5 尺距離。體型為巨型或更大的生物必須進行一次力量豁免（DC 為 8+你的力量調整值+你的熟練加值）。若豁免成功，則它不會被推離。"]},{"id":"m292","b":"武力","n":"山嶽重擊","c":1500,"req":"具有能力[【特殊】不動巨嶺]","refs":[{"b":"特殊","n":"不動巨嶺"}],"need":1,"t":["當你處於狂暴時，如你在此回合無消耗移動速度，你的近戰武器攻擊傷害增加 1D8，當你使用此能力之後之後直到下次你的回合開始前移動速度為 0。","你對物體、建築物和構裝體生物造成的傷害為兩倍。"]},{"id":"m293","b":"武力","n":"撼山打擊","c":2000,"req":"具有能力[【武力】撼山道途]","refs":[{"b":"武力","n":"撼山道途"}],"need":1,"t":["當你處於狂暴時，任何你以非法術手段推離的生物將受到 1D6+你力量調整值的鈍擊傷害。"]},{"id":"m294","b":"武力","n":"百無禁忌","c":2000,"req":"具有能力[【靈敏】舞鬥士]","refs":[{"b":"靈敏","n":"舞鬥士"}],"need":1,"t":["戰場上所有的敵人都將會為你的舞伴。","當你對同體型或更小的生物進行擒抱、掙脫束縛檢定時具有優勢。","此外當你成功擒抱、掙脫束縛一名生物時你可以同時對他發動一次近戰武器攻擊。"]},{"id":"m295","b":"武力","n":"新月血波","c":2000,"req":"具有能力[【特殊】嗜血者]","refs":[{"b":"特殊","n":"嗜血者"}],"need":1,"t":["匯聚自身血液發動大範圍的腥紅血波。","以一個動作發動，對前方 30 尺直線、15 尺錐形生物近行一次敏捷豁免(DC=8+你的熟練值+你的敏捷、力量調整值)，失敗將受到(2D10+你的敏捷、力量調整值)、(近戰武器傷害最大值+你的敏捷、力量調整值)的闇蝕傷害，並獲得一個［鮮血印記］；成功則受到的傷害減半，且不會獲得［鮮血印記］。","當你使用此能力後，你的近戰武器觸及範圍範圍增加 5 尺直到這次戰鬥結束。","你每場戰鬥只能使用此能力一次。"]},{"id":"m296","b":"武力","n":"嗜血獠牙","c":1500,"req":"具有能力[【特殊】嗜血者]","refs":[{"b":"特殊","n":"嗜血者"}],"need":1,"t":["你可以以附贈動作對具有［鮮血印記］的生物進行一次近戰武器攻擊、近戰攻擊。"]},{"id":"m297","b":"武力","n":"暗黑騎士","c":2000,"t":["你獲得嘲諷強敵的能力，可以強迫他們不得不與你發生戰鬥。","一回合一次，消耗一個附贈動作對 30 尺內的一個敵方生物發動，對其進行一次魅力(威嚇)檢定。如你的魅力(威嚇)檢定大於敵方的被動感知(洞悉)值。該生物獲得[嘲諷]( {#詛咒})直到此次戰鬥結束或你對其他生物使用此能力。• [嘲諷]( {#詛咒})","◦ 所有對對施咒者以外的檢定獲得[施咒者魅力調整值]的減值。"]},{"id":"m298","b":"武力","n":"暗黑血鎧","c":2500,"req":"具有能力[【武力】暗黑騎士]","refs":[{"b":"武力","n":"暗黑騎士"}],"need":1,"t":["你將暗黑之力注入你的護甲之中，使其發揮超常的力量。","當你穿著[中甲]或[重甲]時，一回合一次你無視受到的第一次傷害，此效果直到你的回合結束無法再次使用。"]},{"id":"m299","b":"武力","n":"火炬聚集","c":1500,"req":"具有能力[【特殊】光明火炬]","refs":[{"b":"特殊","n":"光明火炬"}],"need":1,"t":["你周圍 5 尺每一名中型以上的友方生物會為你提供 1 點護甲等級(AC)與 1 點豁免加值，此能力最多可以提供的加值為[你的魅力調整值]。"]},{"id":"m300","b":"武力","n":"破壞者道途","c":1500,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["當你處於狂暴時，一回合一次，你以近戰武器攻擊命中生物將受到等同於[你熟練加值]的生命值傷害。如此次攻擊為重擊則此傷害為 2 倍。"]},{"id":"m301","b":"武力","n":"憎恨之擊","c":2000,"req":"具有能力[【武力】破壞者道途]","refs":[{"b":"武力","n":"破壞者道途"}],"need":1,"t":["你可以以一個動作發動一次帶著破壞與憤怒的近戰武器攻擊，此攻擊具有優勢，此外你在進行傷害骰投擲時你可以投擲 2 次，並將其相加作為此次攻擊的傷害。","你可以使用這個能力的次數等同於你的[力量調整值（最少為 1）]。你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m302","b":"武力","n":"隨手收割","c":2000,"req":"具有能力[【武力】破壞者道途]","refs":[{"b":"武力","n":"破壞者道途"}],"need":1,"t":["當你處於狂暴時，你可以在每次近戰武器攻擊時選擇相鄰 5尺的2個敵方生物為目標。如都命中，你可以選擇其中一個敵方生物受到此次攻擊的傷害 1/2 的傷害。"]},{"id":"m303","b":"武力","n":"無盡破壞","c":3500,"req":"具有能力[【武力】憎恨之擊]、[【武力】隨手收割]","refs":[{"b":"武力","n":"憎恨之擊"},{"b":"武力","n":"隨手收割"}],"need":2,"t":["當你處於狂暴時，你將一個敵方生物生命值歸零時，你的近戰武器攻擊傷害獲得+2 加值。此能力的攻擊傷害最多可以疊加至+10。當你結束狂暴或此次戰鬥結束時加值變為 0。"]},{"id":"m304","b":"武力","n":"蝕骨聖痕","c":2000,"req":"具有能力[【通用】蝕骨道途]","refs":[{"b":"通用","n":"蝕骨道途"}],"need":1,"t":["你與你製作的[蝕骨武器]產生一種奇妙的聯繫，當你狂暴並使用你製作的[蝕骨武器]你獲得下面一種聖痕效果。你在進入手持你製作的[蝕骨武器]進入狂暴時選擇聖痕效果。","聖痕","○ 散兵聖痕.","• 當你在狂暴時，當一個敵人在距離你 5 尺內結束它的回合，你能夠以一個反應移動最多等同於你移動速度一半的距離並在這個期間發動一次攻擊。這個移動並不會引發藉機攻擊。","○ 獵人聖痕.","• 當你在狂暴時，你的感知類技能檢定、感知豁免具有優勢，此外你在進行隱匿技能檢定時具有+5 的加值。","○ 大地樹懶聖痕.","• 當你在狂暴時，可使用一個附贈動作獲得[1D12+你的體質調整值]的臨時生命值。","○ 恐懼聖痕.","• 當你在狂暴時，可使用一個附贈動作對 30 尺內的一個生物進行威嚇與感知豁免的對抗，如對抗失敗將會使其以你為來源進入*[恐懼]*狀態，持續一輪。。","○ 巨獸聖痕.","• 當你在狂暴時，你獲得法術:『變巨術』的效果。"]},{"id":"m305","b":"武力","n":"蝕骨之力","c":2500,"req":"具有能力[【通用】蝕骨道途]","refs":[{"b":"通用","n":"蝕骨道途"}],"need":1,"t":["你製作的[蝕骨武器]會吸收你的你血液獲得更強的力量。","每次你失去 10 點生命值時你的[蝕骨武器]命中+1、傷害+1，此效果最多可以加 10 次，這個加值持續到這次戰鬥結束，或是你回復生命值。"]},{"id":"m306","b":"武力","n":"武藝家","c":1500,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"rep":1,"t":["你是如此的熟悉武器與戰鬥技巧，使得你可以在使用不同武器時發揮超出它原有效果的功能。","你獲得以下其中一個效果。","◆ 礫石山脈．一階","◇ 一回合一次，當你單手持用一把簡易近戰武器，且沒有持用其他武器時，你近戰攻擊命中時可以追加一次徒手打擊。","◇ 當你單手持用一把簡易近戰武器，且沒有持用其他武器時，你發動[疾風連擊]時可以以一次簡易近戰武器攻擊代替其中一次的徒手打擊。","◆ 繁花旋風．一階","◇ 當你使用具有[投擲]屬性的簡易武器投擲攻擊後，它們會在你的回合結束時回到你手上。","◇ 以一個附贈動作，消耗 1 點[氣]使你投擲攻擊後，一個你所投擲的簡易武器會直接以直線回返你手上，並對路徑上的一名敵方生物造成一次的武器傷害。","◆ 綠葉之道．一階","◇ 當你使用具有[觸及]屬性的簡易武器時，你的護甲等級(AC)獲得+1 的加值。","◇ 當你使用具有[觸及]屬性簡易的武器時，被選為攻擊目標，可以消耗 1 點[氣]以一個反應使你的護甲等級(AC)獲得+3 的加值，直到你的回合開始。","◆ 湖中之雨．一階","◇ 你在具有[靈巧]屬性的簡易武器上套上鎖鍊或繩鎖使其的近戰攻擊距離變為 15 尺。","◇ 當以此武器你命中一名生物使可以消耗 1 點[氣]與一個附贈動作使其進行一次力量(運動)或敏捷(特技)對抗，如對抗成功你可以使其伏地或被擒(擒抱者為你)。"]},{"id":"m307","b":"武力","n":"進階-武藝家","c":2000,"req":"具有能力[【武力】武藝家]","refs":[{"b":"武力","n":"武藝家"}],"need":1,"rep":1,"t":["你的武器熟練與戰鬥技巧，又更進一步了。","你獲得以下其中一個效果。","◆ 礫石山脈．二階","◇ 一回合一次，當你單手持用一把簡易近戰武器，且沒有持用其他武器時，你近戰攻擊命中時可以消耗 1 點[氣]使這次武器傷害具有優勢。","◆ 繁花旋風．二階","◇ 當你使用具有[投擲]屬性的簡易武器投擲攻擊檢定命中後，你可以消耗 1 點[氣]，使其飛向目標 20尺的你所指定另一個目標，其攻擊命中為原來的攻擊命中。","◆ 綠葉之道．二階","◇ 當你使用反應發動[綠葉之道．一階]成功避免命中時，你可以再消耗 1 點[氣]發動二次簡易近戰武器攻擊或徒手打擊。","◆ 湖中之雨．二階","◇ 當你發動[湖中之雨．一階]成功使其以使其*伏地*或*被擒*(擒抱者為你)時。你可以再消耗 1 點[氣]","使其變為束縛。"]},{"id":"m308","b":"武力","n":"高階-武藝家","c":2500,"req":"具有能力[【武力】進階-武藝家]","refs":[{"b":"武力","n":"進階-武藝家"}],"need":1,"rep":1,"t":["你的武器熟練與戰鬥技巧已經如火純青了。","你獲得以下其中一個效果。","◆ 礫石山脈．三階","◇ 當你單手持用一把簡易近戰武器，且沒有持用其他武器時，你的簡易近戰武器攻擊將在骰出18~20 時造成重擊。","◇ 以一個附贈動作，消耗 2 點[氣]，你將氣注入手持的單手簡易近戰武器使其的重擊閥值-2，直到這個回合結束。","◆ 繁花旋風．三階","◇ 當你發動[繁花旋風．二階]的效果時，你可以而外消耗[氣]指定另多個目標。每消耗 1 點[氣]指定的目標數目增加一個，不可為指定同樣的目標。","◇ 當你發動[繁花旋風．一階]的回返武器效果時，武器回返的數目沒有限制，但每個生物只能受到一次傷害。","◆ 綠葉之道．三階","◇ 一回合一次，如你具有反應動作，當你使用具有[觸及]屬性的武器藉機攻擊時無須消耗反應。","◇ 以一個附贈動作，消耗 2 點[氣]，你將氣注入手持的[觸及]屬性的武器中，所有進入或離開你[觸及]範圍的生物階會觸發你的藉機攻擊。直到你的下個回合開始。","◆ 湖中之雨．三階","◇ 當你發動[湖中之雨．一階]時你的技能檢定具有優勢，此外你可以再消耗 1 點[氣]使目標生物的技能檢定具有劣勢。","◇ 當你使用[湖中之雨．一階]、[湖中之雨．二階]效果時，目標會額外受到 1D6+你的力量或敏捷調整值的揮砍傷害。(對抗不必成功)"]},{"id":"m309","b":"武力","n":"原初合一","c":1500,"req":"具有能力[【特殊】原初門徒]","refs":[{"b":"特殊","n":"原初門徒"}],"need":1,"t":["在你的回合，當你攻擊命中時，如有[原初之靈]在你周圍 30 尺範圍內，你可以消耗其中一個[原初之靈]一點生命值使你此次的攻擊傷害獲得 1d8 的力場傷害或使[原初之靈]發動一次攻擊。"]},{"id":"m310","b":"武力","n":"血之獵人","c":2000,"t":["你獲得手弩的熟練。","你可以消耗一個附贈動作使用手弩發動一次攻擊。","你的手弩攻擊不會因周圍有敵方單位陷入劣勢。"]},{"id":"m311","b":"武力","n":"千錘百鍊","c":1500,"req":"具有能力[【武力】血之獵人]","refs":[{"b":"武力","n":"血之獵人"}],"need":1,"t":["當你使用手弩攻擊命中一個生物時其護甲等級(AC)-1，此效果直到此次戰鬥結束。","此效果每回合只會對同個生物生效一次。"]},{"id":"m312","b":"武力","n":"內臟暴擊","c":2000,"req":"具有能力[【武力】血之獵人]","refs":[{"b":"武力","n":"血之獵人"}],"need":1,"t":["以一個動作，你對[無力]狀態的生物發動一次特殊的近戰攻擊，此次攻擊必定命中，且為[重擊]。"]},{"id":"m313","b":"武力","n":"以盾為武","c":2000,"req":"具有盾牌熟練","t":["當你裝備{#盾牌}時它將同時視為軍用近戰武器，使用盾牌攻擊時具有 1D6 的鈍擊傷害。","盾牌可以裝備[裝備部位:武器]的詞綴，但此盾牌的[裝備部位:武器]詞綴效果只會在具有此能力的生物身上生效。"]},{"id":"m314","b":"武力","n":"雙重持盾","c":2000,"req":"具有盾牌熟練","t":["你現在可以同時裝備兩個{#盾牌}，並獲得兩個{#盾牌}所給予的護甲等級(AC)。","你再進行敏捷豁免或敏捷類技能豁免時必定為劣勢。"]},{"id":"m315","b":"武力","n":"神力引導﹝聖盾恩寵﹞","c":2000,"req":"具有能力[【特殊】神力引導]及具有盾牌熟練","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["當你裝備{#盾牌}時，以一個附贈動作消耗一個神力引導發動，選擇個 30 尺內除你以外[你的魅力調整值 (只少為 1)]個生物，其的護甲等級(AC)增加此{#盾牌}所其提供的護甲等級(AC)，持續 1 分鐘或你陷入無力狀態。","(如你裝備多個{#盾牌}則其選擇一個{#盾牌}所提供的加值)"]},{"id":"m316","b":"武力","n":"神力引導﹝聖盾衝擊﹞","c":1500,"req":"具有能力[【武力】神力引導﹝聖盾恩寵﹞]","refs":[{"b":"武力","n":"神力引導﹝聖盾恩寵﹞"}],"need":1,"t":["當你裝備{#盾牌}時，以一個附贈動作消耗一個神力引導發動，對 30 尺內除你選擇的任意生物造成[{#盾牌}所其提供的護甲等級(AC)]D10 的[力場傷害]，並通過一次體質豁免，失敗生物將會昏迷，持續到其受到傷害或其回合結束。","(如你裝備多個{#盾牌}則其選擇一個{#盾牌}所提供的加值)"]},{"id":"m317","b":"武力","n":"聖盾指引","c":2000,"req":"具有能力[【武力】神力引導﹝聖盾恩寵﹞]","refs":[{"b":"武力","n":"神力引導﹝聖盾恩寵﹞"}],"need":1,"t":["你選擇發動[【武力】神力引導﹝聖盾恩寵﹞]的生物將會獲得此{#盾牌}所給予的所有加成效果，持續至 [【武力】神力引導﹝聖盾恩寵﹞]的效果消失。"]},{"id":"m318","b":"武力","n":"鋒芒貫穿","c":1500,"req":"具有能力[【通用】神力引導﹝赦罪之眼﹞]與[【魔法】至聖斬]","refs":[{"b":"通用","n":"神力引導﹝赦罪之眼﹞"},{"b":"魔法","n":"至聖斬"}],"need":2,"t":["如果你未穿著{#重甲}時，當你使用一次遠程武器攻擊命中一個生物時，可以使用[【魔法】至聖斬]、 [【武力】強化至聖斬]的效果，但其所造成的[光耀傷害]d8 骰變為 d6 骰。"]},{"id":"m319","b":"武力","n":"強化·鋒芒貫穿","c":1500,"req":"具有能力[【武力】鋒芒貫穿]","refs":[{"b":"武力","n":"鋒芒貫穿"}],"need":1,"t":["因[【武力】鋒芒貫穿]所減少的[光耀傷害]d6 骰變為 d8 骰。"]},{"id":"m320","b":"武力","n":"權威化身","c":3000,"req":"具有能力[【武力】鋒芒貫穿]和[【通用】警覺靈光]","refs":[{"b":"武力","n":"鋒芒貫穿"},{"b":"通用","n":"警覺靈光"}],"need":2,"t":["以一個動作，你可以魔法性地變成律法的化身，在接下來 1 分鐘內獲得下列好處：","• [【魔法】至聖斬]、[【武力】強化至聖斬]使用的[光耀傷害]變成 d10 骰","• 對你的遠程攻擊具有[劣勢]。","• 你的遠程武器攻擊具有[優勢]。","• 你的遠程武器攻擊的[重擊]伐值-2。","這個效果會在你陷入[無力]狀態或[死亡]時提早結束。","一旦你使用此能力，直到你完成一次長休之前你都不能再使用它。"]},{"id":"m321","b":"武力","n":"屠龍之槍","c":2000,"t":["長年與巨龍搏鬥的經驗，使你對長柄武器的運用達到嶄新的境界。","當你使用具有［觸及］性質的武器攻擊時，攻擊檢定獲得 1D4 的加值。"]},{"id":"m322","b":"武力","n":"屠龍槍術-突龍擊","c":1500,"req":"具有能力[【武力】屠龍之槍]","refs":[{"b":"武力","n":"屠龍之槍"}],"need":1,"t":["你精通於空中作戰的技巧，能在半空中如同巨龍般同時移動與攻擊。你的槍術不再受地面束縛，而是化為凌空的突襲。","在你的回合且處於空中時，你可以使用【突龍擊】來取代你每一次的近戰武器攻擊。","【突龍擊】","消耗 X 尺移動力，向任一水平方向移動最多 X 尺，並發動一次近戰武器攻擊。(X 為近戰武器的攻擊距離)"]},{"id":"m323","b":"武力","n":"屠龍槍術-突龍槍破","c":2000,"req":"具有能力[【武力】屠龍槍術-突龍擊]","refs":[{"b":"武力","n":"屠龍槍術-突龍擊"}],"need":1,"t":["你將屠龍槍術修練至極，槍鋒不僅是鋼鐵的延伸，更能迸發如同龍息般的力場衝擊。每一次突擊都帶著毀滅性的威勢，令敵人無法分辨槍刃與衝擊的界線。","在你的回合中，一回合一次，當你使用【突龍擊】，可將其變為【突龍槍破】","【突龍槍破】","消耗 X 尺移動力，向任一水平方向移動最多 2×X 尺，並發動一次近戰武器攻擊，此次攻擊傷害額外獲得 X 點力場傷害。(X 為近戰武器的攻擊距離)"]},{"id":"m324","b":"武力","n":"屠龍槍術-星殞","c":2000,"req":"具有能力[【武力】屠龍槍術-突龍擊]","refs":[{"b":"武力","n":"屠龍槍術-突龍擊"}],"need":1,"t":["你將槍術與空戰技巧淬鍊至極，能在半空中化身隕落的星辰，以毀滅性的力量砸向敵人。這一擊象徵龍騎士的至高奧義，將天空的威勢化為致命的槍鋒。","在你的回合且處於空中時，你可以一個主要動作使用【星殞】。","【星殞】直落地面並對降落地點 5 尺範圍內的生物再造成(X/10)(四捨五入)D10 的力場傷害。","X 為你在空中時使用【星殞】前與地面的高度（以尺計算，最大為 100）。","如範圍內只有一名生物時，造成力場傷害為最大值。"]},{"id":"m325","b":"武力","n":"星殞爆裂","c":2500,"req":"具有能力[【武力】屠龍槍術-星殞]","refs":[{"b":"武力","n":"屠龍槍術-星殞"}],"need":1,"t":["你將「星殞」的力量推向極致，墜落的衝擊不再只是單點爆發，而是化為更廣闊的毀滅性震波。當你以隕星之姿墜下，槍鋒與大地的交會引發猛烈的能量爆裂，將更大範圍的敵人吞沒於衝擊之中。","當你使用【星殞】時，其範圍由 5 尺擴展為 15 尺。"]},{"id":"m326","b":"武力","n":"熔岩護甲","c":1500,"req":"具有能力［【特殊】怪獸變身］","refs":[{"b":"特殊","n":"怪獸變身"}],"need":1,"t":["當你以【荒野形態】化身時，熔岩的力量覆蓋你的身軀，形成一層炙熱的護甲。這股熔岩之力不僅能抵擋攻擊，更能化為燃燒的生命屏障，讓你在戰場上持續奮戰。","當你使用［【通用】荒野形態］能力變身時你將獲得 30 點的[臨時生命值]。如果原本就具有[臨時生命值] 則獲得的[臨時生命值]變為[30+你的能力數]。"]},{"id":"m327","b":"武力","n":"山火之怒","c":2000,"req":"具有能力［【特殊】怪獸變身］","refs":[{"b":"特殊","n":"怪獸變身"}],"need":1,"t":["當你以【荒野形態】化身時，炙烈的山火在你的血脈中燃燒，化為無窮的怒焰。你的天生武器不僅是肉體的延伸，更是火焰的媒介，每一次攻擊都帶著熔岩般的灼烈力量。","當你使用［【通用】荒野形態］能力變身時你的天生武器攻擊，且額外獲得 1D6 的火焰傷害。如果天生武器的傷害原本就具有火焰傷害則額外獲得火焰傷害變為 1D12。"]},{"id":"m328","b":"武力","n":"元素斬","c":2000,"req":"具有能力[【特殊】神力引導﹝巨靈盟約﹞]與[【魔法】至聖斬]","refs":[{"b":"特殊","n":"神力引導﹝巨靈盟約﹞"},{"b":"魔法","n":"至聖斬"}],"need":2,"t":["你能將至聖斬的神力引導至巨靈盟約之力，化為元素斬擊。每一次揮斬都帶著元素的威能，足以撼動天地。","當你使用[【魔法】至聖斬]時，可將其變為下面一種元素斬。","元素斬元素斬·土你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力]以對目標造成額外的[鈍擊傷害]。這個額外傷害在消耗 2[魔力]時為 3d8，每額外多消耗 1[魔力]則加上 1d8 傷害，最高至 6d8。","元素斬·火","你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力]以對目標造成額外的[火焰傷害]。這個額外傷害在消耗 2[魔力]時為 2d8，每額外多消耗 1[魔力]則加上 1d8 傷害，最高至 5d8。","元素斬·氣","你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力]以對目標造成額外的[閃電傷害]。這個額外傷害在消耗 2[魔力]時為 2d8，每額外多消耗 1[魔力]則加上 1d8 傷害，最高至 5d8。","元素斬·水","你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力]以對目標造成額外的[冰冷傷害]。這個額外傷害在消耗 2[魔力]時為 2d8，每額外多消耗 1[魔力]則加上 1d8 傷害，最高至 5d8。"]},{"id":"m329","b":"武力","n":"巨靈顯世","c":2500,"req":"具有能力[【特殊】元素靈光]及[【武力】元素斬]","refs":[{"b":"特殊","n":"元素靈光"},{"b":"武力","n":"元素斬"}],"need":2,"t":["以一個[主要動作]，你可以魔法性地變成巨靈的化身，在接下來 1 分鐘內獲得下列好處：","• 你的體型變大一級。","• 攻擊傷害骰增加一顆。","• 獲得[酸蝕傷害]、[雷鳴傷害]、[火焰傷害]、[閃電傷害]或[冰冷傷害]抗性。","• [【武力】元素斬]效果獲得加強:","◦ 元素斬·土→元素斬·大地震撼","▪ 你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力] 以對目標造成額外的[鈍擊傷害]，並其通過一次感知豁免(DC=8 + 你的熟練加值 + 你的魅力調整值)，如失敗該生物陷入[震懾]狀態。這個額外傷害在消耗 2[魔力]時為 3d8，每額外多消耗 1[魔力]則加上 1d8 傷害，最高至 6d8。","▪ 因此效果陷入[震懾]的生物可在其回合結束時，再進行一次感知豁免。若豁免成功，則結束[震懾]狀態。","◦ 元素斬·火→元素斬·烈焰爆裂","▪ 你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力] 以對目標造成額外的[火焰傷害]，並使攻擊命中的生物周圍 5 尺除你以外的生物受到此效果所造成[火焰傷害]一半的[火焰傷害]並陷入[燃燒]狀態。這個額外傷害在消耗 2[魔力]時為 2d8，每額外多消耗 1[魔力]則加上 1d8 傷害，最高至 5d8","◦ 元素斬·氣→元素斬·雷霆連鎖","▪ 你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力] 以對目標造成額外的[閃電傷害]，並使除攻擊目標外周圍 60 尺內最多三個你所指定的生物受到此效果所造成[閃電傷害]一半的[閃電傷害]。這個額外傷害在消耗 2[魔力] 時為 2d8，每額外多消耗 1[魔力]則加上 1d8 傷害，最高至 5d8。","◦ 元素斬·水→元素斬·冰封之握","▪ 你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力] 以對目標造成額外的[冰冷傷害]，並使該生物通過一次力量豁免(DC=8 + 你的熟練加值 + 你的魅力調整值)，如失敗該生物陷入[無力]狀態。這個額外傷害在消耗 2[魔力]時為 2d8，每額外多消耗 1[魔力]則加上 1d8 傷害，最高至 5d8。","▪ 因此效果陷入[無力] 的生物可在其回合結束時，再進行一次力量豁免。若豁免成功，則結束[無力]狀態。","這個效果會在你陷入[無力]狀態或[死亡]時提早結束。","一旦你使用此能力，直到你完成一次[長休]之前你都不能再使用它。"]},{"id":"m330","b":"武力","n":"神力引導﹝聖輝戰旗﹞","c":2000,"req":"具有能力 [【特殊】神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["你能以神力化為聖輝之旗，象徵信念與戰意的武器。當你引導此力量時，聖輝戰旗在你手中燃起光輝，成為你與盟友的精神支柱。","以一個 [附贈動作 Bonus Action ] 消耗一次 [神力引導] 發動，你高舉單手獲得一把 [聖輝戰旗] 武器並熟練於它，你也可以直接將受中裝備的一個武器變為獲得詞綴- [聖輝戰旗] ；持續一分鐘，或你[生命值 Hit Point] 為 0 時提前結束。","你一次只能有一個 [聖輝戰旗] 或 [聖輝戰旗] 詞綴的武器。","[聖輝戰旗] (特殊)","• 此物品的攻擊傷害為 [魔法傷害] 。","• 你可以使用 [感知] 屬性取代原來的攻擊屬性。","• 此物品獲得{#觸及}性質；武器攻擊傷害變為 1D12 [穿刺傷害] + 1D8 [光耀傷害]。","• 當此物品攻擊檢定、攻擊傷害 +1 (穿刺傷害) 。","• 10 尺範圍內除自身以外的友方生物攻擊檢定獲得 +1。({#靈光})"]},{"id":"m331","b":"武力","n":"鳳凰展翅","c":1000,"req":"具有能力 [【特殊】四象之勢]","refs":[{"b":"特殊","n":"四象之勢"}],"need":1,"t":["你展開雙臂，如同鳳凰振翅，烈焰隨氣息爆發而出。這股火焰不僅能焚燒敵人，更能化為戰場的烈焰之翼，象徵你在四象之勢中達到火焰的極致境界。","當你處於四象之勢-火的狀態時，作為攻擊動作的一部份，你可以消耗 2 點氣發動一次特殊的攻擊鳳凰展翅。","鳳凰展翅一片稀薄的火焰將從你伸展掌的指向前射出。","每個處於 15 尺錐形內的生物都必須進行一次{#敏捷豁免}。豁免失敗的生物將受到 3d6 + 四象之勢-火給予的 [火焰傷害 Fire] ，豁免成功則只受到一半的傷害。","這片火焰將會點燃範圍內所有未被穿戴或攜帶的可燃物體"]},{"id":"m332","b":"武力","n":"堅岩鎧","c":1000,"req":"具有能力 [【特殊】四象之勢]","refs":[{"b":"特殊","n":"四象之勢"}],"need":1,"t":["你引動大地的堅毅之力，瞬間化身為岩石鎧甲。這股力量在最危險的瞬間為你提供無與倫比的防禦，使你如同山岳般穩固不動。","當你處於四象之勢-土的狀態時，你可以 [反應 Reactions] 消耗 1 點氣點發動堅岩鎧。","堅岩鎧你將土石化作鎧甲覆於身軀，強化防禦。你的 [護甲等級 Armor Class （ AC ）] +3，並獲得四象之勢-土給予的護甲等級 Armor Class （ AC ）3 倍的臨時 [生命值 Temporary Hit Point] ，直到你的回合開始。"]},{"id":"m333","b":"武力","n":"鳳凰烈焰","c":2000,"req":"具有能力 [【武力】鳳凰展翅]","refs":[{"b":"武力","n":"鳳凰展翅"}],"need":1,"t":["你展開烈焰之翼，如同鳳凰浴火重生，將火焰化為毀滅性的直線衝擊。這股烈焰不僅能焚燒敵人，更能在戰場上留下持續的火海，象徵你在四象之勢中達到火焰的至高境界。","一回合一次，當你處於四象之勢-火的狀態時，作為攻擊動作的一部份，你可以消耗 4 點氣發動一次特殊的攻擊鳳凰烈焰。","鳳凰烈焰你將烈焰凝聚成鳳凰之翼，猛然向前爆發。","你朝任意方向衝刺最多 120 尺(不會觸發[反應 Reactions] )，並對路徑上的生物，行一次{#敏捷豁免}。豁免失敗的生物將受到 6d6+四象之勢-火給予的 [火焰傷害 Fire] 並使其陷入 [燃燒 Combustion] 狀態，豁免成功則只受到一半的傷害且不會陷入 [燃燒 Combustion] 狀態。","之後你經過路徑的變為[火焰地面]。","這片火焰將會點燃範圍內所有未被穿戴或攜帶的可燃物體。"]},{"id":"m334","b":"武力","n":"裏·蒼龍之拳","c":1500,"req":"具有能力 [【靈敏】流水之鞭]","refs":[{"b":"靈敏","n":"流水之鞭"}],"need":1,"t":["你將水之勢反轉為暗流，拳勁化為蒼龍的隱秘之力。這一擊不僅是水流的奔騰，更是暗潮的爆發，近距離的衝擊如同巨龍伏擊，能瞬間震懾敵人，使其在水流的壓制下失去反抗之力。","當你處於四象之勢-水的狀態時，作為攻擊動作的一部份，你可以消耗 4 點氣發動一次特殊的攻擊裏·蒼龍之拳。","裏·蒼龍之拳","你以水流化為蒼龍，轟擊敵人身體內部。","對一個距離你 5 尺的生物發動一次近戰 [攻擊 Attack] ，若攻擊命中，該生物將受額外 6d10 + 四象之勢-水給予的攻擊距離尺(以尺數換算為傷害加值)的 [鈍擊傷害 Bludgeoning] ，且你可以將它 [震懾 Stunned]。"]},{"id":"m335","b":"武力","n":"巖龍途","c":2000,"req":"具有能力 [【武力】堅岩之鎧 ]","refs":[{"b":"武力","n":"堅岩鎧"}],"need":1,"t":["你引動大地的堅毅之力，瞬間化身為岩石鎧甲。這股力量在最危險的瞬間為你提供無與倫比的防禦，使你如同山岳般穩固不動。","一回一次，當你處於四象之勢-土的狀態時，作為攻擊動作的一部份，你可以消耗 4 點氣發動一次特殊的攻擊巖龍途。","巖龍途你腳踏地面召喚一條岩石之龍分隔戰場。","你於自身周圍 60 尺的可見範圍內，於地面上一點，召喚一條 30 尺長、 5 尺寬、 10 尺高的岩石障壁，岩石障壁持續至多 10 分鐘，或你以一個[附贈動作 Bonus Action] 將其消除。","當岩石障壁途形成時，範圍內的所有生物必須進行一次{#力量豁免}，若豁免失敗，其將受到 3d10 [鈍擊傷害 Bludgeoning] ，並由你決定他將被岩石障壁推離至哪側。若豁免成功，則受到一半的 [鈍擊傷害 Bludgeoning] 一半，且可以自行決定被岩石障壁推離至哪側。","岩石障壁上方無法有任何生物停留或佔據。若有生物在障壁形成時位於該範圍，則會被隨機推至最近的未被佔據空間。"]},{"id":"m336","b":"靈敏","n":"越野","c":2000,"t":["你獲得等於你步行速度的攀爬速度和游泳速度。"]},{"id":"m337","b":"靈敏","n":"移動力增加","c":2000,"t":["你的所有移動速度增加 10 尺。"]},{"id":"m338","b":"靈敏","n":"曲射","c":1500,"t":["你學會如何將偏離的箭矢導向一個新的目標。","當你使用遠程攻擊進行一次攻擊檢定並失手時，你可以使用一個附贈動作以對一個距離原本目標 60 尺內的不同目標重骰該攻擊檢定。"]},{"id":"m339","b":"靈敏","n":"直覺閃避","c":1500,"t":["當一個你所能看見的攻擊者使用一次攻擊命中你，你可以使用你的反應以減半該次攻擊對你的傷害。(包含因此次攻擊命中所造成的傷害效果)"]},{"id":"m340","b":"靈敏","n":"金蟬脫鞘","c":1000,"t":["你在掙脫受移動限制時所進行的力量（運動）或敏捷（特技）檢定有優勢。"]},{"id":"m341","b":"靈敏","n":"大地行者","c":2000,"t":["移動穿過非魔法的困難地型並不會花費你其餘的移動速度。","你也可以穿越非魔法植物而不會被它們減緩速度，若它們是荊棘、棘刺、或其他類似危險，你也不會被它們的傷害。","此外，在對抗由魔法創造或控制的植物所造成的阻礙移動效果時（像是糾纏術法術創造出的植物），你所進行的豁免檢定具有優勢。"]},{"id":"m342","b":"靈敏","n":"無影步","c":2000,"t":["你可以在你的回合以一個附贈動作採取躲藏動作，此次躲藏具有優勢。","同時，你不會被非魔法的手段追蹤，除非你選取留下蹤跡。"]},{"id":"m343","b":"靈敏","n":"霧隱漫步","c":1000,"req":"具有能力[【魔法】妖精漫游者]","refs":[{"b":"魔法","n":"妖精漫游者"}],"need":1,"t":["你習得『迷蹤步』法術，這個法術這不會使用你的法術容量。","你可以在眨眼之間穿梭妖精荒原以進行移動：你可以施展『迷蹤步』而不需要消耗[魔力]。你可以這樣做的次數等於你的感知調整值（最低一次），你在完成一次長休后重獲所有的使用次數。"]},{"id":"m344","b":"靈敏","n":"妖影幻霧","c":1000,"req":"具有能力[【特殊】妖精威儀]","refs":[{"b":"特殊","n":"妖精威儀"}],"need":1,"t":["你可以在受到傷害時於一團迷霧中消失無蹤。","每當你受到傷害時，你可以使用你的反應變得隱形，並傳送最遠 60 尺距離到一處你所能看見的未被占據空間。你保持隱形狀態直到你的下個回合開始，或直到你攻擊或施放法術。","一旦你使用此能力，直到你完成一次短休或長休之前你都不能再使用它。"]},{"id":"m345","b":"靈敏","n":"霧隱漫步-同行者","c":1000,"req":"具有能力[【靈敏】霧隱漫步]","refs":[{"b":"靈敏","n":"霧隱漫步"}],"need":1,"t":["每當你施展『迷蹤步』法術時，你可以攜帶一個 5 尺以內你看得見的自願生物與你一起移動。那個生物會被傳輸到由你選取的一個位於你的目標位置 5 尺以內的未被占據空間。"]},{"id":"m346","b":"靈敏","n":"幽影追蹤者","c":2000,"t":["你精通於伏擊的藝術。你可以讓你先攻檢定獲得等同於你感知調整值的加值。","在每個戰鬥的你的第一個回合開始時，你的移動速度增加 10 尺，持續直到該回合結束。若你在該回合採取攻擊動作，作為該動作的一部份，你可以進行一次其餘的武器攻擊。若該攻擊命中，則目標將受到其餘 1d8 該武器傷害類別的傷害。","你獲得 60 尺範圍的黑暗視覺。若你已經擁有來自其他能力的的黑暗視覺，則它的範圍將增加 30 尺。","你也擅長於避開依賴於黑暗視覺的生物。當處於黑暗環境時，你對任何嘗試依靠黑暗視覺以看見黑暗中的你的生物而言處於隱形狀態。"]},{"id":"m347","b":"靈敏","n":"暗影閃避","c":1500,"req":"具有能力[【靈敏】幽影追蹤者]","refs":[{"b":"靈敏","n":"幽影追蹤者"}],"need":1,"t":["隨着一縷自動換行在你身邊的超自然陰影，你能夠以令人無法預料的方式閃躲。","當一個生物對你進行一次攻擊檢定且該檢定不具有優勢，你可以使用你的反應以讓它承受劣勢。","你必須在你知道該攻擊檢定的結果之前決定是否使用此能力。"]},{"id":"m348","b":"靈敏","n":"暗影閃避-陰影守衛","c":1000,"req":"具有能力[【靈敏】暗影閃避]","refs":[{"b":"靈敏","n":"暗影閃避"}],"need":1,"t":["當你使用 [【靈敏】暗影閃避] 能力時，就算你被攻擊命中了，你只需要承受本次攻擊 1/2 的傷害。(包含因此次攻擊命中所造成的傷害效果)"]},{"id":"m349","b":"靈敏","n":"虛體防禦","c":1500,"req":"具有能力[【通用】位面戰士]","refs":[{"b":"通用","n":"位面戰士"}],"need":1,"t":["你穿梭在位面之間的能力讓你得以溜進位面邊線以減輕你在戰鬥中所受到的傷害。","當你受到來自於一次攻擊的傷害時，你可以使用你的反應以讓你自己獲得所有這回合所有傷害的抗性。"]},{"id":"m350","b":"靈敏","n":"虛體防禦-傳輸者","c":1000,"req":"具有能力[【靈敏】虛體防禦]","refs":[{"b":"靈敏","n":"虛體防禦"}],"need":1,"t":["當你使用[虛體防禦]時，你可以傳輸最多 15 尺距離到一處你所能看見的未被占據空間。"]},{"id":"m351","b":"靈敏","n":"翻騰浪湧","c":1000,"req":"具有能力[【特殊】蜂聚集群]","refs":[{"b":"特殊","n":"蜂聚集群"}],"need":1,"t":["你能將你的集群的一部分凝聚成一股集中的力量，來將你托起。","以一個附贈動作，你獲得額外 10 尺飛行速度並且能懸浮在空中。該效應持續 1 分鐘或直到你陷入無力狀態。你能使用該能力的次數等於你的熟練加值，而你在結束一次長休后重新獲得所有消耗的次數。"]},{"id":"m352","b":"靈敏","n":"群逸逃散","c":1500,"req":"具有能力[【特殊】蜂聚集群]","refs":[{"b":"特殊","n":"蜂聚集群"}],"need":1,"t":["你能將自己散入集群來躲避危險。","當你受到傷害時，你能使用你的反應動作讓自己此次受到的傷害減半，直到此回合結束你獲得所有的抗性。你消失在自己的集群之中，然后傳輸至 30 尺內一個未被占據的空間，你在那裡與自己的集群一同重新出現。","你能使用該特徴的次數等於你的熟練加值，而你在結束一次長休后重新獲得所有消耗的次數。"]},{"id":"m353","b":"靈敏","n":"靈巧動作","c":2500,"t":["你的機智和靈巧讓你得以快速地移動和行動。","你可以在戰鬥中每個你的回合採取一個附贈動作。這個附贈動作只能被用於採取疾走、撤離或躲藏。"]},{"id":"m354","b":"靈敏","n":"刺客","c":1500,"t":["你在先發制人的時刻是最致命的。","你對任何在戰鬥中尚未行動過的生物所進行的攻擊檢定具有優勢。此外，任何你命中被突襲生物的攻擊都是重擊。"]},{"id":"m355","b":"靈敏","n":"刺客身法","c":2000,"req":"具有能力[【靈敏】刺客]","refs":[{"b":"靈敏","n":"刺客"}],"need":1,"t":["若你此回合攻擊命中，直到此下次你的回合開始前對你的攻擊具有劣勢。"]},{"id":"m356","b":"靈敏","n":"斥侯","c":1000,"t":["你在戰鬥中變得難以被壓制。","當一個敵人在距離你 5 尺內結束它的回合，你能夠以一個反應移動最多等同於你移動速度一半的距離。這個移動並不會引發藉機攻擊。"]},{"id":"m357","b":"靈敏","n":"伏擊大師","c":2000,"t":["你擅長於率領伏擊並在戰鬥中第一個行動。","你在先攻檢定中具有優勢。","此外，你在戰鬥中第一輪命中的第一個生物對你和其他人而言將更容易被擊中，直到你的下個回合開始，對該目標所進行的任何攻擊檢定都將具有優勢。"]},{"id":"m358","b":"靈敏","n":"風流劍客","c":2500,"req":"具有能力[【靈敏】偷襲Ⅰ]","refs":[{"b":"靈敏","n":"偷襲Ⅰ"}],"need":1,"t":["你學會下面兩個能力:","• 華麗步法.","◦ 你學會如何降下打擊並接着迅速溜走而不至遭受反擊。","◦ 在你的回合期間，若你對一個生物進行了一次近戰攻擊(不需要命中)，該生物在該回合間將無法對你進行藉機攻擊。","• 放蕩無謂.","◦ 你的自信驅使着你加入戰鬥。","◦ 你可以讓你先攻檢定獲得等同於你魅力調整值的加值。","◦ 也獲得一種使用你偷襲能力的額外手段；若你對一個距離你 5 尺內的生物進行攻擊，沒有其他生物距離你 5 尺內，且你在該攻擊檢定中不具有劣勢，則你不需要在該攻擊檢定中具有優勢而仍能對該生物使用你的偷襲能力。所有其他偷襲的規則仍舊適用於你。"]},{"id":"m359","b":"靈敏","n":"優雅戰舞","c":1000,"req":"具有能力[【靈敏】風流劍客]","refs":[{"b":"靈敏","n":"風流劍客"}],"need":1,"t":["你可以在你的回合使用一個附贈動作，以使你在同個回合內所進行的下一個敏捷（體操）或力量（運動）檢定中具有優勢。"]},{"id":"m360","b":"靈敏","n":"優雅戰舞-進行曲","c":1000,"req":"具有能力[【靈敏】優雅戰舞]","refs":[{"b":"靈敏","n":"優雅戰舞"}],"need":1,"t":["你可以在你的回合使用一個附贈動作，直到自身的下個自己回合結束，你的移動速度增加 10 尺。"]},{"id":"m361","b":"靈敏","n":"竊盜者","c":1500,"req":"具有能力[【靈敏】靈巧動作]","refs":[{"b":"靈敏","n":"靈巧動作"}],"need":1,"t":["你學會下面兩個特性:","• 快手.","你可以使用你靈巧動作能力所賦予的附贈動作來進行一次敏捷（巧手）檢定、使用你的工具以解除陷阱或開鎖、或採取使用物件動作。","• 梁上君子.","你獲得能攀爬的比原本更快的能力；攀爬不再需要花費你額外的移動速度。","此外，當你進行助跑跳躍時，你可以跨越的距離將增加等同於你敏捷調整值╳5 的尺數。"]},{"id":"m362","b":"靈敏","n":"潛行者","c":1000,"t":["若你移動不超過你移動速度一半的距離，你在同個回合所進行的敏捷（隱匿）檢定中具有優勢。"]},{"id":"m363","b":"靈敏","n":"盜賊的極藝","c":3000,"req":"具有能力[【靈敏】竊盜者]","refs":[{"b":"靈敏","n":"竊盜者"}],"need":1,"t":["你已成為了伏擊與快速逃離危險的行家。","你在任何戰鬥的第一輪中可以直接進行二個回合。你在你正常的先攻值進行你的第一個回合，並在你先攻值減 10 的順序進行你的第二個回合。你不能在你被突襲的時候使用這個能力。"]},{"id":"m364","b":"靈敏","n":"狂暴衝刺","c":1000,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["作為你進入狂暴的附贈動作的一部分，你可以移動最多等同於你移動速度一半的距離。"]},{"id":"m365","b":"靈敏","n":"撥擋飛彈","c":1000,"t":["當你被一次遠程武器攻擊命中時，你可以使用你的反應以撥擋或抓住該投射物。當你這麼做時，你從該攻擊所受到的傷害將會減少 1d10 + 你的敏捷調整值 + 你的熟練值的 2 倍。"]},{"id":"m366","b":"靈敏","n":"投擲·撥擋飛彈","c":1000,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["當你被一次遠程武器攻擊命中時，你可以使用你的反應以撥擋或抓住該投射物。當你這麼做時，你從該攻擊所受到的傷害將被減少 1d10 + 你的敏捷調整值 + 你的熟練值的 2 倍。","若你將該傷害降低至 0，且若該投射物的大小能夠被你單手抓住且你有至少一只空手，則你可以抓住該投射物。若你通過這個方式抓住一個投射物，你可以消耗 1 點氣，作為你該次反應的一部份，使用你剛抓到的武器或彈藥進行一次遠程攻擊（範圍 20/60）。無論你的武器熟練如何，你都熟練於該次攻擊，且該投射物在此攻擊中被視作簡易武器。傷害為原來投射物的攻擊傷害。"]},{"id":"m367","b":"靈敏","n":"撥擋飛彈·極","c":1000,"req":"具有能力[【靈敏】投擲·撥擋飛彈]","refs":[{"b":"靈敏","n":"投擲·撥擋飛彈"}],"need":1,"t":["當你被一次遠程攻擊命中時，你可以消耗一點氣發動[【靈敏】投擲·撥擋飛彈]的能力。"]},{"id":"m368","b":"靈敏","n":"輕身墜","c":1000,"t":["當你墜落時，你可以使用你的反應以將任何你所受到的墜落傷害減少等同於你 10 倍敏捷調整值的數值。"]},{"id":"m369","b":"靈敏","n":"醉拳","c":1000,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["你學會如何在疾風連擊中快速的翻轉扭動。每當你使用疾風連擊時，你將同時獲得撤離動作的好處，且直到該回合結束前，你的移動速度將增加 10 尺。"]},{"id":"m370","b":"靈敏","n":"鯉魚打挺","c":500,"req":"具有能力[【靈敏】醉拳]","refs":[{"b":"靈敏","n":"醉拳"}],"need":1,"t":["當你處於伏地狀態時，你可以借由消耗 5 尺移動速度力來起身，而非消耗你移動速度的一半。"]},{"id":"m371","b":"靈敏","n":"暗影步伐","c":1000,"req":"具有能力[【魔法】影之技藝]","refs":[{"b":"魔法","n":"影之技藝"}],"need":1,"t":["你獲得穿梭於陰影之間的能力。","當你處於微光光照或黑暗環境時，以一個附贈動作並消耗一點氣，你可以傳送最多 60 尺距離到一處你所能看見，且同樣處於微光光照或黑暗環境的未被占據空間。接着你在該回合結束前所進行的第一次近戰攻擊檢定中具有優勢。"]},{"id":"m372","b":"靈敏","n":"龍之翼","c":1500,"req":"具有能力[【通用】龍之血脈]","refs":[{"b":"通用","n":"龍之血脈"}],"need":1,"t":["你獲得從你背后長出一對龍翼的能力，獲得等同於你當下速度的飛行速度。你可以在你的回合以一個附贈動作創造這對龍翼。它們會持續一分鐘直到你在你的回合以一個附贈動作解消它們。","你無法在你穿戴護甲時操作這對龍翼，除非該護甲是為了容納它們而被打造。此外，未被設計於容納你龍翼的服裝將在你操作龍翼的時候被破壞。"]},{"id":"m373","b":"靈敏","n":"終焉之步","c":1500,"req":"具有能力[【特殊】終焉之力]","refs":[{"b":"特殊","n":"終焉之力"}],"need":1,"t":["你獲得從陰影間穿梭的能力。","當你處於微光光照或黑暗環境中，以一個附贈動作消耗 1[魔力]，你可以用魔法傳送最多 120 尺距離到一處你所能看見，且同樣處於微光光照或黑暗環境中的未被占據空間。"]},{"id":"m374","b":"靈敏","n":"風暴魔法","c":1500,"t":["當你以一個動作施放一個一環或更高環的法術之前或之后，作為動作的一部分以使元素之氣形成的旋轉陣風短暫地環繞着你。這麼做讓你得以飛行最多 10 尺距離，而不會引發藉機攻擊。"]},{"id":"m375","b":"靈敏","n":"迅捷靈光","c":2500,"req":"具有能力[【特殊】神力引導﹝絕倫健將﹞]","refs":[{"b":"特殊","n":"神力引導﹝絕倫健將﹞"}],"need":1,"t":["你散發出一道能使你和你的盟友獲得超自然速度的靈光，從而能夠列隊穿越戰場。","你獲得 10 尺的額外移動速度。此外，若你未昏迷，則在你 5 尺內開始其回合的友方生物獲得 10 尺的額外移動速度，直至該回合結束。"]},{"id":"m376","b":"靈敏","n":"迅捷靈光擴展","c":2000,"req":"具有能力[【靈敏】迅捷靈光]","refs":[{"b":"靈敏","n":"迅捷靈光"}],"need":1,"t":["你的[【靈敏】迅捷靈光]範圍增加至 30 尺。"]},{"id":"m377","b":"靈敏","n":"輝煌防禦","c":2500,"req":"具有能力[【特殊】神力引導﹝絕倫健將﹞]","refs":[{"b":"特殊","n":"神力引導﹝絕倫健將﹞"}],"need":1,"t":["你能夠抵御突然的襲擊。","當你或你 10 尺內一個你可見的生物成為一次攻擊的目標並被擊中時，你可以用反應使其獲得 AC 加值，此舉可能使該次攻擊失敗。此加值等同於你的魅力調整值（至少為+1）。若該次攻擊的結果為失敗，且攻擊者在你的武器攻擊範圍內，你可以對其進行一次武器攻擊，視為此反應的一部分。","你可以使用此能力的次數等同於你的魅力調整值（至少 1 次）。每當你完成一次長休息，你重新獲得已消耗的使用次數。"]},{"id":"m378","b":"靈敏","n":"無盡復仇","c":1500,"req":"具有能力[【特殊】神力引導﹝誓絕仇敵﹞]","refs":[{"b":"特殊","n":"神力引導﹝誓絕仇敵﹞"}],"need":1,"t":["你的超常專注將協助你阻止敵人撤退。","當你以一次藉機攻擊命中一個生物時，你可以在攻擊之后作為該反應的一部份，立刻移動最多等同於你移動速度一半的距離。這個移動並不會引發藉機攻擊。"]},{"id":"m379","b":"靈敏","n":"融身入影","c":2000,"t":["當你處於微光光照或黑暗區域時，你可以使用你的主要動作變為隱形狀態，直到你移動或採取主要動作、附贈動作或反應。"]},{"id":"m380","b":"靈敏","n":"潜行者","c":2500,"t":["你是潛行於陰影中的專家。你獲得下列好處：","• 當你對於你想躲避的生物而言處於輕度遮蔽時，你可以嘗試躲藏。","• 當你對某個生物而言躲藏狀態，且你對它進行的遠程武器攻擊失手，則進行該攻擊並不會因此暴露你的位置。","• 微光光照不會對你依賴於視覺的感知（察覺）檢定造成[劣勢]。"]},{"id":"m381","b":"靈敏","n":"防御式決鬥","c":1500,"t":["當你持握一把你所熟練的靈巧武器，且另一個生物以近戰攻擊命中了你時，你可以針對此次攻擊使用你的 [反應]將你的熟練加值加到 AC 上，這可能會讓該攻擊因此失手。"]},{"id":"m382","b":"靈敏","n":"哨兵","c":2500,"t":["你精通在敵人防御時占盡優勢的技巧，獲得下列好處：","• 當你以藉機攻擊命中一個生物時，該生物在該回合剩下時間的移動速度變為 0。","• 離開你觸及範圍的生物即使採取了撤離動作，仍然會觸發你的藉機攻擊。","• 當一個與你距離 5 尺內的生物對你以外的目標進行了一次攻擊，你可以使用你的反應對該攻擊者進行一次近戰武器攻擊。"]},{"id":"m383","b":"靈敏","n":"消失無蹤","c":1500,"t":["在你受到傷害后，你可以使用一個反應變得隱形直到你的下個回合結束，或直到你攻擊、造成傷害、或強迫某人進行一次豁免檢定。","一旦你使用此能力，直到你完成一次短休或長休之前都無法再使用此能力。"]},{"id":"m384","b":"靈敏","n":"神射手","c":2000,"t":["你精通於遠程武器，且能夠做出他人眼中不可能的射擊。你獲得下列好處：","• 攻擊長射程範圍中的目標並不會讓你的遠程武器攻擊檢定因此獲得劣勢。","• 你的遠程武器攻擊忽略半掩護和四分之三掩護。","• 在你以所熟練的遠程武器進行攻擊之前，你可以選擇讓該次攻擊檢定承受-5 的減值。若該次攻擊命中，該次攻擊的傷害+10。"]},{"id":"m385","b":"靈敏","n":"強弩專家","c":2000,"t":["多虧你在弩上投入的大量訓練，你獲得下列好處：","• 你忽略你所熟練的弩上的裝填屬性。","• 當你使用弩時處於敵對生物 5 尺距離內並不會讓你的遠程攻擊獲得劣勢。","• 當你採取攻擊動作並且以單手武器攻擊，你可以使用附贈動作以一把你持握的手弩進行攻擊。"]},{"id":"m386","b":"靈敏","n":"解放靈光","c":2000,"req":"具有能力[【特殊】神力引導﹝海雲﹞]","refs":[{"b":"特殊","n":"神力引導﹝海雲﹞"}],"need":1,"t":["只要你未處於無力，你和距離你 10 尺內你選擇的生物都不會被擒抱或束縛，且你們無視水下環境的移動和攻擊懲罰。","此外已經被擒抱或束縛的生物也可以花費 5 尺移動速度以自行從非魔法束縛中逃脫。"]},{"id":"m387","b":"靈敏","n":"神話浪客","c":2500,"req":"具有能力[【靈敏】解放靈光]及[【武力】驚濤駭浪]","refs":[{"b":"靈敏","n":"解放靈光"},{"b":"武力","n":"驚濤駭浪"}],"need":2,"t":["你學會引導歷代水手的英魂，短暫地化身為冒險史詩中的英傑。","以一個動作，你擁抱大海的靈魂，在接下來 1 分鐘內獲得下列好處：","• 你在力量（運動）檢定中具有優勢，並獲得等同於你步行速度的攀爬速度。如果你已有攀爬速度，其變為兩倍。","• 若你對一個距離你 5 尺內的生物進行攻擊，沒有其他生物距離你 5 尺內，則你在該攻擊檢定中具有優勢。","• 你可以使用一個附贈動作採取疾走或撤離動作。","• 你在敏捷檢定中具有優勢，且你在對抗你所能見的效果時所進行的敏捷豁免中具有優勢。","• 如你使用具有[靈巧]屬性的的近戰武器進行攻擊時，此攻擊的傷害具有優勢。","一旦你使用此能力，直到你完成一次長休之前你都不能再使用此能力。"]},{"id":"m388","b":"靈敏","n":"舞鬥士","c":1500,"t":["在戰場上你利用靈活的移動來戲弄他人。","一回合一次，當你在自身的回合移動 10 尺以上時，你的下一次近戰武器攻擊命中具有優勢。"]},{"id":"m389","b":"靈敏","n":"靈動步法","c":1500,"req":"具有能力[【靈敏】舞鬥士]","refs":[{"b":"靈敏","n":"舞鬥士"}],"need":1,"t":["你可以步法迷惑敵人，並突破敵人的陣型。","一回合一次以一個附贈動作發動，進行一次力量(運動)檢定或敏捷(特技)檢定。若超過敵方的 AC，則你此回合可自由的穿過他，且他對你的藉機攻擊為劣勢。"]},{"id":"m390","b":"靈敏","n":"劍刃滾滾","c":2000,"req":"具有能力[【靈敏】靈動步伐]","refs":[{"b":"靈敏","n":"靈動步法"}],"need":1,"t":["你的技巧已到達頂點，使你可以在快速移動或迴避時同時攻擊敵人。","當你進行疾走、撤離動作(包含附贈動作)時你可以同時進行一次近戰武器攻擊。"]},{"id":"m391","b":"靈敏","n":"靈動步法·劍刃滾滾","c":2000,"req":"具有能力[【靈敏】劍刃滾滾]","refs":[{"b":"靈敏","n":"劍刃滾滾"}],"need":1,"t":["當你穿過敵方生物時你可以對他發動一次近戰武器攻擊，此次攻擊為劣勢。但每個生物每回合只能發動一次攻擊。"]},{"id":"m392","b":"靈敏","n":"街頭技巧","c":2000,"req":"具有能力[【通用】街頭混混]及[【靈敏】偷襲Ⅰ]","refs":[{"b":"通用","n":"街頭混混"},{"b":"靈敏","n":"偷襲Ⅰ"}],"need":2,"t":["你學會如何使用一些技巧削弱與迷惑與你戰鬥的敵人。","你習得下面 2 種街頭技巧。","在你以{#近戰攻擊}造成偷襲傷害時，你可以宣言減少此回合[機顆偷襲傷害骰]使用下面一個的街頭技巧，你也可以在攻擊命中時直接消耗一個 [附贈動作 Bonus Action] 直接使用街頭技巧， [附贈動作 Bonus Action] 將視為[2 顆偷襲傷害骰]。每次攻擊只能使用一次街頭技巧。街頭技巧的效果會持續至該生物的回合結束。","街頭技巧","◆ 狠踢封路:","• 消耗 [2 顆偷襲傷害骰] ，重擊目標的腳跟，使他無法進行『撤離 Disengage』、『疾走 Dash』動作，此外其移動速度減少 10 尺。","◆ 落地消息:","• 消耗 [2 顆偷襲傷害骰] ，使目標無法維持重心， [伏地 Prone] 。","◆ 削防條款:","• 消耗 [2 顆偷襲傷害骰] ，使其的[護甲等級 Armor Class （ AC ）]-2。","• 每額外消耗 [1 顆偷襲傷害骰] [護甲等級 Armor Class （ AC ）] 再減 1。最多可以使 [護甲等級 Armor Class （ AC ）] -5 。","◆ 靜音處理:","• 消耗 [2 顆偷襲傷害骰] ，使其進入 [耳聾 Deafened] 狀態。","◆ 封視處理:","• 消耗 [4 顆偷襲傷害骰] ，使其進入[目盲 Blinded ]狀態。","◆ 初音未來:","• 消耗 [4 顆偷襲傷害骰] ，使其無法發出聲音。","◆ 不給你動:","• 消耗[4 顆偷襲傷害骰]，使其通過一次{#敏捷豁免} (DC= 15 )否則進入其到下一回合結束前獲得[緩速術 Slow] 的{#法術}效果。","• 每額外消耗 [1 顆偷襲傷害骰] DC 豁免 +1 。","◆ 魂卡一格:","• 消耗[4 顆偷襲傷害骰]，使其通過一次{#體質豁免} (DC= 15 )否則進入 [震懾 Stunned] 狀態。","• 每額外消耗 [1 顆偷襲傷害骰] DC 豁免 +1 。"]},{"id":"m393","b":"靈敏","n":"更多技巧","c":1500,"req":"具有能力[【靈敏】街頭技巧]","refs":[{"b":"靈敏","n":"街頭技巧"}],"need":1,"rep":1,"t":["你習得下面一個街頭技巧。","街頭技巧","◆ 狠踢封路:","• 消耗 [2 顆偷襲傷害骰] ，重擊目標的腳跟，使他無法進行『撤離 Disengage』、『疾走 Dash』動作，此外其移動速度減少 10 尺。","◆ 落地消息:","• 消耗 [2 顆偷襲傷害骰] ，使目標無法維持重心， [伏地 Prone] 。","◆ 削防條款:","• 消耗 [2 顆偷襲傷害骰] ，使其的[護甲等級 Armor Class （ AC ）]-2。","• 每額外消耗 [1 顆偷襲傷害骰] [護甲等級 Armor Class （ AC ）] 再減 1。最多可以使 [護甲等級 Armor Class （ AC ）] -5 。","◆ 靜音處理:","• 消耗 [2 顆偷襲傷害骰] ，使其進入 [耳聾 Deafened] 狀態。","◆ 封視處理:","• 消耗 [4 顆偷襲傷害骰] ，使其進入[目盲 Blinded ]狀態。","◆ 初音未來:","• 消耗 [4 顆偷襲傷害骰] ，使其無法發出聲音。","◆ 不給你動:","• 消耗[4 顆偷襲傷害骰]，使其通過一次{#敏捷豁免} (DC= 15 )否則進入其到下一回合結束前獲得[緩速術 Slow] 的{#法術}效果。","• 每額外消耗 [1 顆偷襲傷害骰] DC 豁免 +1 。","◆ 魂卡一格:","• 消耗[4 顆偷襲傷害骰]，使其通過一次{#體質豁免} (DC= 15 )否則進入 [震懾 Stunned] 狀態。","• 每額外消耗 [1 顆偷襲傷害骰] DC 豁免 +1 。"]},{"id":"m394","b":"靈敏","n":"高速陷阱佈置","c":2000,"req":"具有能力[【通用】守林人]","refs":[{"b":"通用","n":"守林人"}],"need":1,"t":["你可使用一個動作於自身五尺範圍佈置守林人陷阱。佈置的守林人陷阱會在你的回合結束後變得可以被 [觸發]。"]},{"id":"m395","b":"靈敏","n":"自然精準","c":1500,"req":"具有能力[【通用】守林人]","refs":[{"b":"通用","n":"守林人"}],"need":1,"t":["當你將一個擁有[掩護]的生物為目標時，他的[掩護]等級視作減一級。(將[全掩護]視為[四分之三掩護]、 [四分之掩護]視為[半掩護]、[半掩護]視為無[掩護])"]},{"id":"m396","b":"靈敏","n":"自然守護者","c":1000,"req":"具有能力[【通用】守林人]","refs":[{"b":"通用","n":"守林人"}],"need":1,"t":["當有生物[觸發]你的守林人陷阱時，你可以用反應對他發動一次攻擊。"]},{"id":"m397","b":"靈敏","n":"陷阱雲海","c":2500,"req":"具有能力[【靈敏】高速陷阱佈置]、[【通用】大範圍陷阱]、[【特殊】高能陷阱]三個","refs":[{"b":"靈敏","n":"高速陷阱佈置"},{"b":"通用","n":"大範圍陷阱"},{"b":"特殊","n":"高能陷阱"}],"need":3,"t":["當你以動作佈置守林人陷阱時可以同時佈置 X 個，佈置的距離變為 10 尺。(X 為你的敏捷調整值)"]},{"id":"m398","b":"靈敏","n":"手弩反擊","c":1500,"req":"具有能力[【武力】血之獵人]","refs":[{"b":"武力","n":"血之獵人"}],"need":1,"t":["當一名生物已你為目標發動近戰攻擊時，你可以消耗一個反應，對他發動一次手弩攻擊，此次攻擊檢定-5，如攻擊命中則對你攻擊的生物獲得[無力]狀態，直到他的回合開始。"]},{"id":"m399","b":"靈敏","n":"偷襲Ⅰ","c":1000,"t":["你知道如何利用敵人的分心以做出巧妙的攻擊。","每個回合一次，若你在攻擊檢定中具有 [優勢 Advantage] ，則你可以對一個你用該攻擊命中後對該生物造成額外的 2D6 傷害。該攻擊必須要使用敏捷作為攻擊檢定武器。","若有另一個目標的敵人在距離目標 5 尺內的位置，該敵人未 [無力 Incapacitated ]，且你在該攻擊檢定中未承受 [劣勢 Disadvantage] ，則你在該攻擊檢定中不需要具有 [優勢 Advantage] 也可以發動偷襲效果。"]},{"id":"m400","b":"靈敏","n":"偷襲Ⅱ","c":2000,"req":"具有能力[【靈敏】偷襲Ⅰ]","refs":[{"b":"靈敏","n":"偷襲Ⅰ"}],"need":1,"t":["你偷襲的造成額外的 2D6 傷害，變為 4D6 。"]},{"id":"m401","b":"靈敏","n":"偷襲Ⅲ","c":3000,"req":"具有能力[【靈敏】偷襲Ⅱ]","refs":[{"b":"靈敏","n":"偷襲Ⅱ"}],"need":1,"t":["你偷襲的造成額外的 4D6 傷害，變為 6D6 。"]},{"id":"m402","b":"靈敏","n":"偷襲Ⅵ","c":4000,"req":"具有能力[【靈敏】偷襲Ⅲ]","refs":[{"b":"靈敏","n":"偷襲Ⅲ"}],"need":1,"t":["你偷襲的造成額外的 6D6 傷害，變為 8D6 。"]},{"id":"m403","b":"靈敏","n":"偷襲Ⅴ","c":5000,"req":"具有能力[【靈敏】偷襲Ⅴ]","refs":[{"b":"靈敏","n":"偷襲Ⅵ"}],"need":1,"t":["你偷襲的造成額外的 8D6 傷害，變為 10D6 。"]},{"id":"m404","b":"靈敏","n":"暗影手裏劍","c":1500,"req":"具有能力[【特殊】暗影分身]與[【【武力】武藝]","refs":[{"b":"特殊","n":"暗影分身"},{"b":"武力","n":"武藝"}],"need":2,"t":["以一個 [主要動作]，消耗 1 點[氣]你投出一枚由暗影之力構成手裏劍，手裏劍無視一切向前飛行 30 尺後消失，對路徑上的生物進行一次體質豁免(DC=[氣]的 DC)，若豁免失敗，生物將受到 [武藝骰] 的 [闇蝕傷害]，豁免成功則只受到一半的傷害。","在 [暗影分身] 存在時它將可以和你做出相同的動作，且不消耗 [氣] 。","如在 [微光光照] 、或 [黑暗] 環境中使用此能力進行{#體質豁免}的生物具有 [劣勢 Disadvantage] 。"]},{"id":"m405","b":"靈敏","n":"暗影影斬","c":1500,"req":"具有能力[【特殊】暗影分身]與[【【武力】武藝]","refs":[{"b":"特殊","n":"暗影分身"},{"b":"武力","n":"武藝"}],"need":2,"t":["以一個 [主要動作] ，消耗 2 點 [氣] 你的周圍出現由暗影之力構成利刃，砍向周圍 5 尺範圍的生物，對範圍上的生物進行一次體質豁免( DC = [氣] 的DC)，若豁免失敗，生物將受到 2 倍 [武藝骰] 的 [闇蝕傷害] ，豁免成功則只受到一半的傷害。","在 [暗影分身] 存在時它將可以和你做出相同的動作，且不消耗 [氣] 。","如在 [微光光照] 、或 [黑暗] 環境中使用此能力進行{#體質豁免}的生物具有 [劣勢 Disadvantage]。"]},{"id":"m406","b":"靈敏","n":"暗影交叉","c":2500,"req":"具有能力[【靈敏】暗影手裏劍]與[【靈敏】暗影影斬]","refs":[{"b":"靈敏","n":"暗影手裏劍"},{"b":"靈敏","n":"暗影影斬"}],"need":2,"t":["當你和你的 [暗影分身] 使用消耗 [氣] 的範圍效果時，如有個生物同時處你和你的 [暗影分身] 的範圍效果之內時，他將額外受到 2D8 的傷害。"]},{"id":"m407","b":"靈敏","n":"多重·暗影手裏劍","c":2000,"req":"具有能力[【靈敏】暗影手裏劍]","refs":[{"b":"靈敏","n":"暗影手裏劍"}],"need":1,"t":["當你使用[【靈敏】暗影手裏劍]時，你可以而外消耗[氣]於同樣的路徑上投出更多的手裏劍，每而額外消耗一點[氣]，你投出的手裏劍加一。"]},{"id":"m408","b":"靈敏","n":"擴·暗影影斬","c":2000,"req":"具有能力[【靈敏】暗影影斬]","refs":[{"b":"靈敏","n":"暗影影斬"}],"need":1,"t":["[【靈敏】暗影影斬]的範圍由原來的 5 尺變為 10 尺。"]},{"id":"m409","b":"靈敏","n":"獗·暗影影斬","c":2000,"req":"具有能力[【靈敏】暗影影斬]","refs":[{"b":"靈敏","n":"暗影影斬"}],"need":1,"t":["當一個生物在[【靈敏】暗影影斬]豁免失敗時，其的移動速度減少至原來的 1/2，直到其回合結束。({#詛咒})"]},{"id":"m410","b":"靈敏","n":"風之甲胄","c":2000,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["消耗以一個附贈動作，消耗 2 點[氣]，你的護甲等級(AC)+2，移動速度增加 10 尺，持續 10 分鐘。"]},{"id":"m411","b":"靈敏","n":"黎明之眼","c":1500,"req":"具有能力[【通用】神力引導﹝赦罪之眼﹞]","refs":[{"b":"通用","n":"神力引導﹝赦罪之眼﹞"}],"need":1,"t":["在[【通用】神力引導﹝赦罪之眼﹞]的效果持續時間中你的攻擊檢定無視[半掩護]、[四分之三掩護]的效果。"]},{"id":"m412","b":"靈敏","n":"屠龍足術-龍躍","c":1000,"req":"具有能力[【武力】屠龍之槍]","refs":[{"b":"武力","n":"屠龍之槍"}],"need":1,"t":["長年觀察並模仿巨龍的姿態，你將其威嚴的動作融入槍術步法，化為獨特的戰鬥技巧。這種足術能讓你在戰場上瞬間爆發驚人的移動能力，宛如巨龍振翼般凌空而起。","在你處於地面尚且在非特殊地形上時，你可以以一個附贈動作使用下面其中一種【龍躍】。","【龍躍·前行】","你可以消耗 10 尺的移動力，使其朝任意水平方向移動最多 30 尺的距離。","在移動期將你不會觸發敵對生物的反應動作。【龍躍·高升】","你可以向上跳躍最多 30 尺的，且此跳躍不會觸發敵對生物的反應動作。","此外，直到你的下一個回合前你獲得以下效果:","• 漂浮(Hover)。","• 墜落傷害減少 30 尺。"]},{"id":"m413","b":"靈敏","n":"龍躍．機動","c":1000,"req":"具有能力[【靈敏】屠龍足術-龍躍]","refs":[{"b":"靈敏","n":"屠龍足術-龍躍"}],"need":1,"t":["你研習半空中的身法，將巨龍振翼的姿態化為自身的槍術步伐。即使在無立足點的情況下，你依舊能展現驚人的機動性。","當你處於漂浮 (Hover) 狀態時，你仍可使用【龍躍】的能力。"]},{"id":"m414","b":"靈敏","n":"冰月之牙","c":1500,"req":"具有能力［【特殊】怪獸變身］","refs":[{"b":"特殊","n":"怪獸變身"}],"need":1,"t":["當你以【荒野形態】化身時，寒月的力量注入你的血脈，利齒與利爪閃耀著冰霜之光。每一次攻擊都帶著月光般的寒意，能凍結敵人的血肉與意志。","當你使用 [【通用】荒野形態] 能力變身時你的天生武器攻擊，且額外獲得 1D6 的 [冰冷傷害] 。如果天生武器的傷害原本就具有 [冰冷傷害] 則額外獲得 [冰冷傷害] 變為 2D6 。"]},{"id":"m415","b":"靈敏","n":"哨兵靈光","c":2000,"req":"具有能力 [【特殊】神力引導﹝守望意識﹞]","refs":[{"b":"特殊","n":"神力引導﹝守望意識﹞"}],"need":1,"t":["若你未失去意識，你散發出一道令人保持警覺的靈光。","當你和你 10 尺內由你選擇的生物 (數量至多等同於你的魅力調整值) 進行一次 [先攻] 檢定時，獲得等同於你的魅力調整值的加值。 ( [哨兵靈光] 的效果不會疊加)"]},{"id":"m416","b":"靈敏","n":"刺客絕技·屠城","c":2000,"req":"具有能力[ 【靈敏】刺客]","refs":[{"b":"靈敏","n":"刺客"}],"need":1,"t":["你以冷酷而致命的姿態橫掃戰場，每一次斬殺都化為下一次攻擊的契機。","當你使用攻擊方式使一個生物的[生命值 Hit Point ] 歸 0 時，你可以立即再進行一次攻擊。"]},{"id":"m417","b":"靈敏","n":"刺客絕技·巡靈","c":2000,"req":"具有能力[【靈敏】刺客]","refs":[{"b":"靈敏","n":"刺客"}],"need":1,"t":["在幽暗的環境中，你的身影如同靈魂般無聲無息。","在非 [明亮] 光照環境中，你的任何 [移動 Move] 行為不會解除你的 [隱匿] 狀態。"]},{"id":"m418","b":"靈敏","n":"刺客絕技·閃影","c":2000,"req":"具有能力 [【靈敏】刺客]","refs":[{"b":"靈敏","n":"刺客"}],"need":1,"t":["化作殘影般迅疾無比，你的身影在黑暗與戰場之間閃爍不定。","在此回合你的 [移動 Move] [速度 Speed] 為原來的三倍，並且在此回合你的移動不會觸發 [反應 Reactions] 。","此能力只能使用一次直到下次的{#長修}或{#短休}結束。"]},{"id":"m419","b":"靈敏","n":"刺客絕技‧絕命","c":2000,"req":"具有能力 [【靈敏】刺客]","refs":[{"b":"靈敏","n":"刺客"}],"need":1,"t":["你出手如鬼魅般精準，命中要害的機率大幅提升。","當你使用敏捷的近戰武器攻擊檢定具有 [優勢 Advantage] 時你的[重擊 Critical Hit] 閥值 -1。"]},{"id":"m420","b":"靈敏","n":"槍術風格-冷槍高手","c":2000,"req":"具有能力能力 [【特殊】槍匠 ]","refs":[{"b":"特殊","n":"槍匠"}],"need":1,"t":["你擅長在敵人疏忽之際給予致命一擊。當敵人試圖脫離你的射程時，你冷靜地舉起暴雷加農砲，精準地捕捉其破綻。","當有生物離開你周圍 5 尺時，你可以對其進行一次使用 [暴雷加農砲 Discharge Canno] 的 [藉機攻擊 Opportunity Attack] 。此次攻擊的傷害額外獲得 +10 加值。"]},{"id":"m421","b":"靈敏","n":"死亡使徒","c":1500,"t":["你化身為死亡的使徒，追隨血腥的氣息而行。當敵人陷入瀕死之際，你便如同死神般瞬間逼近，給予最後的致命一擊。","當你周圍 30 尺有生物進入 [浴血 Bloodied] 狀態時，你可以以一個 [反應 Reactions] 瞬間移動到其周圍 5 尺發動一次 [近戰攻擊 Attack] ，此次攻擊具有 [優勢 Advantage] 。"]},{"id":"m422","b":"靈敏","n":"死亡到計時","c":1500,"req":"具有能力 [【靈敏】死亡使徒]","refs":[{"b":"靈敏","n":"死亡使徒"}],"need":1,"t":["你化身為死亡的計時者，將浴血之敵的生命推向終焉。每一次斬擊都如同死亡的倒數，讓敵人逐步流血殆盡。若你在他人回合出手，死亡的時鐘便加速敲響，令敵人無法逃脫命運的侵蝕。","你近戰攻擊命中一名 [浴血 Bloodied] 的目標時，可使其通過一次 DC= 8 + 你熟練加值 + 你的敏捷調整值的{#體質豁免}若失敗，賦予其 1d4 層 [流血 Bleeding] 。","若你在若你在非自身回合發動近戰攻擊(例如透過 [反應 Reactions] )則目標直接獲得 1d4 層 [流血 Bleeding] 。"]},{"id":"m423","b":"靈敏","n":"流水之鞭","c":1000,"req":"具有能力 [【特殊】四象之勢]","refs":[{"b":"特殊","n":"四象之勢"}],"need":1,"t":["你將水之勢凝聚成鞭，抽擊如同奔流，既能造成傷害，也能將敵人強行拉近。流水之鞭象徵水的柔韌與牽制，讓你在戰場上掌握敵人的位置。","當你處於四象之勢-水的狀態時，作為攻擊動作的一部份，你可以消耗 2 點氣發動一次特殊的攻擊流水之鞭。","流水之鞭你以水流化為鞭，猛然抽擊前方的敵人。","對一個距離你周圍 30 + 四象之勢-水給予的攻擊距離尺的生物發動一次 [近戰攻擊] 。若攻擊命中，該生物將受額外 [鈍擊傷害 Bludgeoning] ，且你可以將它擊倒 [伏地 Prone] 或將它向你拉近最多 25 + 四象之勢水給予的攻擊距離尺距離。"]},{"id":"m424","b":"靈敏","n":"風靈突進","c":1000,"req":"具有能力 [【特殊】四象之勢]","refs":[{"b":"特殊","n":"四象之勢"}],"need":1,"t":["你化作疾風，突進至敵人面前，攻擊如同風靈的迅猛衝擊。這股力量不僅讓你避開反擊，更能以強烈的力場之力粉碎敵人的防禦。","當你處於四象之勢-風的狀態時，作為攻擊動作的一部份，你可以消耗 2 點氣發動一次特殊的攻擊風靈突進。","風靈突進你向前移動最多 10 尺(不會觸發 [反應 Reactions] )並發動一次[近戰攻擊]，此次攻擊命中額外增加四象之勢-風增加的命中，攻擊傷害增加 2d10 [力場傷害 Force] 。"]},{"id":"m425","b":"靈敏","n":"蒼龍之拳","c":2000,"req":"具有能力 [【靈敏】流水之鞭]","refs":[{"b":"靈敏","n":"流水之鞭"}],"need":1,"t":["你引動水之勢，拳勁化為蒼龍，奔流之力如同巨浪般轟擊敵人。蒼龍之拳不僅能造成強烈傷害，更能以水流的衝擊力擊退並擊倒敵人，展現水的靈動與壓制。","一回合一次，當你處於四象之勢-水的狀態時，作為攻擊動作的一部份，你可以消耗 4 點氣發動一次特殊的攻擊蒼龍之拳。","蒼龍之拳你以水流化為蒼龍，轟擊的敵人。","對一個距離你周圍 30+ 四象之勢-水給予的攻擊距離尺的生物發動一次 [近戰攻擊] 。若攻擊命中，該生物將受額外 6d10 [鈍擊傷害 Bludgeoning] ，且你可以將它擊倒 [伏地 Prone] 。"]},{"id":"m426","b":"靈敏","n":"凌風舞影","c":2000,"req":"具有能力 [【靈敏】風靈突進]","refs":[{"b":"靈敏","n":"風靈突進"}],"need":1,"t":["你化身為疾風，身影在戰場上舞動如幻。凌風舞影象徵風之勢的極致靈動，身形如舞、殘影如幻，敵人只見風影交錯，卻難以捕捉你的真身。","一回合一次，當你處於四象之勢-風的狀態時，作為攻擊動作的一部份，你可以消耗 4 點氣發動一次特殊的攻擊凌風舞影。","凌風舞影你化身為疾風，身影在戰場上舞動如幻。","選擇自身周圍 60 尺內，最多三個你所能看見的生物。對每個目標各進行一次 [近戰攻擊] ，這些攻擊命中額外增加四象之勢-風增加的命中。若命中，目標將受額外 4d10 [力場傷害 Force] 。","你可以接著傳送到一處距離其中一個目標 5 尺內（無論命中與否），你所能看見的未被佔據空間。"]},{"id":"m427","b":"靈敏","n":"凌風舞影·殘","c":1500,"req":"具有能力[【靈敏】凌風舞影 ]","refs":[{"b":"靈敏","n":"凌風舞影"}],"need":1,"t":["你在戰場上舞動如風，殘影隨之散落，幻化出無數身影。敵人眼前只見風影交錯，難以捕捉真身。讓你在戰鬥中宛如風神降世，身影如舞、幻影如幻。","當你使用凌風舞影時，每命中的生物留下一個在你周圍留下一個殘影，直到戰鬥結束。殘影會跟著你移動、模仿你的動作、並變換位置，因此不可能追蹤判斷哪一個殘影才是真身。你可以使用你的 [附贈動作 Bonus Action] 解消這些殘影。","你最多可以擁有3個殘影。","在殘影存在期間，每當有一個生物以你為攻擊的目標，骰一顆以決定該攻擊是否以你的其中一個殘影為目標。在殘影存在期間，每當有一個生物以你為攻擊的目標，骰一顆 d20 以決定該攻擊是否以你的其中一個殘影為目標。","若你有 3 個殘影，你必須骰出 6 或以上才能使該攻擊改為以殘影為目標。當有2個殘影，你必須骰出 8 或以上。當有1個殘影，則你必須骰出 11 以上。","殘影的 AC 等同於 10+你的敏捷調整值。若攻擊命中一個殘影，則該殘影被摧毀。一個殘影只會被一次命中它的攻擊摧毀，而無視所有其他傷害和效果。若一個生物無法視物，或依賴視覺以外的感知，像是 [盲視 Blindsight] 或它可以察覺幻影的真偽，例如透過[真實視覺 Truesight] ，則該生物將不會被殘影迷惑。"]},{"id":"m428","b":"靈敏","n":"劍神流","c":1500,"t":["劍神流象徵著以單劍為信念的極致武技。捨棄厚重的防具與盾牌，你將所有的專注與技巧凝聚於手中的武器之上。這種純粹的劍術流派強調速度、精準與決斷，讓你在戰場上以一劍定生死。","當你無裝備{#重甲}、{#中甲}、{#長劍}、{#短劍}、{#盾牌}且只有武器裝備只有一個{#長劍}、{#短劍}、{#刺劍}、{#彎刀}類武器時，你的近戰武器攻擊命中具有額外的敏捷整值一半(向上取整) 的加值。"]},{"id":"m429","b":"靈敏","n":"劍神流-心眼","c":1500,"req":"具有能力 [【武力】劍神流]","refs":[{"b":"武力","n":"劍神流"}],"need":1,"t":["你能看穿敵人防禦的破綻，將每一次揮劍都化為致命的威脅。這種心眼的境界讓你在戰場上更容易打出致命一擊，展現出「以一劍定生死」的真諦。","當你無裝備{#重甲}、{#中甲}、{#長劍}、{#短劍}、{#盾牌}且只有武器裝備只有一個{#長劍}、{#短劍}、{#刺劍}、{#彎刀}類武器時，你的近戰武器攻擊[重擊 Critical Hit] 閥值 -1 。"]},{"id":"m430","b":"靈敏","n":"劍神流-心眼[疾意]","c":1500,"req":"具有能力 [【武力】劍神流-心眼]","refs":[{"b":"武力","n":"劍神流-心眼"}],"need":1,"t":["你能在瞬間洞察敵人的破綻，將「第一劍」化為最致命的威脅。這種境界讓你在戰場的開局就能展現壓倒性的殺傷力，彷彿「先手即決斷」。","當你無裝備{#重甲}、{#中甲}、{#長劍}、{#短劍}、{#盾牌}且只有武器裝備只有一個{#長劍}、{#短劍}、{#刺劍}、{#彎刀}類武器時，戰鬥開始後的第一個你每回合的第一次的近戰武器攻擊[重擊 Critical Hit] 閥值 -2 。"]},{"id":"m431","b":"靈敏","n":"劍神流-無音太刀","c":2000,"req":"具有能力 [【武力】劍神流]","refs":[{"b":"武力","n":"劍神流"}],"need":1,"t":["在極致境界下的無聲出手。你的第一劍快如閃電、靜如無聲，讓敵人根本無法捕捉或反應。這種境界讓你在戰場上以「先手必殺」的姿態壓制對手，展現出劍術的高級奧義之一。","當你無裝備{#重甲}、{#中甲}、{#盾牌}且只有武器裝備只有一個{#長劍}、{#短劍}、{#刺劍}、{#彎刀}類武器時，每回合的第一次的近戰武器攻擊無法被 [反應 Reactions] 。"]},{"id":"m432","b":"靈敏","n":"劍神流-光之太刀","c":2500,"req":"具有能力 [【武力】劍神流-無音太刀]","refs":[{"b":"武力","n":"劍神流-無音太刀"}],"need":1,"t":["光之太刀象徵劍神流劍士在瞬間爆發出的極致光輝。這一劍快如光影，精準無比，能在最短的時間內洞察並斬擊敵人要害。它不僅是技巧的展現，更是劍士信念的化身－以光之速決斷生死。","一個[主要動作 Actions] 一次，當你無裝備{#重甲}、{#中甲}、{#盾牌}且只有武器裝備只有一個{#長劍}、{#短劍}、{#刺劍}、{#彎刀}類武器時，作為近戰武器攻擊的一部分你可以施放一次特殊的攻擊光之太刀。","光之太刀對一個生物進行一次近戰武器攻擊，此次攻擊命中與攻擊傷害具有 [優勢 Advantage] 且額外獲得 +5 的加值，並且[重擊 Critical Hit] 閥值 -3。","你能使用光之太刀的次數為你的敏捷整值一半(向上取整) ，直到你完成一次{#短休}你回復所有使用次數。"]},{"id":"m433","b":"魔法","n":"法術書","c":1500,"t":["你最多可以習得最多 3 個自選的[戲法]與最多 3 個自選的[一環法術]。","你的 [法術容量] 增加 5 個。"]},{"id":"m434","b":"魔法","n":"法術容量增加","c":1500,"rep":1,"t":["你的 [法術容量] 增加 5 個。"]},{"id":"m435","b":"魔法","n":"魔力增加","c":1000,"rep":1,"t":["你的 [魔力] 上限 +2 。"]},{"id":"m436","b":"魔法","n":"顯現回音","c":2000,"t":["你能使用一個附贈動作與 1 [魔力] 來在你可見的 15 尺內，一處尚未被占據的空間處，魔法地顯現一個你自身的回音。該回音是魔法、半透通的，形如你的黑白形象，回音持續直到被摧毀或你用一個附贈動作摧毀、顯現另一個回音，或你處於無力狀態。","你的回音的 [護甲等級] 為 14 + 你的熟練加值，生命值為 1，並免疫所有 [狀態] 。回音需要進行豁免時，使用你的相應豁免的調整值。它的體型和你一樣，並且會占據空間。在你的回合時，你能精神性地指令回音朝任意方向移動至多 30 尺（無需動作）。如果你的回音在你的回合結束時遠離你超過 30 尺，那麼它會被摧毀。","你能按照以下方法使用回音：","• 使用一個[附贈動作]，你能消耗 15 尺的速度進行傳輸，魔法性地與你的回音交換位置，無論回音與你之間的距離如何或你否看不看的到它。","• 當你在你的回合裡進行攻擊或法術動作時，你用該動作進行的任何攻擊或法術可以用你或回音的空間作為源點。每一次攻擊的源點都由你決定。","• 當一個位於你的回音 5 尺內且你可見的生物嘗試遠離回音至少 5 尺時，你能用你的反應動作來對該生物進行一次藉機攻擊，就如同你位於回音的空間上一樣。"]},{"id":"m437","b":"魔法","n":"回音反饋","c":1500,"req":"具有能力[【魔法】顯現回音]","refs":[{"b":"魔法","n":"顯現回音"}],"need":1,"t":["你能增強你回音的能力。","無論何時你進行攻擊或法術動作，你能在一個回音的位置上進行一次相同的攻擊或法術動作。(法術的[魔力]消耗由你自身扣除。)(如法術需要﹝專注﹞或﹝代價﹞則由你自身支付。)","你能使用本能力的次數等於你的體質調整值（最少 1 次）。當你完成一次長休后，你回復所有已消耗的使用次數。"]},{"id":"m438","b":"魔法","n":"回音殉道者","c":1000,"req":"具有能力[【魔法】顯現回音]","refs":[{"b":"魔法","n":"顯現回音"}],"need":1,"t":["在一個除你以外的，且你可見的生物受到攻擊前，你能用你的反應來讓你的回音與該生物的位址互換。此次攻擊將由你的回音代為承受。","一旦你使用此能力，直到你完成一次短休或長休前，你無法再次使用。"]},{"id":"m439","b":"魔法","n":"回音殘響","c":1000,"req":"具有能力[【魔法】回音殉道者]","refs":[{"b":"魔法","n":"回音殉道者"}],"need":1,"t":["當你使用回音殉道者時如回音因為此次攻擊被摧毀則會對摧毀其的單位造成 3D8 的雷鳴傷害。","當你主動用一個附贈動作消解回音時會對其周圍 5 尺的生物造成 1D8 的雷鳴傷害。"]},{"id":"m440","b":"魔法","n":"回收潛能","c":1000,"req":"具有能力[【魔法】顯現回音","refs":[{"b":"魔法","n":"顯現回音"}],"need":1,"t":["你已經學會吸收你回音上轉瞬即逝的魔力。當你的一個回音被摧毀時，而你也沒有臨時生命值時，你能夠獲得等量於[2d6 + 你的體質調整值]的臨時生命值。","你能使用這個能力的次數等於你的體質調整值（最少 1 次）。當你完成一次長休后，你回復所有已消耗的使用次數。"]},{"id":"m441","b":"魔法","n":"一人之隊","c":1500,"req":"具有能力[【魔法】回音殉道者]、[【魔法】回音反饋]、[【魔法】回收潛能]其中的 2 個","refs":[{"b":"魔法","n":"回音殉道者"},{"b":"魔法","n":"回音反饋"},{"b":"魔法","n":"回收潛能"}],"need":3,"t":["當你用一個附贈動作使用顯現回音時，你能同時顯現 2 個回音，並且這些回音能夠共存。如果你嘗試顯現第 3 個回音，那麼前面其中 1 個回音就會被摧毀。你能夠在其中 1 個回音的位置上進行的所有事情都能用另 1 個回音進行交替。(每顯現 1 個回音需要消耗 1[魔力])"]},{"id":"m442","b":"魔法","n":"一人之團","c":2000,"req":"具有能力[【魔法】一人之隊]","refs":[{"b":"魔法","n":"一人之隊"}],"need":1,"t":["當你用一個附贈動作使用顯現回音時，你能顯現 3 個回音，並且這些回音能夠共存。如果你嘗試顯現第 4 個回音，那麼前面其中 1 個回音就會被摧毀。你能夠在其中 1 個回音的位置上進行的所有事情都能用另 1 個回音進行交替。(每顯現 1 個回音需要消耗 1[魔力])"]},{"id":"m443","b":"魔法","n":"一人之軍","c":2500,"req":"具有能力[【魔法】一人之團]","refs":[{"b":"魔法","n":"一人之團"}],"need":1,"t":["你用一個附贈動作使用顯現回音時，你能顯現 4 個回音，並且這些回音能夠共存。如果你嘗試顯現第 5 個回音，那麼前面其中 1 個回音就會被摧毀。你能夠在其中 1 個回音的位置上進行的所有事情都能用另 1 個回音進行交替。(每顯現 1 個回音需要消耗 1[魔力])"]},{"id":"m444","b":"魔法","n":"絕響","c":3000,"req":"具有能力[【魔法】一人之隊]、[【魔法】一人之團]、[【魔法】一人之軍]中的一個及[【魔法】回音反饋]","refs":[{"b":"魔法","n":"一人之隊"},{"b":"魔法","n":"一人之團"},{"b":"魔法","n":"一人之軍"},{"b":"魔法","n":"回音反饋"}],"need":4,"t":["你能增強你回音的能力並達成一體。無論何時你進行攻擊或法術動作，你能在所有的回音的位置上進行一次相同的攻擊或法術動作，之後所有的回音消解。(法術的[魔力]消耗由你自身扣除。)(如法術需要﹝專注﹞或 ﹝代價﹞則由你自身支付。)","你必須完成長休後才能再使用此能力。"]},{"id":"m445","b":"魔法","n":"戰爭魔法","c":1000,"t":["當你使用你的主要動作以施放一個法術時，你能夠以一個附贈動作進行一次武器攻擊。"]},{"id":"m446","b":"魔法","n":"符文雕刻者","c":2000,"t":["你可以使用魔法符文來增強你的裝備。你可以從下列的被說明的符文當中，選取並學會兩個符文。","每當你完成了一次長休，你可以接觸數量等於你已知符文數物品，並在每個物品上銘刻不同的符文。符合條件的物品必須為一把武器、一套盔甲、一面盾牌、一個裝飾品或者任何其他你可以穿着或手持的物品。你的符文會保留在物品上直到你完成一次長休，且一件物品同時只能承載你的一個符文。","符文占用裝備 2 個[副詞綴]的位置。稀有度為特殊。","符文:","• 雲之符文.","該符文模擬了一些雲巨人使用的魔法詐術。","當你穿着或持有一個銘刻此符文的物品時，你在敏捷（巧手）和魅力（欺瞞）檢定上具有優勢。","此外，當你或一個你 30 尺內可視生物被一次攻擊檢定擊中，你可以用你的反應啟動此符文並選取 30 尺內除攻擊者外另一生物。此攻擊檢定的目標改為該生物，且使用同一骰值。此魔法帶來的攻擊效果無視其距離。一旦你啟動此符文，你無法再次使用直到你完成一次短休或長休。","• 火之符文.","該符文中的魔力啟動了偉大鐵匠的高超技藝。","當你穿着或持有一個銘刻此符文的物品，你在使用具有熟練項的工具進行屬性檢定時，你的熟練加值翻倍。","此外，當你使用武器攻擊並命中一個生物，你可以啟動此符文來召喚熾熱鐐銬：目標受到其餘 2d6 火焰傷害，且其必須通過一次力量豁免檢定，如果失敗則被束縛 1 分鐘。當目標被熾熱鐐銬束縛時，目標在它每回合開始時受到 2d6 火焰傷害。目標可以在每個自己回合結束時重複此豁免檢定，成功則放逐鐐銬。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","• 霜之符文.","該符文的魔力喚起了諸如霜巨人般在冬日荒野中生存下來的力量。","當你穿着或持有一個銘刻此符文的物品，你在感知（馴獸）檢定和魅力（威嚇）檢定上獲得優勢。","此外，你可以用一個附贈動作啟動該符文來提高你的體能。十分鐘內，你所有與力量或體質有關的屬性和豁免檢定獲得+2 的加值。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","• 山丘符文.","該符文的魔力賦予如山丘巨人一般的堅韌。","當你穿着或持有一個銘刻此符文的物品，你在對抗中毒狀態的豁免檢定上具有優勢，且你對於毒素傷害具有抗性。","此外，你可以用一個附贈動作啟動該符文，並獲得 1 分鐘的鈍擊、揮砍和穿刺傷害抗性。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","• 石之符文.","該符文的魔力可以啟動和石巨人相關的智慧。","當你穿着或持有一個銘刻此符文的物品，你在感知（洞悉）的檢定上獲得優勢，且你獲得 120 尺的黑暗視覺。","此外，當一個你 30 尺內可見生物結束它的回合時，你可以使用一個反應動作來啟動該符文，並強迫該生物進行一次感知豁免。若失敗，則該生物被你魅惑 1 分鐘。如果以該形式被魅惑，該生物移動速度降為 0 且無力，陷入夢幻般的麻木狀態。目標可以在每個自己回合結束時重複此豁免，成功則解除該狀態。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","• 風暴符文.","通過使用該符文，你可以像一位風暴巨人預言者一樣瞥見未來。","當你穿着或持有一個銘刻此符文的物品，你在智力（奧秘）檢定上獲得優勢，且只要你未無力，你不會被突襲。","此外，你可以用一個附贈動作啟動該符文來進入先知形態，持續 1 分鐘或直到你無力。在該形態結束之前，當你或另一個你 60 尺內可見的生物進行一次攻擊檢定、一次豁免檢定或一次屬性檢定時，你可以用反應使這次檢定獲得優勢或劣勢。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","(如果一個符文需要通過豁免檢定，你的符文魔法的豁免 DC 等於 8 + 你的熟練加值 + 你的體質調整值。)"]},{"id":"m447","b":"魔法","n":"符文擴充","c":1500,"req":"具有能力[【魔法】符文雕刻者]","refs":[{"b":"魔法","n":"符文雕刻者"}],"need":1,"rep":1,"t":["你可以從下列的符文當中，選取並學會一個符文。","符文:","• 雲之符文.","該符文模擬了一些雲巨人使用的魔法詐術。當你穿着或持有一個銘刻此符文的物品時，你在敏捷（巧手）和魅力（欺瞞）檢定上具有優勢。","此外，當你或一個你 30 尺內可視生物被一次攻擊檢定擊中，你可以用你的反應啟動此符文並選取 30 尺內除攻擊者外另一生物。此攻擊檢定的目標改為該生物，且使用同一骰值。此魔法帶來的攻擊效果無視其距離。一旦你啟動此符文，你無法再次使用直到你完成一次短休或長休。","• 火之符文.","該符文中的魔力啟動了偉大鐵匠的高超技藝。當你穿着或持有一個銘刻此符文的物品，你在使用具有熟練項的工具進行屬性檢定時，你的熟練加值翻倍。","此外，當你使用武器攻擊並命中一個生物，你可以啟動此符文來召喚熾熱鐐銬：目標受到其餘 2d6 火焰傷害，且其必須通過一次力量豁免檢定，如果失敗則被束縛 1 分鐘。當目標被熾熱鐐銬束縛時，目標在它每回合開始時受到 2d6 火焰傷害。目標可以在每個自己回合結束時重複此豁免檢定，成功則放逐鐐銬。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","• 霜之符文.","該符文的魔力喚起了諸如霜巨人般在冬日荒野中生存下來的力量。當你穿着或持有一個銘刻此符文的物品，你在感知（馴獸）檢定和魅力（威嚇）檢定上獲得優勢。","此外，你可以用一個附贈動作啟動該符文來提高你的體能。十分鐘內，你所有與力量或體質有關的屬性和豁免檢定獲得+2 的加值。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","• 山丘符文.","該符文的魔力賦予如山丘巨人一般的堅韌。當你穿着或持有一個銘刻此符文的物品，你在對抗中毒狀態的豁免檢定上具有優勢，且你對於毒素傷害具有抗性。","此外，你可以用一個附贈動作啟動該符文，並獲得 1 分鐘的鈍擊、揮砍和穿刺傷害抗性。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","• 石之符文.","該符文的魔力可以啟動和石巨人相關的智慧。當你穿着或持有一個銘刻此符文的物品，你在感知（洞悉）的檢定上獲得優勢，且你獲得 120 尺的黑暗視覺。","此外，當一個你 30 尺內可見生物結束它的回合時，你可以使用一個反應動作來啟動該符文，並強迫該生物進行一次感知豁免。若失敗，則該生物被你魅惑 1 分鐘。如果以該形式被魅惑，該生物移動速度降為 0 且無力，陷入夢幻般的麻木狀態。目標可以在每個自己回合結束時重複此豁免，成功則解除該狀態。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","• 風暴符文.","通過使用該符文，你可以像一位風暴巨人預言者一樣瞥見未來。當你穿着或持有一個銘刻此符文的物品，你在智力（奧秘）檢定上獲得優勢，且只要你未無力，你不會被突襲。","此外，你可以用一個附贈動作啟動該符文來進入先知形態，持續 1 分鐘或直到你無力。在該形態結束之前，當你或另一個你 60 尺內可見的生物進行一次攻擊檢定、一次豁免檢定或一次屬性檢定時，你可以用反應使這次檢定獲得優勢或劣勢。每當你啟動該符文，你無法再次使用直到你完成一次短休或長休。","(如果一個符文需要通過豁免檢定，你的符文魔法的豁免 DC 等於 8 + 你的熟練加值 + 你的體質調整值。)"]},{"id":"m448","b":"魔法","n":"符文之護","c":1000,"req":"具有能力[【魔法】符文雕刻者]","refs":[{"b":"魔法","n":"符文雕刻者"}],"need":1,"t":["你學會了啟動你的符文魔法來保護你的盟友。","當一個 60 尺內且對你可見的生物被一次攻擊檢定命中時，你可以使用一個反應動作來強迫攻擊者重新擲 D20 並採用新的攻擊檢定結果。","該能力的可使用次數等於你的已知符文數目。直到下次長休結束，你回復所有的使用次數。"]},{"id":"m449","b":"魔法","n":"符文大師","c":2000,"req":"具有能力[【魔法】符文雕刻者]且[已知符文數目大於等於 4]","refs":[{"b":"魔法","n":"符文雕刻者"}],"need":1,"t":["你可以對每個你在符文雕刻者特徴中已知的符文啟動兩次，而不是一次，且你可以在完成一次短休或長休之后回復所有已使用的次數。"]},{"id":"m450","b":"魔法","n":"符文主宰","c":3000,"req":"具有能力[【魔法】符文大師]且[已知符文數目大於等於 6]","refs":[{"b":"魔法","n":"符文大師"}],"need":1,"t":["你可以對每個你在符文雕刻者特徴中已知的符文啟動三次，而不是兩次，且你可以在完成一次短休或長休之后回復所有已使用的次數。"]},{"id":"m451","b":"魔法","n":"妖精漫游者","c":1500,"t":["你能夠使用來自妖精荒原中黑暗空洞的攝心魔法以強化你的武器攻擊。","當你使用武器命中一個生物時，你可以對目標造成額外的 1d6 心靈傷害，一個目標一回合只能夠受到一次這個傷害。"]},{"id":"m452","b":"魔法","n":"精誠所予","c":1000,"req":"具有能力[【魔法】妖精漫游者]","refs":[{"b":"魔法","n":"妖精漫游者"}],"need":1,"t":["妖精荒原的皇庭賜予你獲得精類援助的祝福：你習得『精類召喚術(Summon Fey)』(這不會使用你的法術容量)，且你可以施展它而無需材料成分。你可以不消耗[魔力]而施展這個法術一次，並在你完成一次長休后重獲該能力。","當你開始施展這個法術時，你可以對其進行調整使其無需專注。若你這麼做，那麼法術的持續時間會在那一次施展時變為一分鐘。"]},{"id":"m453","b":"魔法","n":"詭術師","c":1500,"req":"具有能力[【靈敏】靈巧動作]","refs":[{"b":"靈敏","n":"靈巧動作"}],"need":1,"t":["你習得『法師之手』和另外二個自選的戲法。","當你施放『法師之手』時，你可以讓這只幽靈般的手掌隱形，且你可以用它來進行下列的其餘行動：","• 你可以將一個這只手所持握的物體擺入一個被其他生物所穿戴或攜帶的容器內。","• 你可以取走一個被裝在其他生物所穿戴或攜帶的容器內的物體。","• 你可以使用密探工具組或開鎖工具以在射程內開鎖或解除陷阱。","若你成功通過一次對抗某個生物感知（察覺）檢定的敏捷（巧手）檢定，則你可以進行上述其中一個行動而不會被該生物察覺。","此外，所有靈巧動作能力所賦予的附贈動作效果皆適是用於這支手。"]},{"id":"m454","b":"魔法","n":"魔法伏擊","c":1000,"req":"具有能力[【魔法】詭術師]","refs":[{"b":"魔法","n":"詭術師"}],"need":1,"t":["於躲藏狀態的情況下對一個生物施放一個法術時，則該生物在該回合為對抗該法術所進行的任何豁免檢定都將具有劣勢。"]},{"id":"m455","b":"魔法","n":"萬能詭術","c":1000,"req":"具有能力[【魔法】詭術師]","refs":[{"b":"魔法","n":"詭術師"}],"need":1,"t":["你獲得用你的法師之手以干擾目標的能力。","在你的回合以一個附贈動作，你可以指定一個與法師之手法術創造出的幽靈手掌周圍 5 尺內的生物。這麼做會讓你在該回合結束前，有一次機會對該生物所進行的攻擊檢定中獲得優勢。"]},{"id":"m456","b":"魔法","n":"法術盜賊","c":2500,"req":"具有能力[【魔法】魔法伏擊]、[【魔法】萬能詭術]中的一個","refs":[{"b":"魔法","n":"魔法伏擊"},{"b":"魔法","n":"萬能詭術"}],"need":2,"t":["你獲得以魔法從其他施法者手中偷走施展法術知識的能力。","緊接在一個生物施放以你為目標、或將你納入範圍效果的法術之后，你可以使用你的反應以強迫該生物進行一次使用它法術屬性調整值的豁免檢定。這個豁免檢定的 DC 為 8 + 你的熟練加值 + 你的智力調整值。若它豁免失敗，你將無效該{#法術}的效果與傷害。在接下來的 8 小時內，你知曉該{#法術}，但該{#法術}不會使用你的 [法術容量]，且可以使用你的[魔力]施放該法術(不需要耗材)。","你可以使用此能力的次數等同於你的智力調整值（最少 1 次）。你在完成一次{#長休}后回復所有你消耗掉的次數。"]},{"id":"m457","b":"魔法","n":"先祖追道","c":1500,"req":"具有能力[【特殊】先祖靈衛]","refs":[{"b":"特殊","n":"先祖靈衛"}],"need":1,"t":["你習得『卜筮(Augury)』和『銳眼術(Clairvoyance)』，這不會使用你的法術容量，且你可以施展它們而無需材料成分。","你可以不消耗[魔力]而施展其中一個法術(『卜筮(Augury)』和『銳眼術(Clairvoyance)』)一次，並在你完成一次長休后重獲該能力。"]},{"id":"m458","b":"魔法","n":"風暴靈光","c":2000,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["你將在處於狂暴時散發出一道風暴般的魔法靈光。這道靈光將從你身上向全方位延伸 10 尺，但並無法穿透全掩護。","你的靈光具有一個會在你進入狂暴時被激發的效果，且你可以在你的每個回合以一個附贈動作再次激發這個效果。從沙漠、海洋、和凍原中選擇一種環境。你的靈光效果將根據你所選的環境而有所不同，詳述如下。每當你啟動靈光時，你都可以變更你所選擇的環境。","若你的風暴靈光效果要求一次豁免檢定，則 DC 等同於 8 + 你的熟練加值 + 你的體質調整值。","• 沙漠.當這個效果被激發時，所有其他處於你風暴靈光中的生物都將各自受到 (2+自身熟練值) 點火焰傷害。","• 海洋.當這個效果被激發時，你可以選擇處於你風暴靈光中一個你所能看見的其他生物。目標必須進行一次敏捷豁免。豁免失敗的目標將受到 (3d6+自身熟練值)的閃電傷害，豁免成功則只受到一半的傷害。","• 凍原.當這個效果被激發時，由於冰冷驚魂將使人適應於苦難，每個處於你風暴靈光中你所選擇的生物將獲得 (5+自身熟練值) 的臨時生命值。"]},{"id":"m459","b":"魔法","n":"風暴長存","c":2500,"req":"具有能力[【特殊】風暴之魂]、[【特殊】狂怒風暴]或[【特殊】風暴同行]其中二個","refs":[{"b":"特殊","n":"風暴之魂"},{"b":"特殊","n":"狂怒風暴"},{"b":"特殊","n":"風暴同行"}],"need":2,"t":["在你的回合一次，你可以不消耗附贈動作發動一次[風暴靈光]的效果。"]},{"id":"m460","b":"魔法","n":"精魂尋訪者","c":1000,"req":"具有能力[【特殊】圖騰精魂]","refs":[{"b":"特殊","n":"圖騰精魂"}],"need":1,"t":["你追求於與大自然調和之道，使你與動物創建了親密的關系。","你習得『野獸知覺(Beast Sense)』和『動物交談術(Speak with Animals)』法術，這不會使用你的法術容量，但只能通過儀式施展。"]},{"id":"m461","b":"魔法","n":"精魂行者","c":1500,"req":"具有能力[【特殊】圖騰精魂]","refs":[{"b":"特殊","n":"圖騰精魂"}],"need":1,"t":["你追求於與大自然調和之道，使你與動物創建了親密的關系。你習得『問道自然(Commune with Nature)』法術，這不會使用你的法術容量，但只能通過儀式施展這兩個法術(『野獸知覺(Beast Sense)』和『動物交談術(Speak with Animals)』)。"]},{"id":"m462","b":"魔法","n":"精魂召喚","c":1500,"req":"具有能力[【特殊】獸之型]、【魔法】精魂尋訪者、【魔法】精魂行者]其中二個","refs":[{"b":"特殊","n":"獸之型"},{"b":"魔法","n":"精魂尋訪者"},{"b":"魔法","n":"精魂行者"}],"need":2,"t":["你習得『召喚動物(Conjure Animals)』法術，這不會使用你的法術容量，且你可以施展它而無需材料成分。你可以不消耗[魔力]而施展這個法術一次(視為三環施展)，且如果你使用此能力使用『召喚動物(Conjure Animals)』法術你對此法術不需要維持專注。並在你完成一次短休或長休后重獲該能力。"]},{"id":"m463","b":"魔法","n":"察覺魔法","c":1000,"t":["以一個動作，你讓你的感官對聚集的魔力的存在保持警覺。知道你的下一個回合結束前，你可以知曉你 60 尺內任何法術或者魔法物品的位置，除非它們對你有全掩蔽。當你察覺到一個法術的存在時，你還能判斷這個法術屬於哪一個學派。","你可以使用該能力的次數等於你的熟練加值。每完成一次長休或短休之后你回復所有已消耗的使用次數。"]},{"id":"m464","b":"魔法","n":"狂野亂潮","c":1500,"req":"具有能力[【武力】狂暴]","refs":[{"b":"武力","n":"狂暴"}],"need":1,"t":["你體內那翻滾不息的魔法能量又是會從你身上爆發出來。當你進入狂暴狀態時，擲骰子並根據以下\"狂野魔法表\"中決定所產生的狂野魔法。","如果這個狂野魔法需要進行豁免檢定，則其 DC 等於 8 + 你的熟練加值 + 你的體質調整值。","\"狂野魔法表\"","d8 魔法效應","1. 陰暗的卷須在你身邊瘋狂揮舞。在你能看到的 30 尺內，你選擇若干生物，這些生物必須進行一次體質","豁免，如果失敗，則將受到 1d12 的闇蝕傷害。你獲得 1d12 的臨時生命值。","2. 你可以傳送到 30 尺內的一個未被占據的，你可以看到的地方。直到你的狂暴終止，你的每一個回合都","可以消耗一個附贈動作再次發動這個效果。","3. 一個無形的靈體，看起來像一個呋嚕或者皮克精（由你決定），出現在一個你 30 尺內可以看到的生物","的 5 尺以內。並且在當前回合結束時，這個靈體會爆炸，所有 5 尺以內的生物必須進行一次敏捷豁免，如果失敗，將承受 1d6 的力場傷害。直到你的狂暴結束前，你每個回合都可以消耗一次附贈動作來再次發動這個效果。","4. 魔力與你所選擇的一把你正持握着的武器相融在一起。直到你的狂暴結束前，這把武器的傷害類型轉變為力場傷害，並且獲得輕型和投擲（20 尺/60 尺）的屬性。如果你手中不在持握有這把武器，它會在當前回合結束的時候重新出現在你的手中。","5. 在你的狂暴結束前，每當一個生物以攻擊檢定的方式對你進行攻擊並命中，你身上的魔力抽打反擊對","其造成 1d6 的力場傷害。","6. 在你的狂暴結束前，你周身圍繞着彩色的防護光芒。你的 AC 獲得+1 加值，並且在你 10 尺內的伙伴","也可以享受到這一加成。","7. 你身邊暫時生長出花朵與藤蔓。在你的狂暴結束前，你周圍 15 尺的地面對你的敵人視作困難地型。","8. 一束光從你胸膛射出。你所選擇的 30 尺內的你可以看到的一個其他生物必須進行一次體質豁免檢定，","如果失敗，將會受到 1d6 的光耀傷害，並且直到你的下一個回合開始前，其將一直目盲。直到你的狂暴結束前，你每個回合都可以消耗一次附贈動作來再次發動這個效果。"]},{"id":"m465","b":"魔法","n":"掌控亂潮","c":1500,"req":"具有能力[【魔法】狂野亂潮]或[【魔法】狂野魔法浪湧]","refs":[{"b":"魔法","n":"狂野亂潮"},{"b":"魔法","n":"狂野魔法浪湧"}],"need":1,"t":["每當你在\"狂野魔法表\"中擲骰決定狂野魔法效果時，你可以擲兩次骰子並且選擇其中之一作為所釋放的狂野魔法效果。如果你擲出的兩個骰子數值相同，那麼你可以無視這個數字，任意選擇一個\"狂野魔法表\"里的效果。"]},{"id":"m466","b":"魔法","n":"凝神境","c":1500,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["你可以進入一種特別的冥想以使你周遭環繞着一道和平靈光。","在一次長休結束時，你將獲得聖域術(Sanctuary)法術的效果，持續直到你的下一次長休開始（此法術可以和原本一樣被提早結束）。","此法術的豁免檢定 DC 等同於 8 + 你的感知調整值 + 你的熟練加值。","聖域術的效果如下：你守護射程內一個生物不受攻擊。直到法術結束前，以被守護生物為目標進行攻擊或施放危害法術的任何生物都必須先進行一次感知豁免。若豁免失敗，該生物必須選擇另一個目標，否則該次攻擊或法術失敗。此法術並不會從範圍效果中保護被守護的生物，像是火球術。","若被守護的生物進行一次攻擊、施放一個會影響敵人的法術、或對另一個生物造成傷害，則此法術結束。"]},{"id":"m467","b":"魔法","n":"影之技藝","c":1500,"req":"具有能力[【特殊】氣]","refs":[{"b":"特殊","n":"氣"}],"need":1,"t":["你可以使用你的氣以拷貝特定法術的效果。","以一個動作，你可以消耗 2 點氣以施放『黑暗術』、『黑暗視覺』、『行蹤無跡』或『沉默術』，且無須提供材料搆材。","此外，若你尚未知曉『次級幻象』戲法，則你將習得它。(這不會使用你的法術容量)"]},{"id":"m468","b":"魔法","n":"日光箭","c":1000,"req":"具有能力[【特殊】氣]和[【武力】武藝]","refs":[{"b":"特殊","n":"氣"},{"b":"武力","n":"武藝"}],"need":2,"t":["你可以投擲出灼熱的魔法光輝箭矢。","你獲得可以在採取攻擊動作時使用的新的攻擊選項。這種特殊攻擊是一個射程為 30 尺的遠程魔法攻擊。你熟練於此攻擊，且你將你的敏捷調整值加入它的攻擊檢定和傷害骰。它的傷害類型為光耀傷害，且它的傷害骰為一顆 d4。這顆骰子等同於武藝的傷害。","當你在你的回合採取攻擊動作並使用此特殊攻擊作為攻擊動作的一部份，你可以消耗 1 點氣以使用一個附贈動作進行二次此特殊攻擊。","當你獲得額外攻擊能力，此特殊攻擊可以被用於任何你作為攻擊動作一部份所進行的攻擊中。"]},{"id":"m469","b":"魔法","n":"熱弧息","c":1000,"req":"具有能力[【魔法】日光箭]","refs":[{"b":"魔法","n":"日光箭"}],"need":1,"t":["你獲得將你的氣引導轉換成灼熱能量波的能力。","緊接在你在你的回合採取攻擊動作之后，你可以消耗 2 點氣以一個附贈動作施放[燃燒之手]。","你可以消耗額外的氣以將[燃燒之手]作為更高環階的法術施放。你每額外消耗 1 點氣，就可以使該法術的環階提升 1 環。"]},{"id":"m470","b":"魔法","n":"陽光爆裂","c":1500,"req":"具有能力[【魔法】日光箭]","refs":[{"b":"魔法","n":"日光箭"}],"need":1,"t":["你獲得創造出一個將爆發出毀滅爆炸的光球的能力。以一個動作，你將用魔法創造出一個光球，並將它投擲到 60 尺內你所選擇的一點，它將在該處爆發成一個瞬間而致命的光輝球體。","每個處於該 10 尺半徑球體範圍內的生物都必須成功通過一次體質豁免，否則受到 3d6 光耀傷害。一個生物若處於不透光全掩護后方，則它將不需要進行此豁免檢定。","你可以借由消耗額外的氣以增加這個球體的傷害。你每消耗 1 點氣就可以增加 1d6 傷害。"]},{"id":"m471","b":"魔法","n":"日輪聖芒","c":2000,"req":"具有能力[【魔法】熱弧息]、[【魔法】陽光爆裂]、[【特殊】輝日護盾]其中兩個","refs":[{"b":"魔法","n":"熱弧息"},{"b":"魔法","n":"陽光爆裂"},{"b":"特殊","n":"輝日護盾"}],"need":2,"t":["以一個動作消耗 5 點氣，於 60 尺內的一點呼喚擁有太陽力量的光炮，每個點於該 30 尺半徑，半徑球體範圍內的生物都必須成功通過一次體質豁免，豁免失敗將受到 6d6 光耀傷害並且目盲一輪，此光炮的效果與傷害無視掩護；豁免成功則受到的傷害減半，且不會目盲。","你可以借由消耗額外的氣以增加這個光炮的傷害。你每消耗 2 點氣就可以增加 2d6 傷害。"]},{"id":"m472","b":"魔法","n":"天威日輪","c":2500,"req":"具有能力[【魔法】日輪聖芒]","refs":[{"b":"魔法","n":"日輪聖芒"}],"need":1,"t":["當你使用日光箭時，日光箭的傷害為最大值。"]},{"id":"m473","b":"魔法","n":"防護學者","c":1500,"t":["你習得防護系法術所必須花費 DP 減半。"]},{"id":"m474","b":"魔法","n":"奧法防護","c":1500,"req":"具有能力[【魔法】防護學者]","refs":[{"b":"魔法","n":"防護學者"}],"need":1,"t":["你可以在你周遭編織魔法以守護自己。","當你施放一個 1 環或更高環的防護系法術時，你可以同時利用該法術的一縷魔法在你身上創造出一道魔法防護結界，持續直到你完成一次長休。這道防護結界具有等同於你熟練五倍 + 你的智力調整值的生命值。每當你受到傷害時，這道防護結界將代替你承受傷害。若該傷害將這道防護結界的生命值歸零，則你將受到任何剩於的傷害。","當這道防護結界的生命值為 0，它將不能再吸收傷害，但它的魔法仍然保留。每當你再施放一個 1 環或更高環的防護系法術，防護結界將會回復等同於該法術環階二倍的生命值。","一旦你創造出防護結界，直到你完成一次長休之前你都不能再創造它。"]},{"id":"m475","b":"魔法","n":"防護精通","c":1000,"req":"具有能力[【魔法】防護學者]","refs":[{"b":"魔法","n":"防護學者"}],"need":1,"t":["當你施放一個在施放過程中需要你進行屬性檢定的防護系法術時（例如反制法術和解除魔法），你可以將你的熟練加值加入該屬性檢定中。"]},{"id":"m476","b":"魔法","n":"法術抗性","c":3500,"req":"具有能力[【魔法】奧法防護]和[【魔法】防護精通]","refs":[{"b":"魔法","n":"奧法防護"},{"b":"魔法","n":"防護精通"}],"need":2,"t":["你在對抗法術的豁免檢定中具有優勢。","此外，你對法術傷害具有抗性。"]},{"id":"m477","b":"魔法","n":"瞬時靜止","c":1500,"req":"具有能力[【特殊】時間變幻]","refs":[{"b":"特殊","n":"時間變幻"}],"need":1,"t":["以一個動作，你可以魔法性地迫使 60 尺內你可以看見的一個大型或更小的生物進行一次對抗等於你法術豁免 DC 的體質豁免檢定。若失敗，該生物將被禁錮於一個魔法力場中，直至你的下回合結束或者該生物受到任何傷害。當以此法被禁錮時，該生物陷入無力，並且速度被降至 0。","你可以使用這一特性等同於你智力調整值的次數（至少 1 次）。你在完成一次長休后回復所有已消耗的使用次數。"]},{"id":"m478","b":"魔法","n":"奧法停滯","c":1500,"req":"具有能力[【特殊】時間變幻]","refs":[{"b":"特殊","n":"時間變幻"}],"need":1,"t":["當你消耗一個 4[魔力]或更少的[魔力]來施展法術時，你可以將該法術的法力濃縮至一抹微塵中。該法術將凍結在施展的那一刻，並被保存在一個灰色的小珠中，持續一小時。這個小珠是一個擁有 15 AC 和 1 點生命值","的物件，並免疫毒素和心靈傷害。在持續時間結束或者珠子被摧毀時，它會在光芒一閃中消失，而法術將會失去。持握着小珠的生物可以使用他的動作來釋放其內的法術，隨后小珠將會消失。該法術使用你的法術攻擊加值和豁免 DC，而在其他方面視為由釋放它的生物施展。","在你以此特性創造一個小珠后，你在完成一次{#短休}或{#長休}前不能再次這樣做。"]},{"id":"m479","b":"魔法","n":"咒法學者","c":1500,"t":["你習得咒法系法術所必須花費 DP 減半。"]},{"id":"m480","b":"魔法","n":"次級咒喚","c":1000,"req":"具有能力[【魔法】咒法學者]","refs":[{"b":"魔法","n":"咒法學者"}],"need":1,"t":["你可以使用你的動作以喚出一個無生命物體，讓其出現在你手上、或出現在距離你 10 尺內你所能看見的一處未被占據空間的地面上。這個物體的大小在各邊不能超過 3 尺，重量不能超過 10 磅，且它的外形必須是一個你曾經見過的非魔法物體。這個物體可以明顯被看出是帶有魔法的，且它將散發出 5 尺的微光光照。","這個物體將在 1 小時之后，或當你再此使用此能力、它受到任何傷害、或它造成任何傷害時消失。"]},{"id":"m481","b":"魔法","n":"移行換位","c":1000,"req":"具有能力[【魔法】咒法學者]","refs":[{"b":"魔法","n":"咒法學者"}],"need":1,"t":["你可以使用你的動作以傳送最多 30 尺距離到一處你所能看見的未被占據空間。或者，你可以選擇範圍內一處被一個中型或小型生物給占據的空間。若該生物願意，你們兩個可以同時傳送，交換位置。","一旦你使用此能力，則直到你完成一次長休或施放一個消耗 1[魔力]以上的咒法系法術之前，你都不能再使用此能力。"]},{"id":"m482","b":"魔法","n":"高速換位","c":1500,"req":"具有能力 [【魔法】移行換位 ]","refs":[{"b":"魔法","n":"移行換位"}],"need":1,"t":["你的[移行換位]能力可以使用 [附贈動作] 來施展。"]},{"id":"m483","b":"魔法","n":"超速換位","c":2000,"req":"具有能力 [【魔法】高速換位 ]","refs":[{"b":"魔法","n":"高速換位"}],"need":1,"t":["你的[移行換位]能力可以使用 [反應] 來施展。"]},{"id":"m484","b":"魔法","n":"物體交換","c":1500,"req":"具有能力 [【魔法】移行換位 ]","refs":[{"b":"魔法","n":"移行換位"}],"need":1,"t":["你的[移行換位]能力的交換目標可以選擇中型或小型的物體。"]},{"id":"m485","b":"魔法","n":"咒法專注","c":2000,"req":"具有能力 [【魔法】咒法學者 ]","refs":[{"b":"魔法","n":"咒法學者"}],"need":1,"t":["當你 [專注] 於一個{#咒法系}{#法術}時，你的 [專注] 並不會因為受到傷害而被中斷。"]},{"id":"m486","b":"魔法","n":"強韌召喚","c":2500,"req":"具有能力 [【魔法】咒法學者 ]","refs":[{"b":"魔法","n":"咒法學者"}],"need":1,"t":["任何你以{#咒法系}{#法術}召喚或創造出的生物都將擁有額外 30 點[臨時生命值]。"]},{"id":"m487","b":"魔法","n":"預言學者","c":1500,"t":["你習得預言系法術所必須花費 DP 減半。"]},{"id":"m488","b":"魔法","n":"預兆","c":1000,"req":"具有能力[【魔法】預言學者]","refs":[{"b":"魔法","n":"預言學者"}],"need":1,"t":["未來一瞬的景象開始出現在你的意識中。","當你完成一次{#長休}時，骰二顆 d20，並將它們骰出來的數字記錄下來稱之為預言骰。你可以將你或一個你所能看見的生物所進行的任意攻擊檢定、豁免檢定、或屬性檢定的結果替換成其中一顆這些預言骰的結果。你必須在擲骰前選擇是否這麼做，且你每回合只能用這個方式替換擲骰結果一次。","每個預言骰只能被使用一次。當你完成一次長休時，你失去所有尚未被使用的預言骰。"]},{"id":"m489","b":"魔法","n":"預言專家","c":1500,"req":"具有能力[【魔法】預言學者]","refs":[{"b":"魔法","n":"預言學者"}],"need":1,"t":["施放預言系法術對你而言是那麼容易，以至於你只需要花費你一部份的施法能力。","當你使用法術位施放一個 2 環或更高環的預言系法術，你將回復等同於此環階一半的[魔力]。(向上取整)"]},{"id":"m490","b":"魔法","n":"高等預兆","c":1500,"req":"具有能力[【魔法】預兆]","refs":[{"b":"魔法","n":"預兆"}],"need":1,"t":["你夢中的景象變得更加清晰，更精確地在你的意識中描繪出了將要發生的一切。你為你的預兆能力的預言骰變為三顆骰。"]},{"id":"m491","b":"魔法","n":"預言家","c":2000,"req":"具有能力[【魔法】高等預兆]","refs":[{"b":"魔法","n":"高等預兆"}],"need":1,"t":["你夢中的景象變得更加清晰，更精確地在你的意識中描繪出了將要發生的一切。你為你的預兆能力的預言骰變為四顆骰。"]},{"id":"m492","b":"魔法","n":"惑控學者","c":1500,"t":["你習得惑控系法術所必須花費 DP 減半。"]},{"id":"m493","b":"魔法","n":"塑能學者","c":2000,"t":["你習得塑能系法術所必須花費 DP 減半。"]},{"id":"m494","b":"魔法","n":"塑形法術","c":2000,"req":"具有能力[【魔法】塑能學者]","refs":[{"b":"魔法","n":"塑能學者"}],"need":1,"t":["你可以在你塑能系法術的效果範圍內創造出相對安全的區域。","當你施放一個會影響你所能看見的其他生物的塑能系法術時，你可以從中選擇數量等同 1 + 該法術環階的生物。所選生物將自動成功通過對抗該法術的豁免檢定，且若它們原本在豁免成功時會受到一半的傷害，則它們改為不受任何傷害。","你能使用此能力的次數等於你的智力調整值（最少 1 次）。當你完成一次短休后，你回復所有已消耗的使用次數。"]},{"id":"m495","b":"魔法","n":"強力戲法","c":1500,"req":"具有能力[【魔法】塑能學者]","refs":[{"b":"魔法","n":"塑能學者"}],"need":1,"t":["即使生物避開了你傷害類戲法效果中最主要的沖擊，你仍能影響它們。","當一個生物成功通過一次對抗你戲法的豁免檢定，該生物仍會受到該戲法的傷害（若有）的一半，但並不會承受來自該戲法的額外效果。"]},{"id":"m496","b":"魔法","n":"強效塑能","c":1500,"req":"具有能力[【魔法】塑能學者]","refs":[{"b":"魔法","n":"塑能學者"}],"need":1,"t":["你可以將你的智力調整值加入任何你所施放的塑能系法術的其中一次傷害骰中。"]},{"id":"m497","b":"魔法","n":"超載魔導","c":2500,"req":"具有能力[【魔法】塑能學者]","refs":[{"b":"魔法","n":"塑能學者"}],"need":1,"t":["你可以提升你那些較簡單法術的威力。","當你施放一個環階在一環到五環之間，且會造成傷害的法術時，你可以讓該法術造成最大傷害。","當你第一次這麼做時，你不會承受任何負面效果。若你在完成一次長休之前再次使用此能力，你將在施放該法術后立刻受到消耗的[魔力] 2 倍的 D12 的闇蝕傷害。這個闇蝕傷害不可被減免。"]},{"id":"m498","b":"魔法","n":"重力井","c":1000,"req":"具有能力[【特殊】重力調節]","refs":[{"b":"特殊","n":"重力調節"}],"need":1,"t":["你學會了如何在一個活體上操縱重力：無論何時你對一個生物施展法術，只要該目標自願被移動，或是法術攻擊命中了該目標，亦或是該目標在對抗這道法術的豁免時失敗，你就能讓該目標朝着一個由你選擇且未被占據的空間移動 5 尺。"]},{"id":"m499","b":"魔法","n":"矢量操作","c":2000,"req":"具有能力[【魔法】重力井]","refs":[{"b":"魔法","n":"重力井"}],"need":1,"t":["位於你 60 尺內且你可見的生物被武器攻擊命中時，你能用你的反應加快或減慢這次攻擊的速度，使得被攻擊的目標額外受到或減少 1d10 的該武器類型所造成的傷害。","此外，如果一個位於你 60 尺內的生物遭受了墜落傷害，你能用你的反應動作來增加或減少這次墜落所造成的傷害，增加或減少值為 2d10。","你能使用此能力的次數等於你的智力調整值（最少 1 次）。當你完成一次長休后，你回復所有已消耗的使用次數。"]},{"id":"m500","b":"魔法","n":"事件視界","c":3000,"req":"具有能力[【特殊】重力調節-極]","refs":[{"b":"特殊","n":"重力調節-極"}],"need":1,"t":["以一個動作，你能魔法發散出由重力能量引起的強大力場，力場能把其他生物拖拽至多 1 分鐘，或在你的專注終止（如同你專注法術一樣）時結束。在持續時間內，當一個位於你 30 尺內，且與你敵對的生物開始回合時，該生物必須進行一次力量豁免對抗你的法術 DC。當豁免失敗時，該生物受到 1d10 力場傷害，並且移動速度降低至 0 尺，減速持續直到該生物的下一個回合開始。當豁免成功時，該生物受到一半的傷害，並且每移動一尺就需要額外花費 2 尺的移動力。","一旦你使用了此能力，你不能再次使用，直到你完成了一次長休，或花費 3[魔力]來再次使用。"]},{"id":"m501","b":"魔法","n":"擬似黑洞","c":3500,"req":"具有能力[【魔法】事件視界]","refs":[{"b":"魔法","n":"事件視界"}],"need":1,"t":["以一個動作對自身 150 尺內的一點發動，你能魔法地發散出由重力能量引起的強大力場，對此點周圍 60 尺球形內的所有單位進行一次 DC=你的法術的力量豁免，失敗則會向此點移動至撞上物體為止，並且受到 6D12 的力場傷害；成功則不會移動且不會移動且受到的力場傷害減半。","一旦你使用了此能力，你不能再次使用，直到你完成了一次長休。"]},{"id":"m502","b":"魔法","n":"幻術學者","c":1500,"t":["你習得幻術系法術所必須花費 DP 減半。"]},{"id":"m503","b":"魔法","n":"精通次級幻象","c":1000,"req":"具有能力[【魔法】幻術學者]","refs":[{"b":"魔法","n":"幻術學者"}],"need":1,"t":["你習得次級幻象戲法。若你已經知曉此戲法，則你習得另一個自選的戲法。(這不會使用你的法術容量)","當你施放次級幻象，你可以在一次施法中同時創造出聲音和影像。"]},{"id":"m504","b":"魔法","n":"可塑幻象","c":1500,"req":"具有能力[【魔法】幻術學者]","refs":[{"b":"魔法","n":"幻術學者"}],"need":1,"t":["當你施放一個持續時間為1分鐘或更久的幻術系法術時，只要你可以看見該幻象，你就可以使用你的動作以改變該幻象的性質（仍需遵守該法術對該幻象的基本屬性描述）。"]},{"id":"m505","b":"魔法","n":"幻象步","c":1500,"req":"具有能力[【魔法】幻術學者]","refs":[{"b":"魔法","n":"幻術學者"}],"need":1,"t":["機乎等同你對危險的本能反應，你可以在瞬間創造出一個你的幻象拷貝體。當一個生物對你進行一次攻擊檢定，你可以使用你的反應以在你和攻擊者之間插入該幻象拷貝體。該攻擊將自動失手，且該幻象將接着消散。","你能使用此能力的次數等於你的智力調整值（最少 1 次）。當你完成一次長休后，你回復所有已消耗的使用次數。"]},{"id":"m506","b":"魔法","n":"亦真亦幻","c":2000,"req":"具有能力[【魔法】幻術學者]","refs":[{"b":"魔法","n":"幻術學者"}],"need":1,"t":["你學會幻影魔法的奧秘，並能將之編入你的幻象中以賦予它們半真實的特性。當你施放一個 1 環或更高環的幻術系法術時，你可以選擇一個屬於幻象一部份的不可動且非魔法的物體，並讓該物體變為真實。你可以在法術持續期間在你的回合以一個附贈動作這麼做。該物體將保持真實存在並持續 1 分鐘。舉例來說，你可以創造出一道橫跨峽谷的幻象橋梁，並使它變為真實以讓你的隊友們通過。","該物體無法造成傷害、或以任何方式直接傷害任何人。"]},{"id":"m507","b":"魔法","n":"死靈學者","c":1500,"t":["你習得死靈系法術所必須花費 DP 減半。"]},{"id":"m508","b":"魔法","n":"不死奴僕","c":1500,"req":"具有能力[【魔法】死靈學者]","refs":[{"b":"魔法","n":"死靈學者"}],"need":1,"t":["每當你使用一個死靈系法術創造出一個不死生物時，它將獲得下列好處：","• 該生物的生命值最大值增加等同於你熟練值 5 倍的數值。","• 該生物將你的熟練加值加入它的攻擊傷害骰中。"]},{"id":"m509","b":"魔法","n":"變化學者","c":1500,"t":["你習得變化系法術所必須花費 DP 減半。"]},{"id":"m510","b":"魔法","n":"次級煉金","c":1000,"req":"具有能力[【魔法】變化學者]","refs":[{"b":"魔法","n":"變化學者"}],"need":1,"t":["你可以暫時地改變一個非魔法物體的物理性質，將它變成另一種物質。","你可以對一個完全由木、石（但非寶石）、鐵、銅、或銀所搆成的物體施展一項特殊的煉金進程，將它轉變成上述的另一種材質。你每花費 10 分鐘施展這個煉金進程，你就可以轉變最多 1 立方尺的材質。在 1 小時之后，或直到你失去你的專注（如同你專注於一個法術），該材質將會變回它原本的物質。"]},{"id":"m511","b":"魔法","n":"變化術精通","c":1500,"req":"具有能力[【魔法】變化學者]","refs":[{"b":"魔法","n":"變化學者"}],"need":1,"t":["你習得『變形術(Polymorph)』(這不會使用你的法術容量)","你可以施放變形術而無須消耗[魔力]。當你這麼做時，你只能以自己為目標，且只能轉變為一個挑戰等級為 1 或更低的野獸。一旦你用這個方式施放變形術，則直到你完成一次短休或長休之前你都不能再這麼做。不過你仍然可以借由消耗可用的[魔力]來正常地施放它。"]},{"id":"m512","b":"魔法","n":"祕法偏斜","c":1500,"t":["你學會編制你的魔法以讓你自己在對抗傷害時更加堅韌。當你被一次攻擊命中、或在一次豁免檢定中失敗時，你可以使用你的反應以使你的 AC 對該次攻擊獲得+2 加值，或在該豁免檢定中獲得+4 加值。","當你使用此能力，則直到你的下個回合結束前，你都無法施放戲法以外的法術。"]},{"id":"m513","b":"魔法","n":"力量湧動","c":1500,"req":"具有能力[【魔法】祕法偏斜]","refs":[{"b":"魔法","n":"祕法偏斜"}],"need":1,"t":["你可以將魔法能量保存在你體內以增強你往後施放的傷害性法術。這個能量保存的形式被稱作力量涌動。","你可以保存最多等同於你智力調整值數量的力量涌動（最少 1 點）。每當你完成一次長休，你所保存的力量涌動數量將回復至最大值。每當你成功以 (解除魔法 Dispel Magic) 或 (反制法術 Counterspell) 等方式結束一個敵方所施放法術，隨着你從你所破壞的法術中竊取魔法，你將獲得一點力量涌動。若你在結束一次短休時沒有任何力量涌動，你將獲得一點力量涌動。","每回合一次，當你以一個法術對一個生物造成傷害時，你可以消耗一點力量涌動以對目標造成額外的[力場傷害]。這個額外傷害等同於你熟練值的2 倍。"]},{"id":"m514","b":"魔法","n":"耐久之法","c":2500,"req":"具有能力[【魔法】祕法偏斜]","refs":[{"b":"魔法","n":"祕法偏斜"}],"need":1,"t":["你所導引的魔法能夠協助阻絕傷害。","當你 [專注] 於一個{#法術}時，你的{#AC}和所有{#豁免檢定}都獲得 +2 加值。"]},{"id":"m515","b":"魔法","n":"偏斜彈幕","c":1500,"req":"具有能力[【魔法】祕法偏斜]","refs":[{"b":"魔法","n":"祕法偏斜"}],"need":1,"t":["你的秘法偏斜變得充斥着致命魔法。","當你使用你的秘法偏斜能力時，你可以使魔法能量從你身上弧射而出。最多 3 個距離你 60 尺內，你所選擇且你能看見的生物將各自受到等同於熟練值 2 倍的[力場傷害]。"]},{"id":"m516","b":"魔法","n":"超魔法","c":2000,"t":["你獲得扭曲你的法術以使其符合你需求的能力。你獲得下列超魔法選項中的二個。","你施放一個法術時最多可以讓此法術使用等同於你魅力調整值數量（最少為 1)超魔法選項。","超魔法選項","• 謹慎法術. 當你施放一個會強迫其他生物進行豁免檢定的法術時，你可以保護其中一些生物不受該法術的完整威力影響。要這麼做，你得額外消耗 2[魔力]，並選擇最多等同於你魅力調整值數量的生物（最少一個生物）。被選擇的生物將在對抗該法術的豁免檢定中自動成功。","• 遠程法術. 當你施放一個射程為 5 尺或更遠的法術時，你可以額外消耗 1[魔力]以將該法術的射程變為二倍。當你施放一個射程為觸碰的法術時，你可以額外消耗 2[魔力]以將該法術的射程變為 30 尺。","• 強效法術. 當你在為法術骰傷害時，你可以額外消耗 1[魔力]以重骰最多等同於你魅力調整值數量的骰子（最少一顆）。你必須使用新的擲骰結果。","• 延時法術.當你施放一個持續時間為1分鐘或更久的法術時，你可以額外消耗 2[魔力]以將它的持續時間變為二倍，最久到 24 小時。","• 升階法術. 當你施放一個會強迫一個生物進行豁免檢定以抵抗它效果的法術時，你可以額外消耗 2[魔力]以讓一個該法術的目標在它對抗該法術的第一次豁免檢定中承受劣勢。","• 瞬發法術. 當你施放一個施法時間為 1 個主要動作的法術時，你可以額外消耗 2[魔力]以將它在這次施法的的施法時間變為 1 個附贈動作。","• 精妙法術. 當你施放一個法術時，你可以額外消耗 2[魔力]以施放它而無須提供任何姿勢或聲音搆材。","• 孿生法術. 當你施放一個射程不為自身，且在使用當前法術位時無法指定超過一個生物作為目標的法術時，你可以消耗等同於該法術環階數量的[魔力]以使用同個法術指定射程內的第二個生物作為目標（若該法術為戲法，則額外消耗 2[魔力]）。要符合條件，該法術必須要在使用當前法術位時無法指定超過一個生物作為目標。舉例來說，魔法飛彈和灼熱射線並不符合條件，但冰冷射線和幻色法球則可。","• 追蹤法術. 當你因法術進行一次攻擊檢定失手時，你可以使用 3[魔力]重投 d20。超魔法的追蹤法術與其他超魔法選項合用不會占用超魔法選項。","• 轉化法術. 當你施放一個能夠造成以下列表中類型傷害的法術時，你可以使用額外消耗 2[魔力]將其改為列表中的另一種傷害類型：酸蝕傷害、冰冷傷害、火焰傷害、閃電傷害、毒素傷害或雷鳴傷害。"]},{"id":"m517","b":"魔法","n":"進階超魔法","c":2500,"req":"具有能力[【魔法】超魔法]","refs":[{"b":"魔法","n":"超魔法"}],"need":1,"t":["你獲得扭曲你的法術以使其符合你需求的能力。你獲得下列超魔法選項中的二個。","超魔法選項","• 謹慎法術. 當你施放一個會強迫其他生物進行豁免檢定的法術時，你可以保護其中一些生物不受該法術的完整威力影響。要這麼做，你得額外消耗 2[魔力]，並選擇最多等同於你魅力調整值數量的生物（最少一個生物）。被選擇的生物將在對抗該法術的豁免檢定中自動成功。","• 遠程法術. 當你施放一個射程為 5 尺或更遠的法術時，你可以消耗 1 點術法點以將該法術的射程變為二倍。當你施放一個射程為觸碰的法術時，你可以額外消耗 2[魔力]以將該法術的射程變為 30 尺。","• 強效法術. 當你在為法術骰傷害時，你可以額外消耗 2[魔力]以重骰最多等同於你魅力調整值數量的骰子（最少一顆）。你必須使用新的擲骰結果。","• 延時法術.當你施放一個持續時間為1分鐘或更久的法術時，你可以額外消耗 2[魔力]以將它的持續時間變為二倍，最久到 24 小時。","• 升階法術. 當你施放一個會強迫一個生物進行豁免檢定以抵抗它效果的法術時，你可以額外消耗 2[魔力]以讓一個該法術的目標在它對抗該法術的第一次豁免檢定中承受劣勢。","• 瞬發法術. 當你施放一個施法時間為1個動作的法術時，你可以額外消耗 2[魔力]以將它在這次施法的的施法時間變為 1 個附贈動作。","• 精妙法術. 當你施放一個法術時，你可以額外消耗 2[魔力]以施放它而無須提供任何姿勢或聲音搆材。","• 孿生法術. 當你施放一個射程不為自身，且在使用當前法術位時無法指定超過一個生物作為目標的法術時，你可以消耗等同於該法術環階數量的術法點以使用同個法術指定射程內的第二個生物作為目標（若該法術為戲法，則額外消耗 2[魔力]）。要符合條件，該法術必須要在使用當前法術位時無法指定超過一個生物作為目標。舉例來說，魔法飛彈和灼熱射線並不符合條件，但冰冷射線和幻色法球則可。","• 追蹤法術. 當你因法術進行一次攻擊檢定失手時，你可以使用 3[魔力]重投 d20。你必須使用重投的結果。超魔法追蹤法術可以與其他超魔法選項合用。","• 轉化法術. 當你施放一個能夠造成以下列表中類型傷害的法術時，你可以使用額外消耗 2[魔力]將其改為列表中的另一種傷害類型：酸蝕、冰冷、火焰、閃電、毒素或雷鳴。"]},{"id":"m518","b":"魔法","n":"扭曲爆裂","c":3500,"t":["你能夠解放你異質的力量，從而制造扭曲空間的異常現象。","以一個動作，你可以傳送到 120 尺內你可見的一個未被占據的位置，然后你消失位置 30 尺內的生物必須進行一次力量豁免(DC=8+你熟練值的 2 倍)，失敗受 4d10 力場傷害並被立即拉向你原本的位置或最近的一個未被占據的位置，成功半傷且不受拉扯。","一旦你使用了此能力，你在完成一次長休息之前必須消耗 5[魔力]以再次使用此能力。"]},{"id":"m519","b":"魔法","n":"律令之壁","c":2500,"t":["你可以利用事物的壯麗聯系為一個生物激發閃爍的秩序之盾。以一個動作，你可以使用 1~5[魔力]創造出一個環繞你或 30 尺內一個你可見的生物的魔法屏障。此屏障持續存在直到你完成一次長休或直至你再次使用此能力。屏障具有等同於你所消耗[魔力]的 D8 骰。當被守護的生物受到傷害時，其可以消耗任意數量的這些 D8 骰，並使該傷害減少擲出結果的數值。"]},{"id":"m520","b":"魔法","n":"序列意志","c":3500,"t":["你獲得了將你的意識和機械境無盡的計算達成同步的能力。","以一個附贈動作，你可以在 1 分鐘內進入此種狀態。在此期間，對你進行的攻擊免受優勢的影響，且每當你進行一次攻擊檢定、屬性檢定或豁免檢定時，你可以將 d20 擲出的 9 或以下的數值視為 10。","一旦你使用了此能力，你在完成一次長休息之前必須消耗 5[魔力]以再次使用此能力。"]},{"id":"m521","b":"魔法","n":"元素親合","c":2000,"req":"具有能力[【通用】龍之血脈]","refs":[{"b":"通用","n":"龍之血脈"}],"need":1,"t":["當你施放一個會造成與你龍之血脈對應傷害類型相同的傷害的法術時，你可以將你的魅力調整值加入該法術的其中一個傷害骰中。","你獲得與你龍之血脈相應傷害類型相同的抗性。"]},{"id":"m522","b":"魔法","n":"狂野魔法浪湧","c":2000,"t":["你的施法可以釋放出未經馴服的魔法浪涌。緊接在你施放一個 1 環或更高環的法術時，DM 可以要求你骰一顆 d20。若你骰出了 1，則擲骰使用狂野魔法浪涌表以創造出一個隨機的魔法效果。一道狂野魔法浪涌在每回合可以發生一次。","若狂野魔法效果為一個法術，則它太過狂野以至於它無法被所有能力的效果影響。若它原本需要專注，則它在這個情況下也不需要專注；該法術將持續到它的完整持續時間。"]},{"id":"m523","b":"魔法","n":"狂野轟擊","c":1500,"req":"具有能力[【魔法】狂野魔法浪湧]","refs":[{"b":"魔法","n":"狂野魔法浪湧"}],"need":1,"t":["你法術的傷害性能量明顯加劇。","當你會一個法術擲骰決定傷害，且其中任何一顆骰子骰出了最大的骰面，則從這些骰子中選擇一顆，重骰它並將其擲骰結果加到傷害中。你在每個回合只能使用此能力一次。"]},{"id":"m524","b":"魔法","n":"法術破壞者","c":1500,"req":"具有能力[【特殊】神力引導﹝奧秘阻絕﹞]","refs":[{"b":"特殊","n":"神力引導﹝奧秘阻絕﹞"}],"need":1,"t":["當你使用法術回復一個盟友的生命值，你也可以選擇結束一個作用於該生物上的法術。你所結束法術的花費[魔力]必須等於或低於你用以施放該回復生命值的法術所使用的[魔力]。"]},{"id":"m525","b":"魔法","n":"奧秘神導","c":2000,"req":"具有能力[【特殊】神力引導﹝奧秘阻絕﹞]","refs":[{"b":"特殊","n":"神力引導﹝奧秘阻絕﹞"}],"need":1,"t":["你將你的感知調整值加入任何你使用法術所造成的所有傷害與生命值回復中。"]},{"id":"m526","b":"魔法","n":"二重死靈","c":1500,"req":"具有能力[【特殊】神力引導﹝死亡之觸﹞]","refs":[{"b":"特殊","n":"神力引導﹝死亡之觸﹞"}],"need":1,"t":["當你施展一個通常指定一個生物為目標的死靈系戲法時，則該法術現在可以同時指定施法距離內兩個相互之間距離不超過 5 尺的生物。"]},{"id":"m527","b":"魔法","n":"精通-二重死靈","c":2500,"req":"具有能力[【魔法】二重死靈]","refs":[{"b":"魔法","n":"二重死靈"}],"need":1,"t":["當你施展一個通常指定一個生物為目標的死靈系五環(含)以下法術時，則該法術現在可以指定施法距離內兩個相互之間距離不超過 5 尺的生物。"]},{"id":"m528","b":"魔法","n":"律法化身","c":1500,"req":"具有能力[【特殊】神力引導﹝秩序之令﹞]","refs":[{"b":"特殊","n":"神力引導﹝秩序之令﹞"}],"need":1,"t":["你變得相當熟練於引導魔法能量以強迫他人。","若你使用一個 1 環或更高環的法術位施放一個惑控學派的法術，只要該法術原本的施法時間為1個動作，你就可以將該法術的施法時間變為 1 個附贈動作。","你可以使用這個能力的次數等同於你的感知調整值（最少一次），且你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m529","b":"魔法","n":"神力引導﹝召喚假體﹞","c":1500,"req":"具有能力[【特殊】神力引導]","refs":[{"b":"特殊","n":"神力引導"}],"need":1,"t":["你可以使用你的神力引導以創造一個你自己的幻象假體。","以一個[主要動作]消耗一個神力引導，你創造一個你自己的完美幻象，持續 1 分鐘，或直到你失去你的專注（就如同你專注於法術一樣）。這個幻象會出現在一個距離你 30 尺內你所能看見的未被占據空間。在你的回合以一個附贈動作，你可以使幻象移動最多 30 尺到一處你所能看見的空間，但它必須維持在距離你 120 尺內的位置。","在持續期間，你可以如同你處於幻象的位置來施放法術，但你必須使用你自己的感官。此外，當你和你的幻象都位於一個可以看見幻象的生物 5 尺範圍內，由於幻象對目標所造成的干擾，你在對該生物進行的攻擊檢定中具有優勢。"]},{"id":"m530","b":"魔法","n":"強化假體","c":3000,"req":"具有能力[【魔法】神力引導﹝召喚假體﹞]","refs":[{"b":"魔法","n":"神力引導﹝召喚假體﹞"}],"need":1,"t":["當你使用召喚假體時，你可以創造出最多四個你自己的幻象假體，而非一個。在你的回合以一個附贈動作，你可以讓任意數量的假體移動最多 30 尺距離，到最遠 120 尺的範圍內。"]},{"id":"m531","b":"魔法","n":"至聖斬","c":2000,"t":["當你使用一次近戰武器攻擊命中一個生物時，除了武器傷害以外，你可以消耗 2[魔力]以對目標造成額外的光耀傷害。這個額外傷害在消耗 2[魔力]時為 2d8 點，每額外多消耗 1[魔力]則每環再加上 1d8 點傷害，最高至 5d8。","若目標為不死生物或邪魔，則至聖斬傷害再增加 1d8 點，最高至 6d8。"]},{"id":"m532","b":"魔法","n":"淨化之觸","c":2500,"t":["可以使用你的動作以結束一個作用於你自己或一個你所碰觸自願生物的法術。","你可以使用這個能力的次數等同於你的魅力調整值（最少一次）。","你在完成一次長休后回復所有你花費掉的次數。"]},{"id":"m533","b":"魔法","n":"邪魔斬","c":1500,"req":"具有能力[【特殊】神力引導﹝控制亡靈﹞]","refs":[{"b":"特殊","n":"神力引導﹝控制亡靈﹞"}],"need":1,"t":["當你使用一次近戰武器攻擊命中一個生物，除了武器傷害以外，你可以消耗 2[魔力]以對目標造成額外的闇蝕傷害。這個額外傷害在消耗 2[魔力]時為 3d8，額外多消耗 1[魔力]則每環再加上 1d8 傷害，最高至 6d8。"]},{"id":"m534","b":"魔法","n":"荒野夥伴","c":1500,"req":"具有能力[【通用】荒野形態]","refs":[{"b":"通用","n":"荒野形態"}],"need":1,"t":["你獲得召喚呈現動物形態的精魂的能力，以一個動作，你能夠消耗一次荒野形態的變形使用次數來施放一次無需材料的[尋獲魔寵(Find Familiar)]法術。你以此方法施放該法術時，魔寵的類型是精類而不是野獸。"]},{"id":"m535","b":"魔法","n":"野獸施法","c":2500,"req":"具有能力[【通用】荒野形態]","refs":[{"b":"通用","n":"荒野形態"}],"need":1,"t":["你可以在處於荒野形態所變成的任何型態時施放你的有些法術。你可以在處於野獸型態時運法術的姿勢和聲音構材，但你無法提供材料構材。"]},{"id":"m536","b":"魔法","n":"月光與陰影之家","c":2000,"t":["任何你所在的地方都可以是你的家。","在短休或長休期間，你可以呼喚來自薄暮庭院的幽影力量以協助你守護你暫時的歇息。在休息開始時消耗 3[魔力]，你觸碰空間內的一點，且一個隱形，30 尺半徑球體的魔法能量將會以該點為中心出現。將球體區域籠罩在全掩護之下。","當處於球體區域內，你和你的盟友將在敏捷（隱匿）檢定和感知（感知）檢定中獲得+5 加值，且任何球體內明火所散發出的光照都無法被從外側看見。","這個球體將在休息結束或你離開球體時消失。"]},{"id":"m537","b":"魔法","n":"夢境旅者","c":2500,"t":["妖精荒野的魔法賦予你以心靈或身體穿梭夢境的能力。","你習得『託夢術(Dream)』（以你作為信使）、『探知(Scrying)』、『傳送法陣(Teleportation Circle)』三個法術。(這不會使用你的法術容量)","當你完成一次短休，你可以施放下列其中一個法術，無須消耗[魔力]或需求材料搆材：『託夢術』（以你作為信使）、『探知』或『傳送法陣』。一旦你使用此能力，直到你完成一次長休之前你都不能再使用它。","這個『傳送法陣』的使用方式是特別的。它所打開的傳送門並非通往一個永久傳送法陣，而是通往你在當前存在位面中最后一次完成長休的地點。若你在當前位面中尚未進行過長休，則此法術將失敗，但使用次數並不會被浪費。"]},{"id":"m538","b":"魔法","n":"千面相","c":2000,"t":["你學會以更精細的方式用魔法改變自己的身體型態。","你習得『變造自身 Alter Self』法術。(這不會使用你的法術容量)","你可以隨意施放『變造自身』法術。"]}],"specialists":[{"n":"屬性值增加","t":["你獲得 6 點可自由分配的屬性值，你不能透過這個 [精通能力 Specialist] 將一個屬性值提升至超過 20。"]},{"n":"極限突破:力量","t":["角色的屬性值:力量增加 4 點，你能透過這個 [精通能力 Specialist] 將此屬性值提升至超過 20。"]},{"n":"極限突破:敏捷","t":["角色的屬性值:敏捷增加 4 點，你能透過這個 [精通能力 Specialist] 將此屬性值提升至超過 20 。"]},{"n":"極限突破:體質","t":["角色的屬性值:體質增加 4 點，你能透過這個 [精通能力 Specialist] 將此屬性值提升至超過 20。"]},{"n":"極限突破:感知","t":["角色的屬性值:感知增加 4 點，你能透過這個 [精通能力 Specialist] 將此屬性值提升至超過 20。"]},{"n":"極限突破:智力","t":["角色的屬性值:智力增加 4 點，你能透過這個 [精通能力 Specialist] 將此屬性值提升至超過 20 。"]},{"n":"極限突破:魅力","t":["角色的屬性值:魅力增加 4 點，你能透過這個 [精通能力 Specialist] 將此屬性值提升至超過 20 。"]},{"n":"生命結晶","t":["你的最大 [生命值 Hit Point] +50。"]},{"n":"逐戰之財","t":["每次戰鬥結束時，你額外獲得 100 [Deep point (DP)]。"]},{"n":"斬獲之財","t":["當你使一個{#小型}型以上的生物生命值變為 0 時，你獲得 100×該生物物挑戰等級的 [Deep point (DP)] 。","若該生物挑戰等級小於 1 ，則視為 0，不獲得額外 [Deep point(DP)] 。"]},{"n":"二重屬性豁免","t":["你獲得所選的兩種屬性豁免熟練。"],"opt":"(力量/敏捷/體質/智力/感知/魅力)與(力量/敏捷/體質/智力/感知/魅力 )"},{"n":"四類技能熟練","t":["你獲得所選的 4 個 [技能 Skills] 熟練。"],"opt":"XX(技能)、XX(技能)、XX(技能)、XX(技能)"},{"n":"二類技能專精","t":["你獲得所選的 2 個 [技能 Skills] 熟練使其變為 [技能 Skills] 專精。"],"opt":"XX(技能)、XX(技能)"},{"n":"外交官","t":["你習得 3 種 [語言和文字] 。"]},{"n":"工具人","t":["你獲得 2 種{#工具組}熟練。"]},{"n":"目光如炬","t":["你獲得 120 尺的 [黑暗視覺 Darkvision] 。","你的 [黑暗視覺 Darkvision] 不會因為{#法術}效果失效。","如你已經擁有 [黑暗視覺 Darkvision] 則你的 [黑暗視覺 Darkvision] 增加 60 尺。"]},{"n":"荒野之體","t":["你獲得 [【通用】荒野形態] 的能力效果做為你的 [特性] 使用。","如果你已經有此能力 [【通用】荒野形態] 的變形次數增加 2 次。"]},{"n":"動作如潮","t":["在你的回合在你完成原本的 [主要動作 Actions] 和可能的 [附贈動作 Bonus Action] 之後，另外再採取一次額外的[主要動作 Actions]。","你必須完成{#短休}後才能再次使用此能力。","當你擁有多個動作如潮的[精通能力 Specialist]時你可以在一次前使用動作如潮 X 次，但同個回合只能使用一次。 (X 為你動作如潮的 [精通能力 Specialist] 的次數)"]},{"n":"警覺","t":["經常對危機保持警惕，讓你獲得下列好處：","• 你的 [先攻 Initiative] 獲得+5 加值。","• 當你意識清醒時不會被 [突襲 Surprise] 。","• 其他生物對你進行的攻擊檢定並不會因為你看不到它而獲得 [優勢 Advantage] 。"]},{"n":"氣運過人","t":["你獲得 [【通用】幸運] 的能力效果做為你的特性使用。","如果你已經有此能力[幸運點]的數量 +3。"]},{"n":"機會主義","t":["當你在 [技能 Skills] 檢定具有 [優勢 Advantage] 時，此次技能檢定額外 2d6 獲得的加值。"]},{"n":"額外攻擊","t":["每當你在自己回合以 [主要動作 Actions] 執行攻擊動作時，你的攻擊次數 +1 。"]},{"n":"武器重擊","t":["當你使用武器攻擊， [重擊 Critical Hit] 閥值 -1 。"]},{"n":"鐵壁反震","t":["你能以純粹的力量與堅毅來抵抗某些範圍效果，例如:巨獸的衝擊波或地震術法術。","當你成為一個允許你進行{#力量豁免}以僅承受一半傷害的效果的目標時，你改為在豁免成功時不受任何傷害，且在豁免失敗時僅承受一半傷害。"]},{"n":"反射閃避","t":["可以靈活地躲開某些範圍效果，例如: 紅龍的火焰吐息或閃電束法術。","當你成為一個允許你進行{#敏捷豁免}以僅承受一半傷害的效果的目標時，你改為在豁免成功時不受任何傷害，且在豁免失敗時僅承受一半傷害。"]},{"n":"鐵軀抗擊","t":["你能以堅韌的體質來抵抗某些範圍效果，例如: 毒霧、寒冰暴或震盪衝擊。","當你成為一個允許你進行{#體質豁免}以僅承受一半傷害的效果的目標時，你改為在豁免成功時不受任何傷害，且在豁免失敗時僅承受一半傷害。"]},{"n":"思維庇護","t":["你能以敏銳的智慧與冷靜的分析來化解某些範圍效果，例如: 幻象衝擊或心靈震盪。","當你成為一個允許你進行{#智力豁免}以僅承受一半傷害的效果的目標時，你改為在豁免成功時不受任何傷害，且在豁免失敗時僅承受一半傷害。"]},{"n":"預兆迴避","t":["你能以敏銳的感知與直覺來化解某些範圍效果，例如: 隱匿的陷阱、爆裂或自然災害的波及。","當你成為一個允許你進行{#感知豁免}以僅承受一半傷害的效果的目標時，你改為在豁免成功時不受任何傷害，且在豁免失敗時僅承受一半傷害。"]},{"n":"魅力護壁","t":["你能以強大的魅力與精神意志來抵抗某些範圍效果，例如: 心靈衝擊或支配系法術。","當你成為一個允許你進行{#魅力豁免}以僅承受一半傷害的效果的目標時，你改為在豁免成功時不受任何傷害，且在豁免失敗時僅承受一半傷害。"]},{"n":"捉摸不定","t":["是如此的難以捕捉以至於攻擊者很少有辦法在對付你時取得 [優勢 Advantage] 。","當你不處於 [無力 Incapacitated] 狀態時，對你進行的所有攻擊檢定都不具有 [優勢 Advantage] 。"]},{"n":"偷襲技巧","t":["你獲得 [【靈敏】偷襲 Ⅰ] 的能力效果做為你的 [特性] 使用。","如果你已經有此能力 [【靈敏】偷襲 Ⅰ]你的 [偷襲骰] 增加 2 顆。"]},{"n":"機動性","t":["你特別地迅速而靈巧。你獲得下列好處：","• 當你採取 [疾走 Dash] 動作時，該回合內的 [困難地型 Difficult Terrain] 不會消耗你額外的移動速度。","• 當你對一個生物進行近戰攻擊后，無論你命中與否，你在該回合都不會再引發該生物的 [藉機攻擊 Opportunity Attack]。"]},{"n":"多列思緒","t":["你獲得 1 個額外的 [反應 Reactions] ，但不能在同一個回合使用。"]},{"n":"魔力之體","t":["你的 [魔力 Magic Point (MP)] 上限 +10 。"]},{"n":"法術倉庫","t":["你的 [法術容量] 增加 10 個。"]},{"n":"術法學者","t":["你在學習{#法術}時的所需的 [Deep point(DP)] 減半。"]},{"n":"邪魔韌性","t":["你可以在完成一次{#長休}時選擇一種傷害類型。你獲得對該傷害類型的抗性，持續直到你使用此能力再選擇一種不同的傷害類型為止。","當你擁有多個[邪魔韌性]的 [精通能力 Specialist] 時你可以在一次{#長休}時多個傷害類型，選擇的個數等同於 [精通能力 Specialist]-[邪魔韌性]的數目。","魔法武器或銀制武器所造成的 [揮砍傷害 Slashing] 、 [鈍擊傷害 Bludgeoning] 、 [穿刺傷害 Piercing] 將忽略此 [抗性 Resistance] 。"]},{"n":"戰鬥施法者","t":["你受訓於混亂戰場的中心施展處{#法術}，學習這項技巧讓你獲得下列好處:","• 當你受到傷害時，你在為維持{#法術} [專注 Concentration] 而進行的{#體質豁免}檢定上有 [優勢 Advantage] 。","• 即使你單手或雙手持有武器或{#盾牌}，你也可以做出{#法術}所要求的{#姿勢}構材。","• 當一個敵意生物的移動觸發了你的[藉機攻擊 Opportunity Attack] ，你可以使用你的 [反應 Reactions] 以對該生物施展{#法術}，而非進行一次[藉機攻擊 Opportunity Attack] 。該法術的施法時間必須為 1 個 [主要動作 Actions] ，且只能以該生物為目標。"]},{"n":"氣脈貫通","t":["你獲得 [【特殊】氣] 的能力效果做為你的特性使用。","如果你已經有此能力 [【特殊】氣] 你的氣的數量上限 +5 。"]},{"n":"不屈意志","t":["當你 [生命值 Hit Point] 降至 0 時，你可以進行一次 DC 15 {#體質豁免}，成功則生命值降至 1 且獲得最大 [生命值 Hit Point] 一半的 [臨時生命值 Temporary Hit Point] ，直到你的下一個回合結束。","你必須完成{#長休}後才能再次使用此能力。","當你擁有多個[不屈意志]的 [精通能力 Specialist] 時你可以在一次{#長休}前使用[不屈意志] X 次，但同個回合只能使用一次。","( X 為你[不屈意志]的 [精通能力 Specialist] 的次數)"]},{"n":"死線回魂","t":["當你在死亡豁免檢定中成功時，你可以立即獲得 1 點 [生命值 Hit Point] ，並立刻恢復意識，同時，你的 [力竭 Exhaustion] 等級額外增加一級。","(即 [力竭 Exhaustion] 二級)"]},{"n":"同調超越","t":["你與魔法物品的{#同調}數目上限 +1 。"]},{"n":"額外能力","t":["你獲得 2 個自選的 [能力] 作為你的 [特性] 使用。但須符合 [能力] 的規定與該[能力]的前置條件。","以此效果獲得的能力不會獲得額外最大 [生命值] 與 [魔力] 成長"],"opt":"XX(能力) 與 XX(能力)"}]};
